/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070926-8","meetingId":"h19-cm09","date":"2007年9月26日","dateIso":"2007-09-26","committee":"建設委員会","time":"午前１０時０２分～午後４時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"委員長、冒頭に委員会運営について一言いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"すみません。今日の委員会ですけれども、資料の配付が２日前ということですが、再開発のほうは昨日、耐震化促進計画については、つい１５分前に配られたということなので、その理由を説明いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"活発な委員会を進めるためにも、今まで２日前に資料を出して委員会を行ってきたという流れの中で、今回、理由は今ご説明がありましたけれども、ぜひ２日前に資料は出していただきたいと思うのと、とりわけ、後でご説明がありますけれども、耐震化促進計画については大事な問題だと思いますので、ぜひ今日の委員会だけで終わることなく、次回しっかり改めて時間をとって行うべきだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"}]},{"id":"topic-02","title":"に入ります。 (1)の戸越幹線中流域浸水対策事業説明会の開催","agenda":"に入ります。 (1)の戸越幹線中流域浸水対策事業説明会の開催","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"その辺の数というんですか。そこら辺をちょっとご意見を聞いて検討というか、要は雨水５０mmに対応ということですが、生活排水がどんどん増えることによって、今回それでも問題ないような戸越幹線中流域の浸水対策ということで、そこら辺は計算に入っているんでしょうか。その辺をちょっとお聞かせください。","respondent":"家壽田下水道河川課長","answer":"今、委員ご質問の件ですけれども、５０mmの計画の中に生活排水の汚水量が含まれております。これにつきましては、一般的に５０mmのときにどれぐらいの比率が汚水と雨水になるかですが、汚水が仮に１としますと、雨水が７０ぐらいで考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"この出席者が８名ということですけれども、説明会の周知の方法はどうだったのか聞かせていただきたいのと、あと、この場所に貯留管方式ということですけど、今後この方式でこういう対策を行う計画みたいなのはあるのかないのか、教えていただけますか。","respondent":"家壽田下水道河川課長","answer":"説明会の周知方法についてですけれども、７月３１日に地域センターにビラを持ち込みまして、５町会の回覧板、それから掲示板に掲載しております。８月１７日には路上工事が発生しますお宅の、まさに近接する家屋には直接ビラも配っておりまして、周知を図っております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"第１回定例会に契約議案が出てくるということで、３月中に工事契約をされるということなんですが、最終本会議が多分３月の終わり、２７日か２８日なのかなと思っています。それが４月１日か２日じゃ、年度的に書くんだったら、これは平成２０年度から２１年度でいいわけだよね。それが２５カ月だと、平成２２年度の４月になっちゃまずいと思われているのか、教えてもらいたい。","respondent":"家壽田下水道河川課長","answer":"発注方法等の２年債務にするのか３年債務にするのかにつきましては、受託事業ですので、現在、東京都の下水道局と協議をしておりまして、できれば平成１９、２０、２１年の３年間で工事をするということで考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"三上委員","kind":"質問","question":"そうでなくて、もうこういう説明会をやって、それからいよいよこういう話が始まるぞとなって、それからまたああでもないこうでもないと始まるのでは、過去のそういう騒動が何の知識、知恵にもならないようなことで終わってしまうようなことであれば、この今の契約の案件にしても２５カ月で終わるという話ではなくなってくるということになるわけですから、そういうあたりの地元の理解度。","respondent":"家壽田下水道河川課長","answer":"ただし、水をためるときには、空気を抜いていただきませんと水が入っていきませんので、その空気の置換というものを戸越銀座通りのわきからぶつけてやる計画になっておりますので、このときに若干地上での工事が出てくるということで、地元でも説明させていただきましたけれども。","voiceIndex":17,"id":"exchange-007"},{"speaker":"三上委員","kind":"意見","question":"今のところそうなんですよ。ただ、現実にここの場所と特定した場合、そこから始まるんですよね。だから、この工事期間中は水が出ないように考えるのは当たり前であるけれども、そういうことがないように将来的なことをやるためにここに必要なんだということを今の段階からそこの場所に対しては説明しない限り、こういうところから反対運動が起きてくるんですよ。ぜひお願いしたいと思います。","respondent":"家壽田下水道河川課長","answer":"今のまさに工事をやるんだというイメージは、先ほどビラを配布したというところで、路上工事を予定するところについては、それに関して既にビラを配っておりまして、その方々が必ず全員出てきたわけではありませんけれども。","voiceIndex":19,"id":"exchange-008"}]},{"id":"topic-03","title":"目黒川親水護岸整備工事","agenda":"目黒川親水護岸整備工事","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけ意見だけ述べさせていただきたいと思います。この公園は、きのうも言いましたけれども、開発事業者のクオリティーを上げるためのものであり、間違っていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"浮き桟橋までおりる護岸は、これで見ると、どこかを乗り越えていくわけだけれども、そのときの階段は水かさの違いもあるんだろうから、例えばこの護岸に沿って階段をつけるとか、そうすればどこの高さでも浮き桟橋を使って船で避難するとか、災害のときにいろいろなことが考えられるわけだけれども、その階段みたいなものもかいていないんだけれども、その２点を教えてもらいたいんですが。","respondent":"青木都市開発課長","answer":"ご指摘のとおり、そういった浮き桟橋を出し入れして使うことになるんですけれども、この絵にはのっかっておりませんけれども、先ほどご説明した三角形の陸地部分、民間事業者側で整備してもらいます提供公園の中に地域交流施設のようなものをつくる予定でございまして。","voiceIndex":26,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"しながわ水族館なんかもそういう形になっていますよね。今言ったはしごという壁沿いの部分というのは、実際に災害が起こって、全部道路が使えない。災害が何か起きたときには。そこら辺の河川管理者との話の中で、影響が今あるという話なのか、どうなのか。船に近づけないんだから、そういう問題じゃないと思うんだけど、そこら辺のところをもう１回ちょっと教えてもらいたい。その階段の部分だけ。","respondent":"青木都市開発課長","answer":"この件につきましては、工事は発注いたしますけれども、最終的な護岸を削るというご提案に対してはおこたえできかねると思うんですけれども、何らかの安全なタラップ、おりていく方法論については、その詳細な検討の中で最終的にしつらえていきたいというのが現状です。","voiceIndex":28,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"護岸を削らなくてはならないとは思っていないんだけど、それに足すだけでも階段はできると思うし、ただ、水の流れの問題はいろいろと考えていただかなくてはならないけれども、本当に積極的に使うというか、災害があったときに何が大切かということを考えるのであれば、そういうことを準備しておくというのが私は本来だと思うので、ぜひお願いだけしておきますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"そういう中にあって、こういう構造的な部分というのがなぜ考えられたのか、これが１つですね。人が通れるところは満潮時に水があふれてくる可能性もあるのかないのか、それはちょっとわからないんですけれども、そういう説明がないので、そこらあたりは本当に満潮時の時点でその地点から何ｍ上の部分にこの人が通れる平面があるのかというのを、もう１回ご説明していただけませんか。","respondent":"青木都市開発課長","answer":"そういったことから、いろいろと地元からもご要望がありましたし、私どももできるだけ親水性の高いものでいいものをつくっていきたいということを考え、なおかつ防災機能もということでいろいろ検討してきたんですけれども、現実的に現地の状況、広さ。","voiceIndex":31,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"完成後に区が引き継ぐということは、公園全体は区立公園になって、区がその管理をするということでよろしいんでしょうか。","respondent":"青木都市開発課長","answer":"そのとおりです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"それで、この三角形のところは業者の土地で業者が整備するということですが、でき上がったら一体的な公園として使われるというので、使い勝手なんていうのを一体的にデザインされたほうがいいのではないかと思うのですけれども、それはここでかいていないだけで、一応そうした話はきちんとできていて、全体のデザインというのがある中で切り取ったここだけを今回示しているということでよろしいんでしょうか。","respondent":"青木都市開発課長","answer":"全体の絵は再開発事業の指導という観点からも建設委員会でご指導いただくべき案件ですので、ある一定の時期にこの公園全体の計画概要がまとまりましたら、改めてご報告させていただきたいと考えています。","voiceIndex":35,"id":"exchange-015"}]},{"id":"topic-04","title":"区民住宅ファミーユ西五反田西館の指定管理者募集","agenda":"区民住宅ファミーユ西五反田西館の指定管理者募集","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今、現在６社ほど参加の話があって、締め切らせていただきましたというお話でしたけれども、書類審査、ヒアリング審査は選定委員会の中でどのような審査を行うのか、教えていただけますか。","respondent":"齋藤住宅課長","answer":"審査の具体的な個々の中身につきましては、地方自治法の契約締結権の中身になりますので、大まかなところでいわゆる企業としての執行体制ですとか、就業者は現場でどのような方法で取り組んでいるか、現状どうやってどのような管理体制をとっているかとか。","voiceIndex":43,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"今、審査の中身の大まかなご説明がありましたけれども、この審査の中で指定管理者の候補者を選定するわけだと思うんですけども、その指定管理者となる団体について、例えばその団体の、会社だったら社長、団体だったら代表者、その役員の中に、例えば品川の区議会議員がいたり、現職の区長や三役がいたり、また配偶者、親族、その他含めていろいろな者がいるという法人や団体については。","respondent":"齋藤住宅課長","answer":"もし、地方自治法に規定されている支配人に当たる者が議員や首長の親族にいるというのであれば、排除されますので契約はできないことになります。","voiceIndex":45,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"つまり、議員だったり三役だったり、教育長も含めて、議決や契約の締結に直接、間接的に関与する立場ですから、その権限が鈍るというか、恣意的に用いられてはだめだということで、制限されているわけですけれども、この地方自治法の請負禁止規定というのは、指定管理者制度にも適用されるものなのか、そこを教えていただけますか。","respondent":"齋藤住宅課長","answer":"適用されます。民法でいう請負よりも概念が広うございまして、継続的に利益を受け続ける立場にある者が契約の相手方になってはならない、排除しなさいですので、本件でも同様に解釈しています。","voiceIndex":47,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"いわゆる請負には当たらないという話を聞いたことがあるんですよね。そうなると、今はなっていないとは思いますけど、今の制度のままでは指定管理者として指定される団体の長、社長だったり、取締役だったりというのは、区議会議員や区長がなる道を残しているんじゃないのかなという気がしてならないんですけれども、それについてはいかがでしょうか。","respondent":"齋藤住宅課長","answer":"契約の問題でございまして、私が住宅課長としてお答えはできかねます。","voiceIndex":49,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"品川区には現状そういう条例がないものですから、どういうお考えなのかなと。今のご説明ですと、審査の過程の中で、当然選ばれない理由の１つになるというお話でしたけれども、改めてその基準を再度ご説明いただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"},{"speaker":"中塚委員","kind":"確認","question":"じゃあ、確認ですけど、現在、ベニーエステートサービス株式会社も、社長、役員の中に議員はもちろん区の三役、親族も含めていないということでよろしいんでしょうか。","respondent":"齋藤住宅課長","answer":"おりません。","voiceIndex":53,"id":"exchange-021"}]},{"id":"topic-05","title":"平成１８年度区民住宅・区営住宅における指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成１８年度区民住宅・区営住宅における指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、冒頭に若干説明がありましたけど、区で点検したものを議会に報告するという話がありましたけど、そこのところをもうちょっと詳しく説明していただきたいと思ったのが１点と、あと、中間評価が出た時点で報告をするということの区の方針というか、その辺も含めて、もう少し詳しく教えていただけますか。","respondent":"齋藤住宅課長","answer":"今、委員ご質問の点は行財政改革特別委員会のほうで企画財政課のほうでご説明申し上げたところでございまして、住宅課長として説明するにはなかなか難しいのですが、要は、指定管理者制度をとってサービス向上、経費削減につながらなければ意味がない。","voiceIndex":59,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"その建設委員会に今の報告があったわけですから、所管の部としてどういう理由でこれを報告したのかというのは、きちんと説明をいただきたいなという思いで質問したので、これは建設委員会でそれぞれの業者を指定管理者として決定するか否かを審査をして、本会議で議決をしたわけですから、この報告をした理由をもう少し詳しく説明していただきたいという趣旨です。","respondent":"齋藤住宅課長、岩田まちづくり事業部長","answer":"ただ、中身はどのような業務をしていて、どういった問題があるかは所管の課、私のほうから説明させていただいて、福祉の指定管理者であれば厚生委員会で、そういう形で説明をするということです。当然のことながら、議会の議決をいただいて決めた業者ですから、そのＰＤＣＡの適切な時期にきちっと議会にも明らかにしていくという、この１つの制度として、今回。","voiceIndex":61,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"その結果、こういう評価になりましたよというその両方が必要ではないのかなと思うんですよね。この区の評価を僕らが再評価するわけではなくて、その事業が適切に行われたかどうかをそれぞれの委員の目でチェックをするわけですから、事業計画書や事業報告書、基本協定書をしっかり出してもらった上で、区としてはこういうふうに総括シートをつくりました。","respondent":"齋藤住宅課長","answer":"統一の総括シートでもってお示しをする。これが今のところの区の考え方です。どこまで議員が関与していいか悪いか評価するについては、おそらくは今後研究することだと思います。ただ、例えば、契約締結権、契約自由の原則でございまして、決めたと。","voiceIndex":64,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的にその総括シートに書かれたことで１点伺いたいんですけど、指定管理者の三井不動産株式会社の総括のところで書かれているんですけれども、家賃滞納時には粘り強い対応というお話がありましたけれども、その家賃滞納者の理由というのは何かということと、直接家賃の滞納の理由になると、個人情報なんかの固まりみたいなものじゃないですか。","respondent":"齋藤住宅課長","answer":"個別の理由はちょっと言いにくいんですけれども、そういった方が悩ましいところでありまして、一般的にはそういうことです。家賃は五反田のあたりで１２万円とか１３万円で入れますので、普通の収入であれば滞納ということはおよそないです。","voiceIndex":66,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"本当にいわゆる情報の漏えいをきちんと防ぐことができるのか、その仕組みがきちんと担保されているのか。三井不動産のことでなくしても、この間、いろいろ情報の漏えいの問題はあらゆる民間企業から社会問題化しているだけに、この問題というのはしっかり仕組みが担保されているのかどうか、非常に疑問に思うところなんですけれども、それについてはどういうふうにお考えなんでしょうか。","respondent":"齋藤住宅課長","answer":"不動産会社ですので、そういった情報が漏れるということ自体が会社の信用にかかわりますので、それについては今のところ問題はありません。区と同じように、あるいはそれ以上に守秘義務は守られていると考えております。","voiceIndex":68,"id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"住宅の問題というのはその個人の生活の本当に基本中の基本だと思いますので、そこはやっぱり指定管理者が、ここでいう三井不動産株式会社というところであれば、いわゆる情報の漏えいの問題というのはやっぱり不安を抱かざるを得ない。それを防止する仕組みも今の説明では私はできないと思います。最後、意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"宅建管理センターのところで区民住宅、区営住宅の退去から入居までの平均日数というのが９８.９８日とあるんですが、最短と最長で平均がどういう平均になっているのかわからないので、最短と最長がわかれば、教えてください。それと、３件ともそうなんですけれども、管理運営委託料の算定基準というか、どういうことでこういう金額になっているのかというのを教えていただければ。","respondent":"齋藤住宅課長","answer":"オーナーによって熱意が違いまして、急がなくてもいいと思うところはのんびりやってしまいますので、業者発注までなるべくすぐ入れてくださいというお話をさせてもらっているんですけれども、ところによっては５カ月ぐらいかからないと直さないというところがありまして。","voiceIndex":71,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"区民住宅、区営住宅の部分ではそんなに空きはないとは思いますけど、ここに限って言ったら、９８日というのは利用の要望が多いところのはずなのに、こんなにあるというのがよくわからないんですけど、そこのところを教えてほしい。","respondent":"齋藤住宅課長","answer":"かなり老朽化しておりますので、出た後、区のほうで壁紙とか水回りを直しますので、工事を発注するのに１カ月で、工事して１カ月、クリーニングして１カ月、大体３カ月ぐらいかかっているです。","voiceIndex":73,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっとよくわからない。普通に３カ月って、すごく要望があって大変な思いをして抽選もしてやっているというところで、その３カ月というのが妥当なのか。民間でもし早く入居させてというふうになれば、もっと早いのではないかなと思うのですが、それは仕組み的に３カ月もかからなければ対処できないということでしょうか。","respondent":"齋藤住宅課長","answer":"それは大概３カ月。住宅の傷みの程度によって違います。","voiceIndex":75,"id":"exchange-030"},{"speaker":"井上委員","kind":"提案","question":"ちょっと専門的なことなので、それはとにかく可能な限り努力をするということですので、それは徹底してほしいと思うんですが、１つだけ意見なんですが、区民満足の視点というところで、これは事業者側が区民満足の視点で回答しているところだと思うんですが、なおかつ、そのことについてのヒアリングも区が事業者に対してヒアリングをするということだと思うんですが、以前からこの指定管理者制度について。","respondent":"齋藤住宅課長","answer":"今後、モニタリングシステムの運用の中でどのような形でもって満足度を調査するか、今後指標が入ってくるかもしれませんが、今のところはアンケートという考えはないということのようです。","voiceIndex":77,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"全体の取り組みとしてはそういうことですので、住宅の管理を指定管理者を導入するという意味では、当然、担当事業部の取り組みとしてチェックは必要だと思いますので、それは統一的な部分が本来であれば求められるところですけれども、指定管理の内容によって違いもあるかもしれませんけれども、そこのところは事業部ごとに検討し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"ほかのところではこういう点ではないかということがあって、でもここでは空欄になっていると。これはむしろ書けと言っても書かなかったんだというご説明がありましたけれども、逆に区民満足の視点からも運営していくというような、逆に誘導するようなことというのも、こういうことをしたら書けるよみたいなことで、実施を誘導するようなことというのは区ではなかったんでしょうか。","respondent":"齋藤住宅課長","answer":"２つありまして、１個はモニタリングシステムというのが導入されまして、私どもも指導できなかったということ、それと、これはどういうことを、どういう点を書くのかということを議論したんですけど、なかなかうまく指導できなかったということがあります。","voiceIndex":80,"id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"先ほどちょっと委託料の算定基準なんていうのもありましたけれども、逆に、小規模で数がたくさんのものを管理するときに、これはちょっと漠然とした質問ですけど、あまりにも業者が持ち出しが多くならないような配慮というのをされているんでしょうか。何かあんまりむちばかりでもかわいそうだなと、見て思っていたんですが。","respondent":"齋藤住宅課長","answer":"だからその分を人件費にあてなさいというのを、ずっとこの間、指導してきたことなんですけど、あと、宅建管理センターとしても自慢の組織であり、若干先進的なモデルなんだと本腰を入れられている状況だと思います。","voiceIndex":82,"id":"exchange-034"},{"speaker":"三上委員","kind":"意見","question":"利益を上げているから、それで人を増やせと簡単に言うけれども、それはそれで努力をしてそれだけの利益を出すということは、もう民間は当然それは考えることだと思うので、そこらあたりの考え方と、区がやはりこれはもう少しこういった点で人の手が増えないからこういうことが起きてくるんだとかという現実があるのかどうかということについて、どういうふうにとらえていらっしゃるのか。","respondent":"齋藤住宅課長","answer":"年齢を申しますと、５０代の女性職員が２人いらっしゃるだけなので、きめ細かさ、あるいは要望されたときに、すぐに行く。","voiceIndex":84,"id":"exchange-035"},{"speaker":"三上委員","kind":"確認","question":"今、住宅課長の感じていらっしゃることを伺った話の中で、そういった現実というのは宅建管理センターの役員の方は理解し、手を打ちますということは言っていらっしゃるのか。そこのところだけちょっと確認します。","respondent":"齋藤住宅課長","answer":"検討委員会を設けて５回開催されて、大分体制が変わってきております。","voiceIndex":86,"id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"様子は、それはもう見ていきます。ほかの２社と違うのは、１つの会社が担当しているということではない。やっぱり考えてみると、そういった点での弱点というのはあるわけですから、そこのところを逆手にとって、本当に自分たちがいろいろな意味でその４６０社のそういう知恵とかいろいろなものを出し合ったならば、それはまたすごい力になるということはあり得ると思うんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"確認","question":"全体のことからちょっとお聞きしたいんですけれども、確認なんですが、基本的に先ほど来、いろいろ宅建管理センターも含めていろいろなところと、例えば、三井不動産の部分でも報告書等の提出期限を守るようにとかいろいろ指示をしたという、この対応方針と行政側の最後の経営会議における検証、この２カ所で、あとは業者が書いてきたという理解でいいわけですよね。そこだけまず。","respondent":"齋藤住宅課長","answer":"これはヒアリングをして区で書いたものです。業者に書かせたものをそのまま出すことはしないという、こういうルールです。ただ言ったことを少しそしゃくして区で書いたということです。","voiceIndex":89,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"確認","question":"そうすると、宅建管理センターのヒアリングの場合、先ほど白紙というところは、ヒアリングをした際も、逆に「こういうことを書いたら」というお話もあったけど、それに対してもヒアリングのときに答えなかったのか、書いてこなかったのかというのがありますよね。だから白紙になっているということなのか、そこら辺のところをもう一度確認させてください。","respondent":"齋藤住宅課長","answer":"白紙で出すのは抵抗がありましたので、「こんなことを書けば」と水を向けたんですが、白紙のまま返ってきた。それで、企画財政課に確認しましたら、議会の意見を仰ぐということを言っておりました。","voiceIndex":91,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"意見","question":"それぞれ皆さん、今も６社来たと。これを見る限り、この３つの中ではベニーエステートサービスは非常によくやっているというのばかりなんだよね。そこら辺の資料のつくり方とか、そういうのは我々ももう一度ちょっと考えたいなと考えていますけれども、ぜひ我々にもわかるように、なるべく資料を出していただけるようにお願いしたいなと思うのと、それから、宅建管理センターはこれはいつごろやったの。","respondent":"齋藤住宅課長","answer":"７月です。","voiceIndex":93,"id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"意見","question":"先週、職員は採用したみたいですね。この４６０人のボランティアでの部分が非常にあるので、利益も出ると思う。なおかつ、今メンテナンスの部分も含めて、案内をしたって、こんな汚いところに案内するのかというようなところも、逆に怒られているようなところも５度も６度も行けと言われて、何度も何度もそういう努力をしている。","respondent":"齋藤住宅課長","answer":"この総括シートをつくるに当たって、いろいろ庁内で勉強しているんですけれども、企画財政課のほうで調整したものだです。宅健管理センターの目に見えない努力というものが伝わらないシートになっているということについては、担当の企画財政課長のほうにも伝えておきます。","voiceIndex":95,"id":"exchange-041"},{"speaker":"三上委員","kind":"質問・要望","question":"今のところに絡む話の中身になってくると思うんだけれども、これを見てもファミーユ西五反田西館といっても、何戸あってという基礎的なものが入っていないわけだよね。１団地の中で何戸とかという形になるんだろうけれども、そういうのが見えてこないと、基礎データ的な部分でこれでは比べようがない。ちょっと要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":40376,"voices":115}},{"id":"h19-20070926-9","meetingId":"h19-cm09","date":"2007年9月26日","dateIso":"2007-09-26","committee":"文教委員会","time":"午前１０時０３分～午後１時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"教員の独自採用制度","agenda":"教員の独自採用制度","exchanges":[{"speaker":"市川委員","kind":"質問・要望","question":"臨時的任用ということなんですけれども、この臨時的任用ということをもう少し詳しく説明していただきたい。この３点をお願いします。","respondent":"河野指導課長","answer":"いわゆる連携校で連携がやられていないのではというご指摘ですが、全ての学校で、小中での連携は実際に実施しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"市川委員","kind":"質問","question":"そうしますと、連携ができている学校というのは大体どれぐらいの学校なのかということを数でお聞きしたいということと、それから臨時的任用という言葉から、不安定な雇用のように聞こえるんですけれども、その辺はどうなのか。待遇として、普通の教員と同じ待遇が与えられるのかということをお聞きしたいんですけれども。","respondent":"河野指導課長","answer":"先ほどもご説明させていただきましたけれども、連携されている学校は、区内の小学校、中学校、全校です。それから、臨時的任用教員の処遇ですが、一般の新卒教員と同等の処遇を考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（慎）委員","kind":"質問","question":"参考にお伺いしますけれども、まず、区費教員は、都費教員と同じ位置でよろしいんでしょうか。","respondent":"河野指導課長","answer":"それぞれ、ただ来たから、人数が増えたからそれをいいように使うということでは研修になりませんので、その辺、受け入れた教員に与える研修テーマであるとか、いつごろ、どういう形で、どういうことをやらせるとか。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、研修内容とかテーマというのは、その受け入れる学校がそのテーマを決めるのか、それとも教育委員会にある程度のものがあって、それに従って受け入れ先がその条件を飲んで受け入れるのか、どちらでしょうか。","respondent":"河野指導課長","answer":"もうちょっと具体的な中身で申し上げますと、各教科、それから市民科、英語科も含む各教科と小中連携、あるいは小中一貫教育、生活指導、あるいは学校運営、そういうような大ざっぱな提示ですが、必ずそれぞれ研修先に行って勉強してきた教員が、自分の学校に戻って役に立つ。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（慎）委員","kind":"質問","question":"もう１回だけお聞きしたいんですけど、このバイズティーチャー、せっかく各小中学校から他の学校で研修をして、前の学校に戻ってすぐに異動とかというのはないように心がけるのか。せっかくほかの学校で研修して、自分の学校に戻ってきたときに、「じゃあ、すみませんけど異動お願いします」と言われたりとか、異動とかというのがあったらどうなのかなと思ってお聞きしたいんですが。","respondent":"河野指導課長","answer":"ただ、初任者が初異動する場合、例えば品川区で初めて教壇に立った教員が３年以上勤務して異動する場合には、区内異動というのが認められませんので、必ず他の区市、あるいは島しょ地域に異動するというのが決まりになっておりますが、２地区以上経験した教員については、今。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"しかしその中で、この留学制度のところに書いてあるように、別の学校に研修・派遣というふうになっているんですが、どういう形で、どこの学校に１年間の任用という形であるか、その辺のあれがなかったからちょっとわからないんですけれども、とりあえず提供された資料を見てみると、小中一貫校を派遣先にするというふうに私は読んだんですけれども、一定期間、区内の別な学校に研修・派遣という。","respondent":"河野指導課長","answer":"この特色校が、例えば連携教育で他校にない斬新な取組をやっているとか、あるいは市民科の研究開発学校ということで研究しているとか、あるいは、例えば特別支援教育で非常に優れた実践をされている教員がいる学校であるとか、そういうようなこと全てですので。","voiceIndex":15,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"派遣し、研修を受ける、自分がこういう勉強を新たにしたいので、例えば今おっしゃった学校だとかそれぞれの特色のある学校にこういう目的で行きたいんだというのを当然出して、受け入れ校との調整が始まっていくと思うんですけれども、その辺は、直接的にはどういうふうになっていくのか伺いたいのと、同時に、受け入れ先の学校も、先ほど研修メニュー。","respondent":"河野指導課長","answer":"それとさらに、年間任用ということで応募されてきた方の資質、さらに所持している免許の整合性、そんなものを総合的に考えながら、最終的に年間任用教員の採用を決定していくという予定です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと複雑なところがあってわかりにくいので教えていただきたいんですが、区費教員採用と、それから人材育成というものの整合をとりますよというお話だと思うんですが、この表を見ると、人材育成は教員採用の対象になるということなんですか。それがまず１点。それと、選考の仕方なんですけど、１次、２次。一つは、校長先生ということですから、各学校によって違う可能性がありますね。","respondent":"河野指導課長","answer":"年間任用教員の業績評価ということで、基準はどうするのかですが、こちらの方については、採用基準をきちんと我々の方で用意をして、その基準に照らし合わせてどうなのかということを、それぞれの学校に客観的に判断していただくというような方法をとる予定です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"１点目、もうちょっと私の意図が伝わっていないのかなと思うんですが、この表の中に、今のお答えだと、区費教員採用という部分と人材育成というところはリンクしないような気がする、そういうお答えですか。一緒にここに書く必要はなかったんじゃないでしょうか。だから、そこで育てた先生は品川区にいてほしいわけですよ。だから、別々に書いたほうがわかりやすいんじゃないですかということです。","respondent":"河野指導課長、若月教育長","answer":"しかも、この都費教員と区費教員、特に区費独自採用教員は定数外ですので、例えば今、Ａ小学校の教員の定数が１０名と決まっていたとしても。今の指導課長の説明のとおりなんですけれども、基本的に、ここの一番下に「品川区立学校教員（１年間任用）選考（公募）」と書いてありますね。せっかく優秀な教員で、身分が区でなくても、都費の身分でありながら、一生懸命品川のために働いてくれていて。","voiceIndex":21,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろご説明ありがとうございました。突き詰めてくると、区費職員の方が多くなるという可能性はあるんですか。ただ、私もいろいろお聞きするまでそのねらいがわからなかったんですよ。そういった場合に、評価をするときにそっちの評価がないと多分見方が違うと思うので、いろいろな評価を踏まえた上で選考していただきたいと考えますが、その考え方についてお聞きしたいと思います。","respondent":"河野指導課長","answer":"ただ、校長連絡会、それから副校長連絡会においてはこの概要を説明して、とにかくこれは教育委員会が施策として実施することではあるんだけれども、これがうまく機能するかどうかということは、これはもう学校現場と行政側との連携がどれだけうまくできるのか。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点だけ追加で質問したいんですが、この区費教員採用、実際に今回５名程度ということで、今年は５名採用されて、その方たちというのは、何もなければずっと採用されるわけですね。さらに、また新たに採用するに当たって、毎年５名程度ずつ増やしていくのか、それともその５名の中で欠員が出て、その欠員を補充するための採用なのかということをちょっとお聞きしたいんですが。","respondent":"河野指導課長","answer":"平成２１年４月に採用を予定しております５名は、これは採用当初は条件つき採用ということになりますので、一応１年間様子を見た上で、最終的に正式採用するかどうかが決定されるということになります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"私も今の質問と同じような角度で伺いたかったんですが、要するに区費ですから、教員の給料が８００万円ぐらいですよね。それを、最初は５名ですからともかく、４年か５年先には二十数名という状況にして、それ以降は、その方たちが少なくとも退職されるまでは、数億の財源を投入し続けるということになるわけですよね。要するに、品川区のそういう教育方針を定着させるための人材育成ですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"}]},{"id":"topic-02","title":"平成１８年度品川区立体育館における指定管理者に対するモニタリング・評価の結果について","agenda":"平成１８年度品川区立体育館における指定管理者に対するモニタリング・評価の結果について","exchanges":[{"speaker":"西本委員","kind":"確認","question":"既に説明していることもあるかもしれませんので、確認の意味でもう一度お願いしたいと思います。組織的なところで、ここは、コナミスポーツが入っていたと思うんですけど、ここの会計はどうなっているのかなということをまず１点確認させてください。その辺は、独自でまかなっていたところがあって委託料が下がっているという解釈でいいのかというところを確認したいと思います。","respondent":"富田生涯学習課長","answer":"このほか、スポーツ協会としては、独自に、総合体育館を利用するに当たっての区民の方々の声を、投書箱等々の設置により集約をしているところでありまして、年度当初、体育館が開設された当初、これは業務委託部分でありますが、プール部分への苦情等々。","voiceIndex":34,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"それはやり方のことですから、別に委託するのが悪いというわけではないんですが、先ほどからトレーニング室、いろいろ改善されているんですけれども、運営についても改善に該当するところというふうな感じなんですけれども、これは、例えばコナミじゃなくて、ほかの団体というような、こういう評価のもとで分析をするときに、スポーツ協会にはいろいろ言えると思うんですけど。","respondent":"富田生涯学習課長","answer":"それと、先ほどご指摘のありました区民満足の視点につきましては、今回、このような形でまとめた結果となっておりますが、今後の評価に当たりましては改善してまいりたいと考えています。再委託先に対して、私ども直接の指示ということは行っておりません。","voiceIndex":36,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"要は、ビル管理が一緒になったのでその分という感じなのでしょうから、わかりました。それから、再委託のフォローですが、再委託ですからわかるんですが、あくまでも区とスポーツ協会との関係であって、スポーツ協会がそれを遂行するために委託を使うということなんですから構わないと思うんですが、ただ、こういう評価をするときに、トレーニングルームとかでいろいろ改善がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"そして二つ目は、２番目と３番目のサービス向上および業務改善の視点ということで、施設の利用そのものをもっと効率的にということで改善されたということで、利用が少なかった団体の部屋の使い方を合同開催にするとか、団体多数のところに振りかえる、こういうことでの指導があって、効率化に努めたというところなんですが、当然これは、専門家のコナミなり、スポーツ協会の方の検討の中だから。","respondent":"富田生涯学習課長","answer":"２点目の、種類の違う競技を同じ部屋でですけれども、従前より、体育館のアリーナについては、半面貸出、半面使用ということを実施してきておりまして、競技にもよりますけれども、かなり多くの競技につきまして、半面ずつ別の競技利用というのは実施をしてきて。","voiceIndex":39,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の見解がもしあれば教えていただきたいと思います。熱中症だとか、そういう問題も健康被害として出てくるということもありますので、ですから、例えば風のとおりをよくするような構造だとか、窓をきちんと開ける指導だとか、そういうものを管理者の方から積極的にそういう声をかけていくということを含めて必要なんじゃないかと思いますので、その辺についてどういうふうになっているのか伺います。","respondent":"富田生涯学習課長","answer":"事務局体制の強化等々についてどう考えているのかですけれども、従前の管理運営委託と、指定管理者になったこととの違いの部分というのは先ほども申し上げましたけれども、その辺をきちんと、スポーツ協会の事務局として認識し。","voiceIndex":41,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"戸越体育館については、競技中心なので、つけるつもりはない、つける必要はないというふうに考えている、そういうことなんですか。ですから、そういう他の使い方というのは、総合体育館以外にもあるだろうと思うし、その辺で、クーラーは整備してもこれからの時代は当然じゃないかなと思いますので、そのあたりの見解を改めて伺いたいと思います。とりあえずそういうことで、よろしくお願いします。","respondent":"富田生涯学習課長","answer":"戸越体育館については、現時点でクーラーを設置する考えは持っておりません。","voiceIndex":43,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"要請ですけれども、先ほど言ったような理由で、戸越体育館にもクーラーは必要ではないか。ぜひつけていただきたいということを、これから予算要望の時期だし、決算特別委員会もありますので、そういう時期をとおしてお願いをしていきたいと考えていますが、出た関係があったので、そのことも話しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"}]},{"id":"topic-03","title":"引き続きまして、(3)「南大井文化センターの改修工事について」","agenda":"引き続きまして、(3)「南大井文化センターの改修工事について」","exchanges":[{"speaker":"南委員","kind":"質問","question":"質問は、空調機の更新工事ということなんですが、その際も非常に暑い日だったので、空調を当然使わせていただけましたけど、各部屋での調節機能というのがなくて、電話で「使いますので」というふうに言うとスイッチを入れてくださって、クーラーが入ってくるようになっているようなんですが、更新するということなので、当然、各部屋でスイッチを入れたり切ったり、暑いときは強にしたり。","respondent":"富田生涯学習課長","answer":"従来は全館空調、第３講習室は個別になっていますが、そのほかは全館一斉のスイッチのオン・オフでありましたが、今回は個別に空調機がついておりますが、コントロールについては１カ所で集中して、連絡した上で調整をしてもらうという形を予定しています。","voiceIndex":50,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"そうすると、例えば区役所の私どもの控え室は、全館空調とは違って、個別に部屋に空調設備が整って、スイッチがあり、そこでつけたり消したり、温度調節もできるようになっていて、非常に使い勝手がいいんですけど、大体品川区の施設というのは、まちの中にある様々な施設も全館空調になっていて、ここの文教委員会の担当じゃないけれども、八潮の地域センターもやっぱりそうで。","respondent":"富田生涯学習課長","answer":"室温を個別にコントロールするのではなく、たしか事務室の方だったと思いますが、そちらの方で調整をするというふうになっているはずです。","voiceIndex":52,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"重複するところがありますので、確認していきたいと思うんですが、不登校の数がその中でもと思うんですけれども、不登校といじめとの関連についてというのがありまして、そこで、荏原第二中学校で実施している通級学級について、将来どういう形になるのかということも含めて教えていただきたいと思います。","respondent":"河野指導課長","answer":"話が前後して申しわけございませんが、荏原第二中学校の方も、不登校以外にも発達障害を受け入れるということで今年から進めておりますので、現在のまま推移をしていきますと、荏原第二中学校の方も手狭になるということが予想されますので、荏原第二中学校の方の移設。","voiceIndex":57,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"全区的に学校を巡回したりとかいろいろされていると思うんですが、そことの関連性はどうなっていくのか。位置づけとしてですね。その場合に、当該の学校の状況も含めて、その情報をお互いに共有することで、早く復帰できるという形がつくれるんじゃないかと私は思うんですが、そういう動きは今後つくっていけるのか、つくってあるのか、いかがでしょうか。","respondent":"河野指導課長","answer":"そういう関係で、どちらも教育委員会所属ということでもありますので、守秘義務ももちろん前提としてあるわけですけれども、同じ組織の中での対応ということで、できるだけ具体的なことも含めて、情報交換をするように努めております。","voiceIndex":60,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"要望も含めて伺いました。荏原第二中学校とマイスクールについては、そういうことになっているということで、今の説明を含めて、事業の拡大という形でぜひ広げていけるように、本当に積極的にまかなえるように、増えていくといいなと思っています。ですから、親が学校に問いかけたりとかしなくてはならないというところが出たりして、わりと当事者間だけだとやりにくい部分もあるんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4614#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":38347,"voices":73}},{"id":"h19-20070926-5","meetingId":"h19-cm09","date":"2007年9月26日","dateIso":"2007-09-26","committee":"総務委員会","time":"午前１０時０３分～午後２時０１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問","question":"補正予算ということは、補正をするということはそもそも何なのということなんですけれども、今のお話の中でもいろいろありまして、事業の進捗に伴って補正をする、時期的な、流れの関係で補正をする、あるいは入札差額等がもう明らかに生じているので、これを補正をする、あるいは補助金等が出てきたりも含めて補正をする、事業内容が変わったから補正をするという部分と。","respondent":"日下部企画財政課長","answer":"１つは委員から最初にご指摘がございました事業の進捗の関係ですけれども、さっき原小学校について大分いろいろと、ちょっとわかりづらかったのかもしれませんが、全体についての組み立てが変わりましたので、補正予算の計上ということでご説明をさせていただきましたけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"よくわかったんですけれども、結局、いわゆる補正をしなくてというのは、例えば予算が入ってくるものはきちんと計上しましょうということになりますから、入ってきますよ、入ってきていますよということを予算書上にも明解にしていかなきゃならないという意味なんだろうと思うんですけれども、要するにいずれの場合も、歳出の場合も、日々動いているわけですから。","respondent":"日下部企画財政課長","answer":"ただ、実際上の、例えば執行過程の中で不用額が一部生じたような場合については、これは結果的に１つの決算対応という形で整理をするということもありますけれども、最大限これは議会にお諮りすると。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"３点ほど、ちょっとそれぞれにお聞かせいただきたいんですけれども、先ほどいろいろご説明をくださった原小学校跡地のところなんですけれども、とりわけシルバーセンター、先ほど直営予定だったのをこうほうえんに一本化をしたんだというお話がありましたけれども、３７ページですけど、その辺の理由をお聞かせ願いたいのと、それともう１つは。","respondent":"日下部企画財政課長","answer":"もともとこれは、当然のことながら高齢者の皆様方に無料で利用していただくという施設でもありますので、そういった意味ではケアホームとか幼保一元施設とかとちょっと性格が違いますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"それのチェック機能というのが実際にどうなっていくのかというのが、一緒にこういう施設整備、助成が補正として来るときに、その辺も含めて出てくるべきではないのかなというような気がするんですけれども、だから、要は条例で規定されているチェック機能がどうなっているのかというところが鮮明になるのかどうかというところをお聞きしたいんです。","respondent":"日下部企画財政課長","answer":"それから条例の関係ですけれども、これは今の西大井シルバーセンター自体が、現に今、原小学校に移行するまでは、今のシルバーセンター自体はずっと生きておりますので、それについての条例として来年の少なくとも８月竣工ということになりますけれども。","voiceIndex":11,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"あと４３ページにありますけれども、八潮地区再生方策検討業務委託というところをお聞きしたいんですけれども、これも今、八潮をどうにか切りかえていかなくちゃならない、これはわかるんですけれども、今、住民の皆さんのところでもいろいろな話し合いが行われていて、この検討業務の委託をするということと、住民の皆さんの意向とこの検討業務との関係というのをどのようにとらえればいいのか。","respondent":"日下部企画財政課長","answer":"ですからそういうことも含めまして、都市計画の見直しについて、これはさまざまな角度からの検討、これは早く着手しないと、せっかく地域でまちづくり、活性化を進めていこうということで、いろいろ今、機運も高まっておりますが。","voiceIndex":14,"id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"都市計画を変えていくというのを、ちょっと聞くところによると、できれば年内あるいは来春の早い時期に行っていきたいというお話を聞いているんですけれども、そうすると、住民の皆さんがいろいろな話し合いをしている中でというのが、これは時間的な問題ですけれども、実際にその中にどういうふうに入っていくのか、その辺の時間的な、住民の皆さんが例えば２年がかりで論議をしようとしたときに。","respondent":"日下部企画財政課長","answer":"これはあくまでも、例えば学校の跡地を具体的に何々の用途にということでがっちりと絞り込んじゃうものではなくて、比較的幅広く柔軟にある程度の枠組みを決めることができるものでありますので、そういった意味では、今のご質問の関係からしますと。","voiceIndex":16,"id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"わかりました。ちょっと最後に教育の部分でお聞かせ願いたいんですけれども、４３ページにありますけれども、新教育システムの開発プログラム事業、これの追加の予算がつけられていますけれども、この事業の目的をまずお聞かせ願いたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"菊地委員","kind":"意見","question":"実際、この事業費というのは、書類上を見れば、教育委員会がこの事業の申請をされて、この中で学校の統廃合の流れをこれから推進するために調査研究をするんだという中身になっているんですけれども、このプログラム事業の費用を実際にここで補正でつけていけば、これが議会でも、あるいは区民の中でも周知をされないまま、これだけの流れがつくり出されていくというふうになると思うんですけれども。","respondent":"日下部企画財政課長","answer":"新教育システム開発プログラム事業費というのは、先ほど申し上げましたように、非常に教育制度全般にわたって幅広く活用できる、そういう形で文科省で設定をしているものであると私どもは承知をしていますし、そういう意味では、品川区におきましてもいろいろ今。","voiceIndex":22,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけれども、今の説明だと、この西大井の原小学校跡地のことについては、何ていうか、法改正があったから、耐震性が間に合わないからという説明があったんですけれども、つまり確認したいのは、平成１８年１月２６日以降法改正があったのか、それとどこの基準に基づいて補正を算定できたのかということを確認をいただきたいと思います。","respondent":"日下部企画財政課長","answer":"ですから実際には、当初の予定では９月までに一通りのそういった作業が終わる予定でありましたものが、どうしても評定取得、二重チェック等の関係で期間が延びてしまいまして、これが１２月ぐらいまでずれ込むことになったと。","voiceIndex":24,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、その部分の説明をいただきたいのと、それからあわせて言いますけれども、例えば法人との貸し付けの調整とか、それからシルバーセンターの民営化なんていうのは本当は中の話なんですが、やっぱりこれは当初の資金がしっかりしていて、こういう調整がとれていって、しかも平成１７年４月時点での耐震基準がもし適用されていてれば、補正を組む必要はなかったと私は思うんです。","respondent":"日下部企画財政課長","answer":"確かに委員がご指摘の点、先に基準の変更というのはわかってはいたわけですから、そういったことも含めて、本来であればもう少し、多少スケジュール的にも幅を持った形での設定ということをしておけば、着工がずれるということもなかったのかなとも考えてはおりますけれども。","voiceIndex":26,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"ですからやり方をそのときしっかりと詰めていれば、補正は組む必要はなかったと私たちは思っていますので、ぜひそういうことも含めて、これからの予算を決めるときには算定を、対処をひとつお願いしておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"浅野委員","kind":"意見","question":"３３ページなんですが、日曜開庁の、きのう出た話ですけれども、住民情報システム改修・運用委託費で２,６００万円計上されていますけれども、単純に考えると、日曜日に開いて、どうして情報システムの改修が必要になるのかと、単純な疑問なんですけれども。","respondent":"小野情報システム課長","answer":"それからもう１つは、それを通常は開庁して処理をしますと、日時の処理ということで、処理が終わった後に全部コンピューターに一回流して、データをきちんと取り込むという作業が出る、そしてこの取り込んだ内容を今度はほかの部門のシステムに反映させる。","voiceIndex":29,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"もう２つくらいあるんですけれども、もう１つが４５ページの学校管理費で荏原第二中学校、平塚中学校の統合で標準服等更新経費というものが入っているんですけれども、中学生ですから、当然、制服という、それぞれ平塚中学校も荏原第二中学校も違うんですが、これは例えば新しい小中一貫校になって、新しい制服を制定するために、この費用は実は随分高いなと思うんですけれども。","respondent":"日下部企画財政課長","answer":"これの対象といいますのは、実は今度新しく入る中学校１年生はわかっていますからいいんですが、２年生、３年生は事前に統合ということをわからないような、そういう状況でありましたので、これについては地域のいろいろな説明会でも父母の負担の軽減ということでいろいろご意見。","voiceIndex":31,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"ということは、例えば２年生ですと２年、３年、３年生ですと１年の使用ということで、これは貸与ということで、卒業したら返却ということでよろしいでしょうか。","respondent":"日下部企画財政課長","answer":"ええ、そのような形で有効活用するというものです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問","question":"もう１点ですけれども、先ほどから何回も出ている原小学校の件なんですけれども、今回、シルバーセンターを民設民営に移行するということですけれども、これは公開されるかどうかもわからないんですけれども、後学のためにお伺いしたんですが、そうして移行することによって、例えば運用費用を民設民営に変えることによって、将来的な費用負担、そういうものが大幅に変わるものなのか。","respondent":"日下部企画財政課長","answer":"ただ、さっき申し上げましたように、広さが広くなりますので、その辺も含めてトータルでどうするのか、これから具体的に詰めてまいりたいと、このように考えております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"菊地委員","kind":"意見","question":"ただ、先ほどお聞かせ願った新教育システム開発プログラム事業というのは、議会でも統廃合の問題も言わず、それから教育委員会でも議事録を見ますといろいろな問題点が指摘されている中で、２月２日に教育委員会の名前で学校統廃合の先行実施を行う、その検証をやるんだということでこの予算が、この予算というよりも、この予算をとるための申請が行われている中身になります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"一番最後、６７ページにあります国庫支出金の返還というところで、平成１８年度の超過分ということになるんですけれども、３億４,０００万円というかなり高額な返還になっているんですけれども、こういう返還金が出た理由というのを教えていただけますか。","respondent":"日下部企画財政課長","answer":"これは制度改正で下がりましたので、その辺が１つ、それから実際は平成１８年度からの介護保険の改正で、特に介護予防の取り組みというのが非常に重視されましたけれども、実際には要支援の１、２に移るというのを見込んでおりました人数が。","voiceIndex":48,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"要するに予算を最初多く見積もり過ぎたということなんですかね。変な話なんですけれども、この余った３億４,０００万円というのを、実際の事業として、事業の幅を拡大してこの予算を使うとかという形式というのはできないものなんですか。いろいろな事業、こういう事業の中身について、これだけ必要ですよということで当初決定されて、国庫からの支出金をもらっているわけですよね。","respondent":"日下部企画財政課長","answer":"もちろん改正を当然前提に予算を組んでいたわけですが、ただ実際の実績が見込みよりも下がったということが、その分全体の実績が下がりましたので、国の補助金についても当初見込んでいたより少なくて済みましたので、その分をお返しするという、基本はそういうことですが、ただ。","voiceIndex":50,"id":"exchange-018"}]},{"id":"topic-02","title":"されております。そういうわけで、お昼の時間を厳守して一たん終わりますので、次からの報告事項が途中になるかもしれませんので、ご了承いただいて","agenda":"されております。そういうわけで、お昼の時間を厳守して一たん終わりますので、次からの報告事項が途中になるかもしれませんので、ご了承いただいて","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"その後、改めてこれが案が取れてパブリックコメントに出されるときに、中身として、こういう委員の皆さんの出された意見の集約として出されるものなんですか。そもそも私が前の基本構想のところがよくわからない、どういう形で出されていたのかがわからないので、ちょっとそこをまず。","respondent":"福島長期計画担当課長","answer":"説明します。先にありますゴシック体で書いてあるものが策定委員から出された意見です。それを受けて、事務局案としまして書いたのが下のものです。","voiceIndex":58,"id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"この間の本会議のときの区長の答弁で、正確な言葉は覚えていませんけれども、いずれにしても区民生活を支えるのが基本なんだという発言がありましたけれども、そうなると、そもそも理念で一番大きなものというのは、どちらかといえば区民を軸にした、これが適切なのかどうかわかりませんけれども、理念の３番目みたいなものは、本来、軸になるべき中身なのではないのかなというような気がするんですけれども。","respondent":"福島長期計画担当課長","answer":"この国際都市という言葉ですけれども、品川区が持つ、あるいは今後２０年で持つであろう、例えばエネルギーですとかポテンシャルですとか、そういったものをイメージしたものと考えております。","voiceIndex":60,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"ですから、だからそこは一番大事なのではないかなと思うんです。そこをちょっと、もう１つ今の自立したというところというのはどうもうなずけない部分なので、ちょっともう一度。","respondent":"福島長期計画担当課長","answer":"自立があってこそ共生ができるのであって、また共生するのも自立があってです。個として自立していないと、共生もできないだろうと考えているものですので、またそういった一人ひとりの区民が自立できるように支えていくのも区の役割ではないかと考えているものです。","voiceIndex":64,"id":"exchange-021"},{"speaker":"土井委員","kind":"質問","question":"基本構想の骨子案についてお尋ねしたいんですが、これは企画部で一応おつくりになって出されたんだとお伺いしたつもりですが、それでいいのかということが１つと、その中で、３ページの理念３のところの大見出しのところにも「区民との協働」と書かれているし、一番下の「自立した区民との協働」、いわゆる協力の「協」に「働く」という「協働」が使われているわけですけれども、これはここばかりでなくて。","respondent":"福島長期計画担当課長","answer":"そういったことも含めまして、こういった協働という言葉を使うかどうかも含めて、委員会で十分議論していきたいと考えております。","voiceIndex":68,"id":"exchange-022"}]},{"id":"topic-03","title":"の(2)インターネットＦＭ局との災害時協定","agenda":"の(2)インターネットＦＭ局との災害時協定","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"確認なんですけれども、このInterＦＭ局の放送の範囲というと２３区と横浜市等ですよね。品川区の方々にケアするのはもちろん優先でいいんですけれども、逆を言うとほかの自治体の方々に対しても、この地域の方々は受信できるわけじゃないですか。ですからその辺のほかの自治体との協力体制はどうなっているかということを確認したいんですが、いかがでしょうか。","respondent":"中川原広報広聴課長","answer":"東京都全域に関することは東京都が協定を結んでやりますので、さらに私どもが協定を結ばせていただくというのは、きめ細やかな品川の情報もそこにさらに入れするといった段階に応じた情報ということになると思います。","voiceIndex":76,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、２３区にまたがる大きなことについては東京都にしていただくと、じゃあ、具体的に品川区民にどういうところをこのＦＭ局とこれから提携をして、品川区の情報を流していくかいうのが、中身について、どういう例えば時間枠があって、どういう内容を放送していくかということまで詰めていますでしょうか。お聞かせいただければと思います。","respondent":"中川原広報広聴課長","answer":"こういった災害協定がないと、そういったときに突然お願いしてもなかなか向こうとしても対応できませんので、対応ができるための条件整備を今の段階でしていこうと、そういうことです。","voiceIndex":78,"id":"exchange-024"},{"speaker":"浅野委員","kind":"質問","question":"８月３日の総務委員会のときに、この会社と試行的に来年３月まで時間を区切って、３分間ですか、多言語で放送するということを試行で始めたということですけれども、これは、例えば来年の３月までやって、そのまま継続するか、また、やめるのか、また、改定をするのかという判断はあると思いますけれども、その契約とは全く別個に、こちらは単独で契約をされるのかどうかをお伺いしたいと思います。","respondent":"中川原広報広聴課長","answer":"ですから今後６カ月間、料金を払いながら放送していただく契約を試行する中で、こういったこともできるということも視野に置いて、来年度以降、放送契約を継続するのが適切かどうかということを今後の予算編成の中で査定をしていくといったものになろうかと思います。","voiceIndex":80,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"ということは、契約を来年度以降しないと、この協定は成り立たないという判断でよろしいでしょうか。","respondent":"中川原広報広聴課長","answer":"なかなか無理は言いづらい関係になろうかと思います。","voiceIndex":82,"id":"exchange-026"},{"speaker":"武内副委員長","kind":"質問","question":"それともあえてやらないとか、やらないほうがいいのか、その辺はどうお考えなんでしょうか。","respondent":"中川原広報広聴課長","answer":"どのような災害が起こって、どういう情報を流すというのにあわせて、時間帯、２４時間時間がありますので、その中で調整をするといったことですので、今の段階で時刻を、一定というのはなかなかむずかしいと思います。","voiceIndex":84,"id":"exchange-027"},{"speaker":"武内副委員長","kind":"質問・要望","question":"わかりました。できればある程度の枠を確保できないか、同じ時間帯にほかのところがブッキングしちゃう場合も当然あるわけでしょうし、１つの幅を広げる意味では協定を結ばれたということはいいと思うんですけれども、実効性を高める意味ではもうちょっと細かいところまで詰めたほうが今後はいいんじゃないかなと、要望だけ、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-028"}]},{"id":"topic-04","title":"災害対策荏原職員待機寮の改築工事","agenda":"災害対策荏原職員待機寮の改築工事","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"災害対策の待機寮という名称のとおり、区内で何か災害があれば、まず優先的にきっとそこにお住まいになられている職員の皆さんは本部に行くか、何か呼び出されるんだと思うんですけれども、そういう災害対策にまず優先的に従事をしなくちゃならないという職員の数の見積もりとして、さっき１１寮から７寮に減っていますという話があったんだけれども。","respondent":"榎本人事課長","answer":"そのうちの、寮が今、全体で７０戸ですので、６０人台後半が災害に従事できるという人数という形になっておりますので、その初動体制の部分でいきますと、全体の数からいくと、区内居住もしくは６km圏居住というのがかなり優先度が高い部分がありますので。","voiceIndex":94,"id":"exchange-029"},{"speaker":"土井委員","kind":"質問","question":"この建物は改築ですよね。改築というと、普通に全部ひっくり返して根っこからつくるということなんですよね。そういうものも検討されたのかなという点と、４階が３階になっちゃうわけだから、面積もそんなに変わらないような、延べ床はもうあれですし、あまり変わらないようなあれなので、そういうものはないのかなと思ったものですから、ちょっと検討されたかなというぐらいの調子で、質問は以上です。","respondent":"榎本人事課長","answer":"それから基礎を残してということなんですけれども、やはり下に防火水槽が入っているんですけれども、防火水槽はできればもう少し大きいものを少し検討したいなということもありまして、従来の４０トンというものがあるんですけれども、今。","voiceIndex":96,"id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"そうすると今は改築の方向でということで、今出ている図面等は固まったものではない、まだ少しは変わるんですか。","respondent":"榎本人事課長","answer":"ほぼ固まっておりますけれども、これから説明会の中で若干の修正が入るかどうかということで、骨格の部分はこれで固まったです。","voiceIndex":98,"id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"それと、あと防火水槽なんですけれども、一応、約４０トンという、これによって補助の関係ですとか、それからもしくは減税とか、減免というようなことが、これから検討されるのかどうかをお教えいただきたいと。","respondent":"榎本人事課長","answer":"この防火水槽につきましては、もう当初の昭和４４年のときから義務づけられている防火水槽でございまして、ある程度戸数がまとまったこういう建物については防火水槽は義務づけられておりますものですので、その形で減免とかそういうものの対象にはならないものと考えます。","voiceIndex":102,"id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"もう一回、今のご説明では、大まかにはわかったんですけれども、そうすると構造的にそれ以上のものにはならないとか、要するにトン数ですね、トン数的なものと、それから全体的にマキシマムに使っていると、自分の考えとしては、当然、以前からもあったんでしょうけれども、それ以上にプラスになる部分的なものが発生するようなところはないでしょうかと、減免だったり、もしくは補助だったりという。","respondent":"榎本人事課長","answer":"あとプラスになるものというのは、逆にいきますと、今まで２階を地元貸し出しの会議室として使っていましたけれども、１階の貸し出しの部屋が使えるということと、あとは今よりかは若干バリアフリーのものが使えるということと。","voiceIndex":104,"id":"exchange-033"},{"speaker":"武内副委員長","kind":"質問","question":"会議室なんですけれども、これはもともとあったんですけれども、広くなったということですけれども、もともとのをちょっと知らないので教えてもらいたいのは、これはこの中だけの何か災害があったときの会議なのか、それとも地域に貸したりとか、そういうことは今まであったんでしょうか、また今後出てくるんでしょうか。","respondent":"榎本人事課長","answer":"会議室としましては、災害があったときの本部機能としての位置づけをしておりますけれども、災害がないときについては、有効利用ということで地元の団体等に貸し出しをしております。今もしておりますし、今後も改築後もそういう貸し出しは継続するものです。","voiceIndex":108,"id":"exchange-034"},{"speaker":"伊藤委員","kind":"確認","question":"それからもう１つ、待機寮ですから、防災計画があって、この地域的にこの待機寮を当てはめていくとか、そのことの中で１１寮を７寮に減らしたんでしょうか。あわせて、この中のものを待機寮がそういう防災的な中で、荏原地域に対する１つの拠点として確保されているんでしょうか、計画上の中のものなのかということの確認をお願いいたします。","respondent":"榎本人事課長","answer":"そのほか東品川地区ですとか、わりと品川区の東、庁舎を中心にしますと東側に３寮、それから南側に２寮、西側に２寮というような形でバランスよく配置を今、行っている状況です。","voiceIndex":110,"id":"exchange-035"}]},{"id":"topic-05","title":"(4)中延児童センター耐震改修その他工事","agenda":"(4)中延児童センター耐震改修その他工事","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"すいません、私がちょっと聞き逃しちゃったのかもしれないんですけれども、保育園の中の内部改修も含めて厨房設備をやられるようなんですけれども、この工事期間は、そのままその場所で保育できる体制でもって工事ができる中身なんでしょうか。そこだけ。","respondent":"中島経理課長","answer":"基本的には、居ながら工事、通常の保育園の運営をしながら、安全を確保しながら工事をしていくというものです。","voiceIndex":118,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1762#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":53147,"voices":127}},{"id":"h19-20070927-14","meetingId":"h19-cm09","date":"2007年9月27日","dateIso":"2007-09-27","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後０時２９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"今回の表では数字が多いということで載ってないということだったんですけれども、そうすると、この収入率というのは、今回の表で言えばどことどこを比べるとこの数字になるのか、あるいは今回の表で出てきているものではこの収入率というのは計算し切れないのか、ちょっと、その関係を教えてください。","respondent":"日下部企画財政課長","answer":"収入率、大変申しわけございません、実はこれを入れたものもつくったんですが、余りにも細かくなってしまうんで、さっき申し上げましたようにカットいたしました。この収入率は、実は決算調定額Ａに対する収入額のＢということで収入率を算出したものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"阿部委員","kind":"確認","question":"確認になりますが、この中ではＡ分のＢということで、前回の表で言う1)分の2)というのと同じということでよろしいでしょうか。","respondent":"日下部企画財政課長","answer":"そのとおりです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"還付未済額のほうなんですけれども、これの滞納繰越ということは、還付しているのですけれども、還付先がどこかわからなくなってしまったとか、そういうことでどんどん増えていってしまうのでしょうか。","respondent":"日下部企画財政課長","answer":"所在不明であったり、いろいろそういう事情がございまして、その分がそのまま繰り越しされる形になってまいります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"そうすると、これはずっと、どの辺までで例えば何か法的にとか、わからないですけれども、例えば区のほうに入るのか、それとも、ずっとこのまま何十年も続けて繰り越しされていくのか、その辺教えてください。","respondent":"日下部企画財政課長","answer":"これは改めて所管のほうには確認いたしますけれども、おそらく税法上の取り扱いとしましては、基本的には５年ということになろうかと思います。","voiceIndex":10,"id":"exchange-004"},{"speaker":"林委員","kind":"質問","question":"大分わかりやすくはなったんだけれども、そもそも不納欠損として計上していくとき、先ほどの説明だといろいろな基準に沿って、５年というものもあるでしょうし、亡くなられた場合とかあるだろうと思うんですけれども、時効という考え方は持っていらっしゃるんですか。","respondent":"日下部企画財政課長","answer":"実は不納欠損の１つの大きな要因としましては、時効ということでの取り扱いをしております。税の場合は５年、それから、国保、介護保険の場合はちょっと法的な位置づけが変わりまして、２年ということで時効が適用されるものです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"林委員","kind":"質問","question":"そうすると、この不納欠損になってくる、今言われた５年とかそういう時間の経過でなってくるわけだけれども、その前に差押とか、あるいは割賦納付というのかな、そういうようないろいろな、とにかく納付をしてもらうための手段というかそういうものを講じているわけだけれども、その辺でもなお不納ということになっていく、その辺の過程、こういうことをやっているんだということをちょっと教えてください。","respondent":"日下部企画財政課長","answer":"今お話のありました例えば督促との関係で申し上げますと、例えば１度督促をいたしますと、その時点で時効のスタート台が移行いたします。","voiceIndex":14,"id":"exchange-006"},{"speaker":"林委員","kind":"質問","question":"率から言うと、分母が大きいからそんな数字には出てこないけれども、額から言うと２億円、３億円ということになるわけで、その数字について、一般的にはえらいお金ですよね、それは行政は少ないと感じているのか、多いと感じているのか。大きいか小さいか、サラリーマンの人は生涯全部１００％払っている人がいるわけだから、そういう人に対しての思いというのは、感想で結構ですから、ありませんでしょうか。","respondent":"日下部企画財政課長","answer":"だから、率で考えれば２％ということにはなりますが、額自体を見ますと２億円、３億円ということになれば、それはやはり、行政運営の一番の土台になるものでありますので、これはやはり、全体の予算規模とかそういうことから比べれば少額ではあるかもしれませんけれども。","voiceIndex":16,"id":"exchange-007"},{"speaker":"林委員","kind":"質問","question":"特に特別徴収の人は、住民税の、下手すると３倍ぐらいになっているのかな、額から言うと。そういうことからすると、普通で３０万円ぐらいの給与でご夫婦でいると、毎月１万円から１万５，０００円ぐらいかかる、ちょっと数字ははっきり覚えてない。別の機会でどういうふうにして対処しているかお聞きしていきますけれども、よろしくお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"提案","question":"この間多分、検討すると言っていただけたと思うんで、その辺もちょっと知りたいんですけれども、いかがでしょうか。私たち、特別区民税の条例提案をしましたけれども、減免、免除。私は、特別区民税と介護保険料のところの滞納の理由とかどういった状況なのかというのもぜひこの場で出していただかないと区民の生活実態が見えてこないと思うんで、その辺をお願いしたいんですけれども。","respondent":"日下部企画財政課長","answer":"それからそれぞれの事情等についてのご質問でありますけれども、これについては基本的には国保のほうでご答弁をさせていただいたような、病気でありますとか失業でありますとか、そういう傾向につきましては、そんなに大きくは変わらない。","voiceIndex":19,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"今、国保と余り変わらないというご答弁だったんですけれども、調査はちゃんとされているのか。きちんと出せる資料となっているのか、その辺もお伺いします。","respondent":"日下部企画財政課長","answer":"これについてはいろいろ把握の仕方とか、その辺についてはまた今、所管のほうでまたこの前のいろいろなやりとりを踏まえて、それはそれなりの整理をさせていただいているような点もありますので、その辺は改めてまた確認させていただきたいと思います。","voiceIndex":21,"id":"exchange-010"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"滞納繰越の不納欠損になっていくのは時効の問題とかいろいろあると思うんですけれども、現年度の不納欠損というのはどういう理由が出てくるのか。それから、もう１点。先ほど特別徴収というお話がありましたけれども、特別徴収で社員の方、従業員の方は払っている。ただ、会社が払わなかったときに社員の方に対して滞納には結びつかないだろうという、その確認をさせてください。","respondent":"日下部企画財政課長","answer":"会社の給料の未払いの関係なんですが、ちょっと、その辺の取り扱いは私も今わかりませんので、これはまた後ほど確認の上ご報告をします。","voiceIndex":24,"id":"exchange-011"}]},{"id":"topic-02","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"山内委員","kind":"質問","question":"この簡易型総合評価方式、大変にすばらしいというか公平性を持った、いわゆる入札という形でよろしいかと思うんですが、どうしても従来やはり価格というものが一番重視、それだけの基準という部分があったと思うんですけれども、それ以外に内容的なものというものも含んで業者を選定しましょうということなんですけれども、やはりこうやって見ますと。","respondent":"中島経理課長","answer":"簡易型総合評価方式におきましては、いわゆる価格点につきましては５０点で、技術点につきましても５０点ということで、フィフティー・フィフティーの重さでもって決めていくということです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"山内委員","kind":"質問","question":"私も、そういう理解はしたいんですが、何となく従来どおり価格的なものが重視されてしまうのかなというのをちょっと危惧して、そのような形で質問させていただいたんです。","respondent":"中島経理課長","answer":"先ほど評点の説明をさせていただきましたけれども、要綱の６ページですけれども、これにつきまして８０％未満から１００％超まであるんですけれども、価格が先ほど例示に挙げました１億円のところで３，０００万円で入れてきたという場合は自動的に、入札でしたら。","voiceIndex":32,"id":"exchange-013"},{"speaker":"山内委員","kind":"質問","question":"私が危惧していたことを今、経理課長がおっしゃっていただいたんですけれども、やはり価格だけで選ぶとなるとどうしても内容的な部分の質の低下というものが危惧されるので、その辺しっかりとお願いしたいと思います。それと、最初に説明いただいた資料の中に学識経験を有する者の意見というものがございましたけれども、その学識経験者の選定基準は何かあるんでしょうか。","respondent":"中島経理課長","answer":"特に具体的にこういう人というのは決められておりませんけれども、例えば学校の教授とか、こういった委託契約に関して特に知識を有する方ということで、特にこういう人を入れなければいけないという規定はございません。","voiceIndex":34,"id":"exchange-014"},{"speaker":"山内委員","kind":"質問・要望","question":"これは私の所属する文教委員会のほうで話が上がったんですけれども、大間窪小学校の給食委託のことで話が上がりまして、簡易型総合評価方式の入札という形である業者が選ばれたんですが、結局しっかりとした仕事ができないということで途中で解約されて新しい業者になったということなんですけれども。","respondent":"中島経理課長","answer":"実際、そこの業者は保育園でも受けておりまして、保育園では相当の実績がある業者と聞いておりまして、実際、そういうことも含めて決めたわけですけれども、実際４月から業務に入った段階で、要するにどういう人が来るのか、調理代行で責任者がどういう人とか。","voiceIndex":36,"id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"そうすると、その業者というのは、今後例えばそういう入札があった場合といったときには、資格がないということでいいのですか。","respondent":"中島経理課長","answer":"例えば来年の契約の中で、そこの業者がこの簡易型総合評価方式の参加資格を失うということはございません。","voiceIndex":38,"id":"exchange-016"},{"speaker":"山内委員","kind":"質問","question":"すると、その会社が参加してきた場合ですけれども、どういう形で区のほうのは考えていくのでしょうか。","respondent":"中島経理課長","answer":"来年、調理代行のほうで参加してきたときに、所管のほうでも審査委員会でどういう評価というのはありますけれども、今年のそういったことがあったというのは当然一定程度加味されたものになるんではないのかなというふうには、予想はしております。","voiceIndex":40,"id":"exchange-017"},{"speaker":"阿部委員","kind":"質問・要望","question":"１点確認させていただきたいんですけれども、この今回の簡易型総合評価方式が随意契約の中で行われるということは、今後また地方自治法の改正なり手続の簡素化が実現することになれば、入札においても導入していこうという見通しの中で行われるということですか。","respondent":"中島経理課長","answer":"委員のおっしゃるとおり、今まさに国のほうで地方自治法施行令の改正を検討しているということですので、そういった中で簡素化されて私ども事務的に対応できるということになれば、当然施行令に沿った形での入札方式に移行していきたいと考えています。","voiceIndex":42,"id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"この実施要綱が１０月１日施行とあるんですけれども、当面の、あるいは例えば本年度中でのこの総合評価方式を使っての契約が何件ぐらい、どのぐらいの大きさのものがありそうなのか、見通しがあれば教えてください。","respondent":"中島経理課長","answer":"まだ予算も決まってない段階ですので具体的にどのぐらいというのはありますけれども、当然１９年度に試行を実施して、学校とか給食の調理代行につきましては当然やっていこうです。それとあと戸籍関係の業務ですけれども、戸籍、住民票の郵送について、今検討をしているです。","voiceIndex":44,"id":"exchange-019"},{"speaker":"阿部委員","kind":"質問","question":"品川区では今後、今これを見た段階では価格と能力という非常にシンプルな評価の視点になっていると思うんですけれども、さらにその評価の視点を広げていくお考えはありますでしょうか。","respondent":"中島経理課長","answer":"委託業務の中で今現在そういった要素は入れておりませんけれども、今後私ども、いわゆる工事等での総合評価方式も今検討に入ったところなんですけれども、そういった中では、例えば建設防災協議会なんかに入っている業者については一定の点を付与しようと今。","voiceIndex":46,"id":"exchange-020"},{"speaker":"阿部委員","kind":"質問・要望","question":"１割ですけれども、恣意的なものも入り込んでくる可能性がある。それぞれの案件についてどういった評価点を配分するのかといったことなどはある程度公開されていくのか、あるいは、どこかで意見を聞いていくような場ができていくのかということを教えてください。","respondent":"中島経理課長","answer":"私ども今回の総合評価方式を検討したときにやっぱり、評点の公表というのが検討の大きな要素になりまして、そういった公表に耐えられるような評定というんですか、あるいは評定項目も含めて、していかなければいけないだろうということで、現在はまだ公開しておりませんけれども。","voiceIndex":48,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、総合評価方式による導入に至った目的、背景について、もう少し詳しく教えていただきたいと思うんですけれども。目的のところで、価格のみの競争になじまないものについてとありましたけれども、逆に今までの契約の中でどのような不具合が生じていたのか。先ほども若干説明がありましたけれども、具体的にもう少し詳しくご説明いただけたらと思います。","respondent":"中島経理課長","answer":"そういったことも受けて私ども、今回の総合評価方式の検討に当たっては、やっぱりやらなければいけないということを感じたです。","voiceIndex":50,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のご説明の中で、全所管に向けて調査をしたというお話がありましたけれども、それはいつ、どういう調査を行って、それがまた、いつ返ってきたのかということと、そこから検討に入ったというお話が今ありましたけれども、検討委員会というものがあったのかどうかわかりませんけれども、検討のメンバーといいますか、ちょっとその辺の経過を追って教えていただきたいのが１点です。","respondent":"堀越行財政改革担当課長、中島経理課長","answer":"総合評価方式の実施要綱については経理課のほう中心で行ってきたものですけれども、その取り組みに当たっては我々企画部の人間も入りまして、企画財政課と経理課の人間を中心に検討を進めるとともに。具体的にどんな意見がというご質問ですけれども、総合評価方式にかかわる部分では、例えば給食調理業務委託については単に価格の選定だと業者ごとの質による差が出ているというような意見もありますし、ほかの意見では。","voiceIndex":52,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、全庁的な調査を行う中でいろいろ声が上がって検討したということで、今、給食の調理代行のこともありましたけれども、きょうの資料の中で対象業務の中に給食の調理代行や運営業務委託、ここにはすまいるスクールのこと、窓口業務、ここには図書館窓口業務のことなどが載せられておりますけれども、例えばこの３つの中で今回総合評価方式を導入しようとした一番の理由というのは。","respondent":"中島経理課長、堀越行財政改革担当課長","answer":"例えば調理代行なんかはまさにそういう業務の筆頭かなと考えていますし、経験なんかも当然、品川区はこういう給食を提供しています、こういうやり方なんですよというようなことも、やっていて。調査のほうは、昨年７月に実施しているものです。","voiceIndex":55,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"今までは、いわゆる価格だけだったと。価格は数字で決まることだけにね。その辺について、どういうふうにお考えがあるのか教えていただきたいなというのが１点です。いわゆるブラックボックス化、法改正に向けて検討していくという話もありましたけれども、ブラックボックス化させてはいけないと思いますので、考え方を教えていただきたいと思います。","respondent":"中島経理課長","answer":"それと、どうして総合評価かというお話もございましたけれども、今、私どもの特に委託業務の考え方では、先ほどちょっとご説明いたしましたけれども、入札方式がありまして、片やプロポーザル方式があります。両極端なんですけれども。","voiceIndex":58,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"例えば、すまいるスクールの問題で言えば、現在専任指導員は１人ですけれども、私は複数配置が必要ではないのかなと常々主張しているわけですけれども、区の質の高いサービス提供というのはどこにポイントを置くのか、その基準は一体どこなのか、その辺はどういうふうに明確にしていくのか、ちょっと抽象的な質問で申しわけないですけれども、お考えをお聞かせください。","respondent":"中島経理課長","answer":"ただ、実際、そういったことをもとにして契約して、実際それが履行されてない場合につきましては、当然、指導する場合もありますし、今後例えばモニタリング等を今検討しているところですけれども、そういった中で検証もできるわけですから。","voiceIndex":60,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"会社が品川区だけ１社ということはおそらくないでしょうから、ほかのところとも契約を結ぶことが多いと思うんですよね。そういう場合ではどういうふうに職員の状況、いわゆるころころ変わるという問題、この総合評価の中で把握しようとしているのか、お考えを教えてください。","respondent":"中島経理課長","answer":"例えば私どもで当然、実施要綱に基づいてヒアリングのもとになる評定基準表をつくりますけれども、そういった中では、それをもとにしながらヒアリングの際には当然、ほかの自治体での実績があるのかないのかといったことも聞きますし、ほかの自治体との業務がどういう業務なのか。","voiceIndex":62,"id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"ちょっとだぶっていたら申しわけないんですけれども、この導入の経緯の中で、今まで競争入札していて、競争入札は価格が大原則になるので、それにはなじまないというか、今までの経緯の中で、やはり業務がしっかりできるかどうか、能力、そういったものを加味したほうがいいよというので導入されたということなんですが。","respondent":"中島経理課長","answer":"通常、委託関係で随意契約をやるものは一定の金額以下のものですので、例えば、ここで表にありますけれども、予定価格５０万円以下の委託関係なんかにつきましては随意契約をやるということがあります。","voiceIndex":64,"id":"exchange-028"},{"speaker":"武内委員","kind":"質問","question":"わかりました。それから、別紙１のほうで評定基準表というのがあるんですけれども、これは５０点になっていますけれども、1)から5)までありまして配点とあるんですけれども、配点は例えば単純に１０点ずつなのか、それともその業務に合わせて3)が１５点になるんだよとか、そういうふうになっているんでしょうか。","respondent":"中島経理課長","answer":"それと、先ほど申し上げましたけれども、必須項目を設けていただきまして、一番重要だと思われる部分につきましては比較的多めの配分にしてもらって、その配分のものが一定程度以下だったらば対象除外とするようなことも、現在考えてあります。","voiceIndex":66,"id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"選ばれた業者のほうに、あなたはこういうことで、価格はこうですけれども、それ以外のところでは何点ですよという、その業者には点数が一定通知されるということなんですけれども、それについて例えば漏れた、残念ながら引っかからなかった業者が、自分のところは例えばこういう内容としても自信があったんだけれども、なぜこんなに低いんだというようなときに。","respondent":"中島経理課長","answer":"説明してほしいというのは、ございませんでした。来れば、どこまで説明できるかというのはあるんですけれども、例えば相手の業者が納得できるような説明はしていきたいと考えております。今年度、実際に問い合わせはございませんでした。","voiceIndex":68,"id":"exchange-030"},{"speaker":"武内委員","kind":"質問","question":"これ、１０月１日からですよね。そうすると、今おっしゃっていたのはどういうことなんですか。これはまだ始まってないという認識なんですけれども。","respondent":"中島経理課長","answer":"平成１９年度で試行実施していますので、その中で出てくるかなということで、実際には出てこなかったです。","voiceIndex":70,"id":"exchange-031"},{"speaker":"武内委員","kind":"質問","question":"これは本当に実際どうかわからないですけれども、入札のほうでは、例えば指名入札でも残念ながら多分、仕事の種類に応じてなんでしょうけど、１社しか指名してないというのも現実はあるんでしょうか。そうすると実際、指名にならないと思うんですけれども。区のほうである仕事をやるのに、その仕事が、おそらく区のほうでは、この１社しかできないんじゃないかということでの指名でしょうか。","respondent":"中島経理課長","answer":"基本的には最低２社以上ないと競争になりませんので２社以上を原則としておりますけれども、通常指名する場合は１０社前後を指名して、なるべく競争して、いいものを安く入れたいと考えてやっているです。","voiceIndex":72,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"受託者の決定のところに、1)に価格書の額が予定価格の範囲内であること、これがかなり大きな比重を占めているわけですけれども、予定価格というのはどのような考えでどういうふうに算出されるのか１つお伺いしたいのと、あと価格外の要素のところで技術的な能力がすごく大きな重みを置いているわけですけれども、技術点、能力を判定していくのはなかなか難しいと思うんですね。","respondent":"中島経理課長","answer":"予定価格の考え方ですけれども、これは物によっていろいろなやり方がありますけれども、例えば見積りをとる場合ももちろんありますし、例えば調理関係の仕事なんかは既に何年も前からやっておりますので、そういった実績を見ながら。","voiceIndex":74,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"予定価格というのは見積りとか実績を見てということなんですけれども、そういった面ではかなり信憑性というか大事な要素を持っているんで、その辺の価格に対する評価ですか。よい待遇のところにはよい人材が集まる、そういった面での給与に対する評価なんかもどういうふうになっているのか、その辺も盛り込まれているのかどうか、教えてください。","respondent":"中島経理課長","answer":"そういった意味では価格で、例えば入札でしたらばそれこそ１億円から、極端な話１００万円までの何千万円の差が出てくるということがありますけれども、総合評価でもって価格点で換算した場合には、上下の差が２０点しかないところでは。","voiceIndex":76,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"給与の把握はしない、その辺はそうであると思うんですけれども、当然だと思いますけれども、そういった待遇とか人を大事にしているかどうかというのは、とても大事な要素であると思うんですよね。私は、評価の表をつくっていく段階で、どういった中身を聴いていくのかというところがすごく大事であると思うんですけれども、ぜひその辺を重視していただきたいなと思いますが、いかがでしょうか。","respondent":"中島経理課長","answer":"それと２点目といたしまして、総合評価競争入札において落札者を決定しようとするとき、予定価格の制限の範囲内の価格をもって行った申込みのうち、価格その他の条件が当該普通公共地方団体にとって最も有利なものの決定かどうかということも。","voiceIndex":78,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"今、指定管理者制度もかなり広がっている中で、指定管理者のところでも委託とか再委託とか行われているわけですけれども、平成１９年度試行ということなんですけれども、方向的に区が責任を持っていくというところでは、指定管理者のところでも、このような総合評価の方法を取り入れていく方向にあるのかどうか、その辺のお考えも聞かせてください。","respondent":"堀越行財政改革担当課長","answer":"指定管理者の選定の部分でのご質問という形でよろしいですか。","voiceIndex":80,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"意見","question":"指定管理者が行っている委託とか再委託のところに関して、区がより責任を持っていく、区が指定管理者に認めた先の委託でも、結構この間問題が起きていますよね。今後の方向なんですけれども、今、区で始まったばかりなんですけれども、今後の方向として指定管理者がこれから広がっていく中での委託、指定管理者が行う委託、再委託に関しての契約のことです。","respondent":"堀越行財政改革担当課長","answer":"指定管理者が行う委託、再委託の部分ですが、再委託するに当たっては文書等で区のほうに確認、承認を求めるような形で再委託をするようにしておりますし、先日ご報告させていただいたモニタリング評価のガイドラインの中においてもありますように。","voiceIndex":82,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"そこを経過して、先のことで伺ったんです。現段階は今そうやって努力されているところで、モニタリングの中にも再委託の項目がありますよね。この簡易型総合評価方式ぐらいに厳しく指定管理者のところでもやってほしいなという思いがあるので、今後の方向性として伺ったんです。","respondent":"堀越行財政改革担当課長","answer":"ですから、今の定めております仕組みを使って、適切に管理をしていきたいと考えております。","voiceIndex":84,"id":"exchange-038"},{"speaker":"林委員","kind":"意見","question":"委託契約の概要にある１番目の目的の４行目にあるんだけれども、業務の質の担保と不良不適格企業の参入防止を図る。これは何もこの総合評価じゃなくても、競争入札方式でもプロポーザル方式でも、このことは区が契約する業者を話し合う上で絶対なければいけないことでしょう。これがなければできない。変なとり方なんだけれども。","respondent":"中島経理課長","answer":"それで私ども、これで入れているのは、総合評価方式の場合、先ほど申しましたヒアリングを実際実施しますので、いろいろ運営方針だとか勤務体制、執行体制とかいろいろ聞いていく中で、こういった不良業者についてはより排除しやすいという部分で。","voiceIndex":86,"id":"exchange-039"},{"speaker":"林委員","kind":"質問・要望","question":"課題を解決するために総合評価方式という方式が１つできてきて、今、経理課長がおっしゃられるようにヒアリングとか。それができるかどうかは検討していただきたいと思いますので、お願いしておきます。それから、要綱についてさっきの話で１０月１日からの施行で、先ほど来給食のことの指摘がされているけれども、これではない要綱に基づいて行ったものだよね。","respondent":"中島経理課長","answer":"今回はその試行した検証等を行いまして、その結果を踏まえて平成２０年度から、この試行に基づいてやったものをさらに拡大して実施していくということで、この要綱を定めたものです。","voiceIndex":88,"id":"exchange-040"},{"speaker":"林委員","kind":"確認","question":"１つ確認したいんだけれども、要綱の中の価格の点での表がありますよね、６ページに。５０点を限度にするということですから、価格の面では５０点が最高点になる。そうすると逆の見方をすると、この５０点というのは、８０％だと５０点だよね、単純に。これ、最低制限価格になりませんか。","respondent":"中島経理課長","answer":"実際、最低制限価格という形での位置づけはとっておりませんけれども、おっしゃるように最低制限価格と同じ考え方になると考えています。","voiceIndex":92,"id":"exchange-041"},{"speaker":"林委員","kind":"質問","question":"だから、例えば１億円で８，０００万円、それより下げても点数は同じだと。予定価格が１億円、では、どうしてもとりたいと思えば８，０００万円を入れてくれば、それ以上の点数はないんだから、価格点では最高点ということになるわけで。それは品川区の、いわゆる入札とは呼ばないけれども、入札の仕組みの中で最低価格を入れてきたんだというふうに理解をしておかなければいけないですか。","respondent":"中島経理課長","answer":"こちらにつきましては、失格にはならない。８割の人も７割の人も、同じ５０点でもって勝負できますよという部分では、効果とすれば、委員のおっしゃるような最低限価格の効果がありますけれども、全くイコールではないところです。","voiceIndex":94,"id":"exchange-042"},{"speaker":"林委員","kind":"質問","question":"Ａ３の表に戻るんですけれども、プロポーザル方式のほうでちょっとお聞きしておきたいんですけれども、評定ですけれども、総合評価方式のほうではきちんと今、点数化で評価していく、２ＷＡＹでやっていく。プロポーザル方式のほうが、私が聞いていた範囲では、審査委員会で採点をして、何社かに絞った上で選定委員会を開くというような話、その辺もうちょっと詳しく説明してくれますか。","respondent":"中島経理課長","answer":"そういった部分では一度、評定という形で採点をした上で、例えば上位３社について選定委員会を開いて、そこでもう一度意見交換しながら決めていくという形をプロポーザル方式はとっていくです。","voiceIndex":96,"id":"exchange-043"},{"speaker":"林委員","kind":"意見","question":"２段階にしていくということで、より慎重にということで受けとめられるんだけれども、そうすると、言葉尻をとっているようで悪いんだけれども、区が望むもの、事業部長であったり審査会の方々のお考えで、区が望むものを決めていくとなると、例えば大きい案件だと議決が必要になってきた場合、一方、価格であるんだけれども、一方で区が望むものという。","respondent":"田中総務部長","answer":"もともと、きょう、経理課長が冒頭からご説明したとおり競争入札という価格の、いわゆる競争でもってすべては決まってきたわけですけれども、この中でプロポーザルというのは、昔、設計業務がいわゆるコンペ方式とかそういう方式の中で登場したものでございまして。","voiceIndex":98,"id":"exchange-044"},{"speaker":"林委員","kind":"提案","question":"国の動きを注視していると書いてあるんだけれども、現段階で国のほうはどっちの方向を、簡易型と厳密型というのかな、間を提案というか、国として認めていくような流れというか方向が見えるのか、土木だ何だというのもひっくるめて全部、いわゆる総合評価という学識経験者を含めた形は動かないだろうと読んでいるのか、その辺の見通しをお聞かせください。","respondent":"中島経理課長","answer":"国土交通省の考え方が、平成１７年に工事の品質を確保していくということでいわゆる品確法というのを定めまして、それはまさに質のよい工事をすることによって将来にわたっていい財産、国民の財産を残していくという考え方がありますので、基本的には。","voiceIndex":100,"id":"exchange-045"},{"speaker":"阿部委員","kind":"質問","question":"先ほど、試行を本年度から始めているということだったんですけれども、試行されてみて、制度上あるいは運用上課題と思われる点がありましたら、出てきたものがありましたら、教えてください。あるいは、あくまでも価格は５０点ないし、それに近いようなもので、その他の項目が合わせて５０点みたいな感じになっていくのか、そういった基本的な考え方がもしあれば、教えてください。","respondent":"中島経理課長","answer":"２点目のほうから先にお答えしますけれども、試行を実施した結果、結果的に見て、バランス、評定のバランスは、結果的に意外とよかったなと感じております。そういった意味では当面、５０点、５０点という考え方でいきたいと考えています。","voiceIndex":102,"id":"exchange-046"},{"speaker":"阿部委員","kind":"質問","question":"評定の言い方がちょっと私、よくなかったかもしれないんですけれども、今、技術点と価格点でいっているときに５０点、５０点というのは、多分それで決まりなんだと思うんですけれども、技術と価格以外の評価の視点が出てきたときの考え方があればいうことで、お伺いしました。","respondent":"中島経理課長","answer":"まだ、その辺までの具体的な検討をしていませんけれども、例えば５０点、５０点プラス例えば２０点という要素を設ける場合もありますし、逆に技術点の５０点の中にそういう要素を組み込むという考え方もありますし、その辺は今後の検討課題だと考えています。","voiceIndex":104,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"私はこれが基本なのかなと思って見せていただいたんですけれども、きょうのご説明によると、かなりヒアリングが行われたり、その案件によって違うということなんで、試行されているところの枠組みだけでも、こんなところを重視しているんだなという、必須項目とかいろいろご説明があったんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-048"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"今の９ページの評定基準表、この中身はわかりますからいいんですけれども、配点をしますよね。それと現場説明会、概要の中にありましたけれども、今、契約関係の中で、工事関係と現場説明会をやってないんですよね。それは今後において簡易型ではなく総合的になっていったときに、現場説明会をやめた理由と、ここがまた出てくる、そこら辺の兼ね合いはどういうふうに考えているのか教えてください。","respondent":"中島経理課長","answer":"１つ懸念されている談合等につきましては、この総合評価方式そのものが談合を防ぐという方式そのものでございまして、要するに価格でもって談合しても、こちらが別の要素でもって評定しますので談合が成立しないという要素もありますので。","voiceIndex":114,"id":"exchange-049"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今の話の中で、１年間の管理状況についての報告というお話がありましたけれども、いわゆる今回の議会への報告というのは決算報告的な、そういう位置づけなのかどうか、それの考え方を教えていただきたいというのが１つです。もう１つは、年に１回この時期に今後も行うということなのかどうか、それについても、あわせてご説明いただけたらと思います。","respondent":"堀越行財政改革担当課長","answer":"今後、いろいろな運用の中で１年間のモニタリング評価の結果が出た段階で、各所管委員会においてご報告をする、そういう予定です。","voiceIndex":122,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"議会には、例えば一般会計予算でも特別会計予算でも決算書というのが出されるわけで、審査をされるわけですけれども、指定管理者の決算報告というのですか、そういう仕組みというのはどういうふうに考えていらっしゃるのか、もう少しご説明いただけたらと思います。","respondent":"堀越行財政改革担当課長","answer":"１年間の成果について、管理状況についてご報告をさせていただいたものでございまして、多少なりとも決算報告的な意味合いもあるかもしれませんが、モニタリングガイドラインを定めております１年間ごとに評価を行っておりますので。","voiceIndex":124,"id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"１年間の管理状況を把握する意味でも、数字上の収支の決算がどうなのか。業務の重点方針、組織管理体制、決算説明資料が載せられているわけですから、今回の報告の中にぜひ事業報告書は載せるべきではないかと思っているのですね。それについてご見解と、今回の総括シートだけの資料で十分だというふうに認識されているのか、今後研究するものがあるのかどうかも含めて、ご説明いただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"今、収支決算書等というお話でしたけれども、収支決算書、事業報告書をそのまま出すというよりも、施設の設置の責任者である区としてそれを受けて、どのようなモニタリングですとか評価をしたのかということを一定整理させていただいて。","voiceIndex":126,"id":"exchange-052"},{"speaker":"中塚委員","kind":"質問","question":"先ほどのご説明の中でも、１年間の管理状況、いわば決算的な要素もあるんではないかというのであれば、やはり収支決算書が載せられた事業報告書を添えて議会に報告することが必要ではないかと思います。３年だったり５年だったり。次年度の事業計画書に沿っても、事務事業概要の時期と合わせてそれぞれ報告すべきではないかと思いますけれども、最後、いかがでしょうか。","respondent":"堀越行財政改革担当課長","answer":"年度を超えてどうかというお話がありましたけれども、そのことにつきましても、この１年間の評価をする中で、またご報告をする中で、総括シートの中に改善が必要とされた事項ですとか改善方針、サービス向上の視点。","voiceIndex":128,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"中身を見ても、不利益に当たるという部分が見たところでは私は感じられないんですが、不利益になるからという話はいただけないんで、どういう意味なのか、何が不利益になるのか。事業計画書は不利益になることはなく、自分たちがこうやっていきたいという計画書ですから、ちょっとおかしいんではないかなと思うんですけれども、長くなってしまいましたが、最後にご見解をいただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"そういった点も加味するとともに、それから、事業計画書を受けて、報告書を受けて設置者である区がどのような観点でどのように考えているかということも加えて整理をして議会のほうでご報告させていただいて、その審議に資するような。","voiceIndex":130,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"職員の体制とかいろいろ、そういった面でもうちょっと盛り込んでいただきたいなと思う意見も多分出されたと思うんです。きのう初めて常任委員会のところで論議がされているんで、私としてはぜひ、その辺のよい面もあるだろうし、問題点も出されていると思うんで、各委員会での状況をちょっと把握をしていただいてご報告をいただけたらなと思うんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-055"},{"speaker":"阿部委員","kind":"質問","question":"まさに昨日の建設委員会でも出たところではありますけれども、例えば区営住宅等の管理についての数字で、管理している戸数が出ていないですとか、そういったところで検討するのは難しいという感もありますので、もし総括シートというのをこれからもベースにするというのであれば、そのシートに書き込む中身が適当であるのか。","respondent":"堀越行財政改革担当課長","answer":"何分今年度から始めたものですので、今後、そういった部分についても必要に応じて見直しは図っていきたいと考えているところです。","voiceIndex":134,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5826#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":43653,"voices":137}},{"id":"h19-20070928-16","meetingId":"h19-cm09","date":"2007年9月28日","dateIso":"2007-09-28","committee":"街づくり特別委員会","time":"午前１０時０３分～午後０時１３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"日程に入ります。 特定事件調査の地区計画に関することのうち、景観","agenda":"日程に入ります。 特定事件調査の地区計画に関することのうち、景観","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと大きなところで聞きたいですけれども、２ページの景観法の特徴というので、国の景観法の特徴の説明はそうだと思うんですけれども、責務というところで、「住民」というところですが、「自ら良好な景観形成に積極的な役割を果す、国や地方公共団体の施策への協力」というのがあるんですけれども、これ、国としてはこういうふうに景観法の特徴としていることだと思うんですけれども、近年。","respondent":"阿部都市計画課長","answer":"先ほど申し上げましたけれども、景観をつくっていくためには、地域の方の行為も当然重要になってまいりますので、先ほど重点地区の中でも、地域の方と一緒に進めてまいりますから、そういう地域の協力が得られなければ。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"何かすごく一般的なお答えだったなと思うんですが、それにちょっと関連して、前回の１カ月前の街づくり特別委員会のほうで、景観に関する質疑があったんですけれども、前回、大崎駅周辺のほうが当時はモデル地区と言っていたと思うんですけれども、重点地区に入っていなかったと記憶をしているんですけれども、この１カ月の間に大崎地区のほうから要望といいますか、モデル地区といいますか。","respondent":"阿部都市計画課長","answer":"もう１点は、先ほど一般的な回答だということでございましたけれども、ここに書いてありますのは、国あるいは地方自治体、事業者、住民それぞれがこういう責務を持って、景観づくりを進めていくですので、一般的ということはなくて、それぞれが責任を持って。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区のほうから１３町会の説明会で、こういう景観計画を今、策定しようとしていますので、モデル地区になりたい方は手を挙げてくださいと言ったところ、旧東海道のほうからはそういう手が挙がったという話だったんですけれども、だから、以前から熱意があったというのは事実だと思うんですけれども、こちらのほうから指定するというよりも、手が挙がったところに対して。","respondent":"阿部都市計画課長","answer":"そういうものを進めていきましょうということで、先ほど委員からもお話がございましたけれども、私もすべての町会の中で話をして、今後、まちづくりを区と一緒に進めてまいりましょう、どうですかというところの中で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと前回のモデル地区は旧東海道の合意だというふうに答えたのは何だったのかなというのは、ひとつお伺いしたいなと思ったのと、あと、これから品川区全体には全体的な景観計画というのを立てるということで、特別な地域には仮称重点地区ということで、細かな例えば色彩ですとかその他を定めていくということなんですけれども、その品川区全体の景観計画というのは、どんなイメージなんですか。","respondent":"阿部都市計画課長","answer":"ただし、品川区全域の景観のあり方、基本理念と申しましたけれども、それは区内全域の基本理念を定めてまいります。先ほど申し上げましたけれども、旧東海道については、より具体的な方針を定めていくという考え方です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それで、この重点地区なんですけれども、これからやっぱり地域の中には、特に今回は景観計画では縛り、強制力はつけられないというご説明がありましたけれども、特に高さとかの問題で、各地域からうちの地区も高さ制限をしたいから、重点地区になりたいんだというお話がこれからも出る可能性があると思うんですけれども、そういう場合に、条件というと変なんですけれども、重点地区として。","respondent":"阿部都市計画課長","answer":"その地区計画については、どのぐらいの合意が必要かということが、基本的にはございませんけれども、既に南品川三丁目で今現在しておりますけれども、そこにつきましては地区の方が、みずから合意形成を図ってまいりましたので、そういう形で。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"１ページ目で平成１５年７月に「美しい国づくり」云々ということで、国の考え方というものがある程度出た。その前に東京都の景観計画の段階で運用する前の状況の中で、この４ページ目のしながわ景観ガイドプランというのが、その東京都の計画をベースにつくられたのかなというふうに、年代をちょっと追ってみたんですけれども、そのような解釈でよろしいでしょうか。","respondent":"阿部都市計画課長","answer":"品川区の景観ガイドプランにつきましては、たしか平成１４年ぐらいからだと思いますけれども、検討は開始しておりました。","voiceIndex":15,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"そうしますと、品川の景観ガイドラインは、直接的には区の動きを見据えてつくられたということと、都をベースにしていない、都の景観計画をベースにしていないということなんですが、同じ景観という名前がついているので、多分、いろいろな意味で、都の計画と整合性をとるというんでしょうか、横目で見ながら、いろいろ進められていると思うんですけれども、そこら辺の調整。","respondent":"阿部都市計画課長","answer":"ただし、先ほど申し上げましたけれども、そういうものにつきましては、重点地区と申しましたけれども、具体的には旧東海道のところで、今地域の方々とどういう形の基準ができるのだろうかという検討を行っているです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"高さや意匠とかはおおむねわかるんですけれども、色彩の基準というのが、数値基準の徹底とか考えられているんですけれども、イメージとして旧東海道の保全とか、非常にそういうふうな趣旨かなという理解なんですけれども、もう少しこの色彩の基準ということの数値基準、その辺ちょっと詳しく教えていただきたいんです。","respondent":"阿部都市計画課長","answer":"それを数値基準として決めていると。なかなかちょっと理解が難しいかなと思うんです。そういうことです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"既存の建物なんかと調和がとれるようなというあれで、非常にどぎつい色とか、一般的に使わないようなものはだめだというような理解でいいんだと思うんですけれども、あとそれと、この景観と屋外広告物と、分けて条例がつくられていくんだと思うんですけれども、この屋外広告物のほうなんですけれども、そういう条例をつくったときに、今の都の条例で適合しているものが既存であると思うんですけれども。","respondent":"松代管理工事課長","answer":"今ご質問の、それを違反したものについては、当然私どもそれを摘発しまして、違法物件という形で取り扱いをして、それを基準のものに直してもらうといったことを今現在はしていますし、今後、そういったものが出てきた場合は、このような形で対応していきたいと考えています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"今の本多委員の関連なんですけれども、先ほど違反に対しては摘発云々と、是正してもらうということなんですが、これは勧告で終わってしまうんですか、それとも是正、こちらからの指導に対して強制力を持つものですか。","respondent":"松代管理工事課長","answer":"申請があればいいですし、申請がない場合は、その申請がない限り、それは違法物件ということで、ぜひ説得をして、改善してもらうように進めているといったものが現状です。","voiceIndex":25,"id":"exchange-010"},{"speaker":"大沢委員","kind":"意見","question":"違法性があるのかないのかと。区が指導をする、勧告は強制力を持ったものなのか、持っていないものなのか。逆に既存不適格であれば、費用的なものいろいろがあって、直す、直さないでいろいろ時間もかかるので、そういった場合に別の法も適用されることがあるのか。","respondent":"岩田まちづくり事業部長","answer":"それと景観法の中で指定された規制を守らずに建物を建てようとした場合には、法に基づいて、重点地区内であれば、変更命令が可能、強制力を持たせてあります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろな品川区でやる問題としては、形態と色彩とその他の意匠ということで建築物と工作物に対して届出をすると、手続の対象になるということなんですが、高さや壁面は地区計画で決めるということなんですけど、これは品川区の計画、あるいは条例に入ってこないで、地区計画というふうに外れているというのはどういうことなのか、ちょっとわからないので、教えていただきたいと思います。","respondent":"阿部都市計画課長、岩田まちづくり事業部長","answer":"地区計画につきましては、先ほど申し上げましたけれども、地区の方の合意を得ながら進めていくというものですので、区としては地区計画を進めてまいりたいと考えています。ですから、そういう面では、過去に区が地域に入って失敗をしました旗の台地区とか、いわゆる御殿山、池田山地区のような、当然、旧一種住専の保存すべき地区として区は考えておりますけれども、これから各地区に入って。","voiceIndex":32,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"地区計画で決めると、それに対して、先ほどそういうふうに答弁されたんですけれども、地区計画自体と、その重さというのかしら、よくわからない、拘束力と、それから条例での拘束力というところのその基準というのか、そういうものの関係がどうなっているのか、ちょっと教えていただきたい。","respondent":"岩田まちづくり事業部長","answer":"先ほど、課長が説明しましたように、１ページに書いてあります、もともと国がこの景観法というのをつくった背景は、建物の高さとか、それからセットバックとか、こういう建築物にかかわるものについては、現行法の都市計画法に基づいて制限がかけられたんです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ教えていただきたいんですが、かなり強制力を持った景観法ということで、期待は大きいんですけれども、まず４ページにあります、東京都との協議により「景観行政団体」になることが可能ということが書かれているんですが、これは先ほどの管理団体になるという意味なんですか。これによって何か品川区のメリットというのがあるのか。","respondent":"阿部都市計画課長","answer":"２点目の地域の合意ですけれども、今申し上げましたように、既にモデル地区としているところでは、まちづくり協議会の方々と、その旧東海道の景観づくりをどうしていくかと考えていますけれども、当然、そこで話し合われたことは、商店街あるいは町会。","voiceIndex":37,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"これはいつごろという、スケジュール等々あるんでしょうか。全体的な、これを使って今進んでいるところを見てみて、強制力も含めて、権限力も含めて、発揮できるのはいつ頃見えてくるものなのか、そのスケジュールをお聞きしたい。","respondent":"阿部都市計画課長","answer":"スケジュール関係は、一番最後の９ページにありますけれども、９ページの一番上、「現在」と、ここに書いてありますけれども、地元のまちづくり活動団体、まちづくり協議会の方を中心として、今現在、こういうルールを検討中の段階です。","voiceIndex":39,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"スケジュールの件ですが、今年、平成１９年度で原案を策定するという形で、ちょっと見ると、まだまだ後だと。この後というのは、二、三年というレベルになるかどうか、その大体の目安はあるんですか。","respondent":"阿部都市計画課長、岩田まちづくり事業部長","answer":"はそこの合意をとっていくというのがやっぱり重要だと思っていますので、それに去年、今年と入っているわけですけれども、やっぱり地域の方々との話し合いの中では。ちょっと補足しますが、今課長が言いましたのは９ページでございまして、既に品川区全域は東京都の景観計画が走っておりまして、既に網がかかってしまったんです。","voiceIndex":41,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、これからどういうレベルで進んでいくのかなというところが、ちょっと気になって質問をさせていただいたんですが、同時並行で進んでいくんでしょうけれども、皆さんに理解をしていただいて、大分早く強制力が入るような形に持っていっていただきたいなということで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"今度、その世代が変わったときに、私たちは違う方向で持っていきたいんだとなったときに、その地区計画の変更等、それから景観法の縛りを排除するというようなことは、この中には今書いていないんですが、それは容易にできるんでしょうか。そういう可能性はあるんでしょうかということをちょっとお聞かせください。","respondent":"阿部都市計画課長","answer":"ですから、委員ご指摘の、例えば１００年後にその地区がどうなのか、全く今と逆のこともあり得るのかですけれども、まちづくりというのは長い期間で進めてまいりますので、例えばその中で、１００％変更になるということは将来的にはありかもしれませんけれども。","voiceIndex":45,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"あるいはある程度こういうふうに住民の合意がまたあれば、変更が可能なのかというところは、やはり皆さん気になるところもあると思うんですが、再度、もしお答えできなければあれですが、ある程度もし、万が一方向変換、百八十度とかあった場合に、その変更できる可能性というのはあるんでしょうか。その１点だけお願いします。","respondent":"岩田まちづくり事業部長","answer":"それで、委員がおっしゃるように、一度議会の議決を得ていただいて、規制をつくります。何十年かたって、地域の方たちがやっぱりこれは不都合だと、変えたほうがいいという声がほとんどになった場合に、理論上は景観計画の変更を持ち上げることは可能です。","voiceIndex":47,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えてください。看板なんか、屋外広告物も含めて、これはおかしいだろうというのは結構まとまる。多分、これは計画的にはある程度進んでいく話だろうと。これを乗せることによって、また厄介なことになっちゃうんだったら、乗せないほうがいいと思うのか、そこら辺の感覚をちょっと教えていただきたい。","respondent":"阿部都市計画課長","answer":"ただ、ほかの地区で地区計画を定める場合には、正直言って、その景観について制限を定めるということはなかなかできないというふうには思っておりますけれども、地区計画の中では、景観についても配慮するということで、一応考えていただくという事項に定めてまいりますので。","voiceIndex":49,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"重点地区の話は結構です。もう大体わかったんです。だけども、地区計画がありますよね。それで、地区計画がかかっている、大きいところがありますね。あるいは東品川四丁目地区とかも地区計画をかけている。そこに景観の部分のものを入れ込んでいくのか、今言った、その景観の部分をしっかり計画として入れ込んでいくのか、それでもなきゃ、あそこなんかそんなに数があるわけじゃないじゃないですか。","respondent":"岩田まちづくり事業部長","answer":"特に昭和６０年前後に地域に入って失敗をした例が、一種住専の地区がありますので、やはりきちっとした入り方で、粘り強く話し合いをしながら、まず機運を高めていくことが必要だと思いますので、そういった面では全地区を視野に入れて、頑張っていきたいと考えています。","voiceIndex":51,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうところには、地区計画なのか、何がこういう景観なのか、こういうものをつくっていきましょうというものを、どういうような形で、その入っているコンサルの人も言っているわけだから、地区の声も挙げ、もちろん地区の協議の内容もご存じだと思うんだけれども、そのときにどういう方向性がいいんでしょうかねというのがありますね。景観の部分だけなら。そういうことをお聞きしたいのが１つ。","respondent":"阿部都市計画課長、岩田まちづくり事業部長","answer":"ただ当面は、まずは旧東海道で具体的な基準をつくる。はそれに取り組んでまいりまして、その後に、今、部長が申し上げましたけれども、ほかの地区にもさらに働きかけてまいりたいと考えています。ただ、地元の意識とすれば、景観という考え方で何とかしようというお気持ちは、まだそこまで熟度は高くありませんけれども、実はあの地区は地中化に合わせて、いろいろな提案をされてきておりますので、当然、あそこの動きというのは。","voiceIndex":53,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"じゃ、もうちょっと道路を広げようよとか、そういう話になってくると、必ずかかってくるのは、地区計画みたいな形になっちゃうんじゃないですか。なおかつ、それを踏まえて、コンサルの方々と、違う方法もあるんじゃないですか。この景観を守る、それから例えばその状況を守るには、違う方法もあるんじゃないですかというのは、コンサルの人はあまり言えないわけです。","respondent":"岩田まちづくり事業部長、山路委員長、家壽田下水道河川課長","answer":"委員おっしゃるとおりですので、私ども、これだけの管理職が首をそろえておりまして、直接景観法に関係する部署の者もいれば。ほかにございませんか。ほかになければ、以上で、特定事件調査を終了します。それから運転時間におきましても、結構水質についても、夏場と冬場では違うということもわかってきていますので、３６５日回しっ放しというのは。","voiceIndex":56,"id":"exchange-023"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"落合水再生センターから、処理水の放流という話がありましたけれども、これは淡水だということですけれども、ちょっと聞いたんですけれども、流される処理水の水量がちょっと減ってしまったので、その目黒川自体の水量が減ってしまい、流れがちょっと滞ってしまい、それがちょっと水質改善効果もなかなか上がらない理由なんじゃないかみたいなことを伺ったんですけれども、そこに関する因果関係などと。","respondent":"家壽田下水道河川課長","answer":"それに対して、当区を初め、この城南の各区では、やはり水が減らされては困るということがございまして、現在は区のほうで半額の運転費を、予算を各区が計上しまして、都のほうにお支払いをして、それでそもそも考えている計画量１００％を流すということで、現在。","voiceIndex":62,"id":"exchange-024"},{"speaker":"安藤委員","kind":"意見","question":"水量をもう少し多くするというのは可能なのかということと、それをやることによって、水質というのは改善する見通しがあるのかどうかというのを、ちょっと知りたいんですけど。","respondent":"家壽田下水道河川課長","answer":"実際には量は増やせませんし、先ほど説明したとおり、淡水を幾ら出しても、目黒川の改善したいところにはまざっていかないということがわかっておりますので、我々としては、清流復活水を増やすのではなくて、違う手法で何とか目黒川をきれいにしたいと考えております。","voiceIndex":64,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"あれを物理的にできるのかどうかわかりませんが、例えば河口を仮にふさいだとしますよね。ふさいで、ポンプで海側に流すと。そうすると、そこには流れというのは生まれるのではないですか。干潮のときはもちろん自然と流れていくんでしょうが、そういう取り組みというのはあるのか、実際、物理的に不可能なのか、その辺何かお考えというのはあるんでしょうか。","respondent":"家壽田下水道河川課長","answer":"目黒川につきましても、下流側の川幅が２５メートルほどの幅がありますので、そこをせきとめて、そこを四、五メートルぐらいの高さをつくるとなりますと、そのダムの形状というものも非常に膨大なものになってまいりますし、それは当然。","voiceIndex":67,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"停滞しているということで、かなり距離的に長いですよね。その辺、何かいい改善策とか、いい方法があれば、せっかく今回、大崎地区にもああいう水辺の公園もできてくるわけですから、非常に一生懸命取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-027"},{"speaker":"西本委員","kind":"意見","question":"実験なんですけど、だれがするのかということと、研究センターという形になって、それがされるのかなということなんですけど、どのぐらいのお金をかかるのか、区の委託だと思うんですけど、その点についてお願いします。","respondent":"家壽田下水道河川課長","answer":"この浄化の検討につきましては、本年度予算をいただきまして、５,６００万円余りなんですが、区の単独費で調査をしております。","voiceIndex":70,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"ある程度の予測を立てながら、データを積み上げていく形だろうと思うんですが、これはほかの方法が何かありそうだとかという、実験計画の変更ということが当然出てくると思うんですけど、その現実性というか、審査というか、どのぐらいのシミュレーションをもって委託をされているのか、お聞きしたい。","respondent":"家壽田下水道河川課長","answer":"それから報告につきましては、今、実験はこれからやるところですし、水質測定も定期的にやっておりますので、それを取りまとめた上で、年度内、早いうちに、もしできれば３月ぐらいにやりたいと考えていますが、場合によっては取りまとめ等を含めて。","voiceIndex":72,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"もう１点、途中で予測外のことがあったときのこと、それと費用がそれよりかかってしまうという場合にはどういうふうに対処されるんですか。","respondent":"家壽田下水道河川課長","answer":"その調査の結果によって、どういう対策を必要かということについては、我々も全くわかりませんので、これからどういうものが一番いいかというのは、恐らく出てくるんだと思いますので、それは期待して、より安く。","voiceIndex":74,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"これからさらにどのくらいの費用が予測されるのかをちょっと伺っておきたいんですけれども、そういう状況で見たときに、極めて目黒川の水質改善はさっきも言ったように、否定するものではないけれども、これから行っていくあの辺の開発等々の運河ルネッサンスとの関係で非常にクローズアップされてきているのかなと、ちょっと感じるものですから、その辺で費用の部分と。","respondent":"岩田まちづくり事業部長","answer":"いわゆる汚濁物質が入ってこなくなってしまうわけですね。そうすると、いわゆるこれ以上の汚濁物質があそこの中に入ってこなければ、区がやっている今のいろいろな実験を継続的に行えば、水質改善が飛躍的によくなるとうことは、もう先が見えたわけですね。","voiceIndex":76,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そうなると、かなり大きな工事になるんじゃないかと思うので、経費的にもかなりのものが必要になるかと思っているので、検討項目、調査項目と挙げている、ここの必要な経費として５,６００万円というわけじゃないと思うので、その辺、どの程度の規模が必要になるのか、見通しを教えていただきたいと思います。","respondent":"家壽田下水道河川課長","answer":"その規模につきましては、昨年度、概算で検討していますが、まだまだデータ的にもつまびらかになっていないところがありますので、それは今年度の中でも、その事業費をしっかり精査していきたいと思います。数十億円規模ということが今の想定ではあります。","voiceIndex":78,"id":"exchange-032"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここでやる話だろうと思うのであれなんですが、八潮で今、皆さん、大変住民の方がご努力をされて、いろいろ意見調整をされていると思うんですが、その状況報告というのか、それをもしわかれば、ぜひしていただきたいと思います。","respondent":"日下部企画財政課長","answer":"八潮につきましては、先般もご報告していますけれども、地元のほうでは、この間、私どもいろいろなご説明をさせていただきましたが、８月の下旬からまちづくりの検討会ということで進められておりまして、実は明後日の３０日にそのまちづくり検討会の中で。","voiceIndex":83,"id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々のところにもそういう話があるところはある、ないところはないのでありますけれども、当初から、公募をされて、住民の方がやっていこう。そういう気を使わせていること自体がいいことではないと思って、じゃ、本心はどうなんですかとお聞きしたら、いや、それは住民でこういう形で検討会をやってきたので、議員の方の参加はしないでいただきたいという話があったわけですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"今、石田委員のおっしゃった意味がちょっとよくわからないので、整理したいと思っているんですけど、住民の方がそれぞれの会派に参加してもらいたいということを言ってきたと。そのことと、議員が出ていくところの仕切りがどうこうというのはどういうことなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この中で、南委員は住民だということで、オブザーバーということで参加をさせてくれということで、１回目は何も話がないままで参加をされた。それはオブザーバーですからということで参加をされたけれども、何回か発言をされた事実があるみたいです。だけど、私は住民だからと。だから、この中のまさに特別委員会の中で今やっているわけですから、この場で話すということだろうと思って、その他でお話をした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"確かに、私は委員じゃなくて、住民として委員にならせてくださいということで、応募要項というのがあって、４００字の文章を書いて提出しました。後で聞いたら、５０人の応募枠のところ、２６人なので、その中に入れていただいたわけです。まちの問題と、議会の中の問題と全然場面が違う、性格も違う問題ですから、それをここで仕切ってほしいなんていうこと自体、ちょっと私は違うんじゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"まさにここの話なんですが、住民と議員という立場をどう考えるんですか。こっちは住民の方々で、議員という立場をわきまえて、まるっきり別ですということで、やっていらっしゃるというお話だから、そちらのほうがね。それを２６人だから入れてもらって、どうって、案内がどう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"それは向こうがやっていることではないでしょうか。それはあなたが言うことじゃないでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ委員長のほうで、そこら辺の主催をされている方々の意思を確認していただいて、そこら辺の対処をしていただきたいということを、じゃ、要望をしておきます。そうしないと、議員という立場で話をしている話ですので、おかしな話になりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"まちの問題と議会の問題と、たまたま同じ八潮のまちをどうしようかという問題ではあっても、全然質と次元が違うじゃないですか。私も今初めて聞いた話ですから。だから、私はそう言うのであれば、じゃ、ほかの議員だって入れたっていいじゃないですか。どうしてまちの話の中に、議員が来ることがだめなんですかというふうに申し上げましたけれども、その話については全然ないんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-041"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこに今、南委員がいみじくもおっしゃっている、すべての議員が行ったっていいじゃないかみたいな話で、議員が押しかけて、区民の方々が分科会なり何なりの意見をしっかりしている中に、そういうことをまさに入れ込んでいるほうが、議員の立場と住民の方々のそういういろいろ意見集約をする場と、それをまさに混同している話であって、私は議員だから何をしてもいいという話とは違うわけで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"だけど、まちの問題で住民の１人として参加をする。どなただってそういう場面というのはあり得るわけですから。そういう問題に対して制限を加えるような、そういう判断というのは私はやるべきじゃないと思うんです。そこのところもよく考えていただいた上で、調査をしていかないといけないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6352#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":42349,"voices":100}},{"id":"h19-20071002-4","meetingId":"h19-c-settlement","date":"2007年10月2日","dateIso":"2007-10-02","committee":"決算特別委員会","time":"午前１０時０２分～午後５時４７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山元副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。閉会予定時間は、区役所の執務時間と同じく、午後５時１５分を目途といたします。１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。経過時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"以上で決算統計上の数値についての説明が終わりました。 それでは、平成１８年度品川区一般会計歳入歳出決算","agenda":"以上で決算統計上の数値についての説明が終わりました。 それでは、平成１８年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"ここについても、とりあえずここの部分で質問しますと、私立幼稚園と公立幼稚園、ここのかかる費用の一部を助成して公平に支援していこうじゃないかという形の部分だと思いますが、そういう理解でよろしいのか、あと、ここに出ている８,８９７万円ということは、現在私立幼稚園に通っている約６割弱ぐらいなのかな、そこぐらいの園児の保護者に出されている補助金という理解でいいのか。","respondent":"高橋幼保一元担当課長","answer":"全体的に今区側が子育て支援ということで、公立・私立の幼稚園・保育園に通う方々についている補助金の関係等の割合の関係ですけれども、今国のほうでも幼稚園での子育て支援、保育園での子育て支援、いろいろ言われている中では、区といたしましては。","voiceIndex":13,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう形の中で、今お話があったこれも都の補助金、１０分の１０の部分がある。ここら辺のところに、今言った区として東京都の１０分の１０の補助はわかるけれども、そうじゃなくて、全体のバランスを見ていくという話であるならば、やっぱりそこに所得制限のところに手を入れていくべきだろう、私はそういうふうに思っているわけですけれども、そこら辺の点についての考え方を教えていただきたい。","respondent":"高橋幼保一元担当課長","answer":"それぞれ区によって補助金額が違いますので、そういったことを見合いながら、今後どうするか調査をしながら考えてまいりたいと思います。","voiceIndex":15,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"よく話を聞いていただきたいんだけれども、他区のそういう状況もわかって質問しているつもりだし、先ほど言った乳幼児医療費のこともあって、それは区で独自にどうやってお金を使う部分というのは、考え方が一つあるわけですよ。","respondent":"古川児童保健事業部長","answer":"しかしながら、子育て支援全体をどうとらえていくかという中で、この保護者補助金の所得制限につきましても、そういう観点から全体としてとらえていき、大きな課題を今後どう解決していくかと、こう考えてございまして、委員のご指摘については、私ども十分承知していると。","voiceIndex":17,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはしようがないと思って見守っていこうとしているのか、あわせて前回一般質問でもちょっと出たけれども、幼保一体施設を例えば小中一貫校につけていくというようなことも考えていくと、新たなそういう部分で展開を図っていこうとされるのか、こっちは見守る、こっちは区としては行政側としてはつくっていく、そういう考えでいらっしゃるのかどうかというところだけお聞かせ願いたい。","respondent":"高橋幼保一元担当課長","answer":"今見守っていくのかどうなのかということのご質問ですけれども、私どものほうといたしましては、見守ることがいいのか、見守らないことがいいのかということになりますと、やはり、それは私立につきましては、私立運営。","voiceIndex":19,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、今も思ったんですが、幼保の動きがあるのなら私立も支援をしていくという考え、区も基本的には幼保一体施設を増やしていくということだよね。そういう考えでいいか悪いかだけ教えてください。そういう理解でいいのか。","respondent":"高橋幼保一元担当課長","answer":"それでいいのかというとあれですけれども、品川区の幼児教育は私立幼稚園に支えられて進められてきたところがあります。今回ソフト部分については、私立、公立関係なく、品川の幼児教育については考えていこうというソフト部分の姿勢はあります。","voiceIndex":21,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"地域密着型は後でやるけれども、このことについて今言ったように、東京都はなくそうとしているわけですよ、１０２条園はなくしていこうとしているわけですよ。そういう考えになるのは私は普通だと思うんだけど、そういうことをしっかり行政も踏まえて１回やっぱり言っていくべきだろうし、私はそういう理解でいいのかということを聞いているので、そこは再度そういう理解でいいのか教えていただきたい。","respondent":"古川児童保健事業部長","answer":"私どもにつきましては、２０園については品川区のこれからの子育て支援のためには幼児教育として欠かせない園ですので、それぞれ必要性の範囲の中で十分に支援をしていきたい、このように考えています。","voiceIndex":23,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"３４億円で１行というのは、ほかにもこれより額が大きくて１行しかないのもあるんですけれども、この中身につきましては、さまざまな基盤整備をされているかと思いますが、それぞれの内容、大きい内容だと思いますけれども、金額と内容、そして、この収入というのはどこから入ってきた歳入であって、この意味づけ、意義づけというものがございましたならば教えていただければと思います。","respondent":"青木都市開発課長","answer":"都市基盤整備費収入のご質問についてお答え申し上げます。３４億円強の収入の内訳、主なものですけれども、この都市基盤整備費収入と申しますのは、現在品川区が大崎駅周辺地区で進めております再開発事業に関連いたします道路や公園などの公共施設整備に対する負担金です。","voiceIndex":26,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"大崎駅周辺等の整備費ということで、公共の施設の整備費、道路・公園ですね、そういうふうに伺いまして、こちらのほうの工事をするためには、当然事業者のほうで費用が発生するわけですが、この費用というのは、たぶん業者のほうも利益を追求するような企業ですので、自分の利益から持ち出しをするのか、それとも事業者のほうにどこからか歳入というんでしょうか、お金が出ているのか。","respondent":"青木都市開発課長","answer":"このお金の考え方ですけれども、別のページでご覧いただきますところに書いてありますけれども、まず都市基盤整備に関しましては、制度要綱に基づいて国からの補助金が入ってあります。","voiceIndex":28,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"何分ちょっとここら辺の経理に関しては不慣れなもので、何度もお伺いして申しわけないんですけれども、国からの補助金とか都からの補助金ですね、また国からの負担金もあるかと思うんですけれども、それがどうしてもお金の流れということを考えてしまいますと、国からの例えばそういう補助金が区のほうに入って、そのお金でこのような公園ですとか道路の整備をするために。","respondent":"青木都市開発課長","answer":"これが国からの補助金で、これは区に収入しております。区はこれに一般財源をあわせまして、今ご説明したような公共施設整備を行いました。これは公共施設整備ですので、区の事業として行っております。","voiceIndex":30,"id":"exchange-010"},{"speaker":"浅野委員","kind":"意見","question":"そうしますと、単純に考えますと、区のほうから形として支出をしているわけですね。負担金とこちらの先ほどの説明のありました８５ページの都市再生総合整備事業費と、あと区の一般財源、これから支出をして、それが開発業者に回って、またこちらに戻ってくるという、そういうことで、ちょっとそこら辺がどうしてもすみません理解できないので、申しわけございません。","respondent":"岩田まちづくり事業部長","answer":"その場合、２分の１が区の単費になってしまいますので、先ほど課長が説明しました地元の開発者が、そのうちの２分の１を、区の持ち出し分を負担金として区に入れていただくと、こういう仕組みになってあります。","voiceIndex":32,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"次ですけれども、８５ページ、再開発事業費、先ほどの都市再生総合整備事業費の上になるわけですけれども、こちらのほうの補助金ということで、土木費の補助が出ているんですが、これは大崎周辺と東五反田の事業というふうに聞いておりますけれども、この補助金のベースになる金額ですね、例えば大崎駅東口第３地区であれば、２０億円ぐらいのお金が出ているわけですけれども。","respondent":"青木都市開発課長","answer":"区に納められたこの補助金に、簡単に言うと倍額にして組合に支出する、区から支出するというもので、これはまた日を改めて歳出のときにご説明申し上げたいと思います。","voiceIndex":34,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"最近発表された地域の危険度が高いエリアということで、品川区がベスト１０のうちに四つ入っておりまして、それが旗の台駅から西大井駅にかけての立会道路沿いの地域なんですけれども、このような密集した地域を何とかしていこうというのは、地権者また住民の感情もあって難しいとは思うんですけれども、このような地域を例えばいろいろな計画を立てたりして整備するに当たり、国庫また都の負担。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"６９ページの特別区民税についてお伺いいたします。特に今年６月に届いた住民税の増税の通知が、開けるとともに年金が減ったのに、なぜ税金ばかりが増えるのか、二、三倍にはね上がって、間違いではないか、こういった問い合わせや、また苦情が殺到したのも記憶に新しいところです。平成１８年度は種々の税制改定がありました。影響額と対象人数を教えてください。１番目が定率減税２分の１の縮小の影響です。","respondent":"武内税務課長","answer":"３,０００人増えるということは、その中でも生産年齢といいますか、税を払っていただく方が６割ぐらいいるのかなというような状況の中でも税が増えているのかなというふうに考えますと、一般的な部分では、そういう納税義務者。","voiceIndex":42,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"トータルの金額と人数的にはマックスで何人になるんでしょうか。ちょっと教えてください。","respondent":"武内税務課長","answer":"それと、人口増ということで、先ほどお話ししたとおり、３,０００人ぐらいの人口が増えておりますので、それで３億円ぐらいの収入があるのかなというふうに見ております。","voiceIndex":44,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その中で増税、私はまちの中から悲鳴が聞こえてくるのは当然であると思っています。税に連動する影響も出ていますけれども、非課税によるサービスなども課税になって受けられなくなったり、また、保険料などが上がる、生活を圧迫するところが多いと思うんですが、非課税から課税になった人が何人か教えていただきたいのと、その影響についてどう受けとめていらっしゃるのかお聞かせください。","respondent":"武内税務課長","answer":"老年者控除の廃止に伴いまして、その方たちは条例に定める一定金額以下の非課税という、そういう措置もありますので、そちらのほうでかなり吸い上げられているのかなというふうに考えております。","voiceIndex":46,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと今人数を書き漏らしてしまったので、あとでちょっと非課税から課税になった人数を、改めて、人数で、もう一回きちんと教えてください。次でいいです。影響のところが答弁なかったですね。影響をどう受けとめているかのところも。","respondent":"武内税務課長","answer":"これをどのように受けとめているかということですけれども、やはり、社会情勢が少子高齢化ということで、また社会保障制度の充実ということで今後、税の負担する層が生産人口というのが減ってくるという中で、ある一定の高齢者の方にも負担をいただくという。","voiceIndex":48,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"非課税から課税になってどう変わるのか。この方が平成１８年度住民税１万２,０００円です。そして、国民健康保険料６万４,２００円が９万円になりました。私はこういった不公平税制を正していくのが筋と考えていますが、この辺にメスが入らない部分で、国から言われているままに、こうやって高齢者のところに押しつけていくものはいかがなものかと思いますが、いかがでしょうか。","respondent":"田中区民生活事業部長","answer":"税制改正の影響でご質問がありました。考え方として、当然医療費ですとか年金ですとか社会保障を含めまして、社会のあり方の問題にかかわる話だと思います。制度の持続性を考えた場合に、医療費にしろ、年金にしろ、だれかが負担しなければいけないわけです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"利益が２倍なのに税金は同じである。一つには、節税の活用、各種控除がいろいろありますが、その辺の内容的に負担軽減のために役立つ控除の広報をどうしていらっしゃるのかを、強化をぜひしていただきたいという立場でお伺いしたいと思います。そして二つ目は、本来非課税である所得の低い方々に減免制度がある、この道を開くべきであると思いますが、いかがでしょうか。","respondent":"武内税務課長","answer":"委員言われるとおり、この間指摘のあります障害者控除の件、あるいは医療費控除、さまざまな控除のＰＲというのが本当に大切だということは重々私ども認識しておりまして、これにつきましては、一番大きいところでは、３月１５日の確定申告という中で。","voiceIndex":52,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"減免制度というのは、地方税法第３２３条、そして品川区の特別区条例においても減免制度がしっかりと書かれています。でも、これが今生活困窮者とありましたけれども、ここに使われていないんですね。私は飾りになっているんではないかなと思います。ぜひ、特別区税増収分をぜひこういった方たちに使っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-020"},{"speaker":"阿部委員","kind":"質問","question":"私は７４ページ、保養所使用料、そして７６ページ、道路占用料、そして７９ページの戸籍証明手数料についてお伺いいたします。その中で、行政が保養所を運営することの意義というのをまずどのようにとらえられているのかということをお伺いしたいと思います。その中で、行政が保養所をなぜ持ち続けるのか、その基本的なお考えについてお伺いしたいと思います。","respondent":"鷹倉区民課長","answer":"やはり多様なニーズにこたえられるような形で行政がどういう形でかかわっていけるか、ここのところ。かかわり方は当然区が保養所行政をしていく以上は一定あるわけですけれども、昭和４０年代とは随分変わってきていると、このように認識しています。","voiceIndex":56,"id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"借り上げの方向にも来ているということなんですが、それも含めて、例えば借り上げをしてまで保養所を提供する意義があるかどうかということも含めてお伺いをしたかったので、この点についてもご答弁をお願いします。例えば、渋谷区でしたら、生活保護世帯に割引があるほか、交通費の助成がある、あるいはひとり親家庭に対する援助などもあると。その辺について再度ご答弁をお願いします。","respondent":"鷹倉区民課長","answer":"その中でも、やっぱり中小企業、今お話のようにアッパークラスではなく、所得が若干低目の方々、中小企業の従業者の方々、それから高齢者、ますます増えてくるわけですけれども、そのような方々の福利厚生あるいはレジャーという意味で、そういう形を進めていく必要があると。","voiceIndex":58,"id":"exchange-022"},{"speaker":"阿部委員","kind":"質問・要望","question":"もし不正確であれば、ご指摘いただきたいんですけれども、こうしたある程度の使用料を見込まれながら運営する施設の中で、ただこの部屋を１年間回していったら幾らというので安いところを選ぶだけではなくて、やはり利用者をより獲得できるような営業能力をきちんとしてくれるといった視点もぜひ入れて業者を選ぶ、あるいは委託内容を決めていく必要があるかと思うんですけれども、その点はいかがでしょうか。","respondent":"鷹倉区民課長","answer":"その中からお客をさらに増やしていくことによって、一定の収入が安定的にといいますか、その間確保できるという、この間従業員の働く場所が確保できるというインセンティブが働くのではないかと思います。","voiceIndex":60,"id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"その辺のことはさらにきちんと経営努力をするような契約方法というのをきちんとさらに詰めていってほしいなと思います。７６ページの道路占用料なんですけれども、１０月１日から郵政公社が民営化されまして、ポストの道路占用料を徴収する自治体がそこそこ出てきているということです。品川区の場合は、この問題についてどのようにお考えなのか、方向が決まっていれば教えてください。","respondent":"松代管理工事課長","answer":"ただいま質問がありました民営化に当たりましてのポスト、それも占用物権として占用料を徴収していきたいと考えているものです。","voiceIndex":62,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"その場合、いつから占用料を徴収の対象にするのか、その時期と対象の数、そして幾らぐらいの収入が見込まれるのかということを教えてください。","respondent":"松代管理工事課長","answer":"つい最近通知が来まして、今詳細にわたって検討しております。早急に料金等を定めまして、徴収をして収入にしていきたいというふうに考えているところです。おおむね１基当たり８,９００円の単価で占用料を徴収したいと、このように考えているところです。","voiceIndex":64,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"基本的には民間会社の占用ですので、当然徴収して区の収入にすべきだと考えています。１点だけ心配なのは、ポストの数がこれで減ってしまうのではないかと、お金を取られると。そのことが結局住民の利便性を低下させるんではないかという意見をちょっと聞いたことがありますが、そういった心配は特にございませんでしょうか。","respondent":"松代管理工事課長","answer":"今実際の実数、占用料を賦課する個数、そういったものも先方と話をしながら調整をしています。それが将来的に減ずるかどうかというのは、正直言いまして、私のほうでは何とも今のところ答えようがございません。","voiceIndex":66,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"最後の質問にいきます。７９ページの戸籍証明手数料なんですけれども、この戸籍の証明書というのは、本人、家族以外でも一定の要件があれば発行できると。そういった少なくとも自分と家族以外の者がとったこういった証明書、個人にかかわる証明書は、請求があったことだけでも知らせるようなサービスなどを考えることはできないか、お考えを伺いたいと思います。","respondent":"上川内戸籍住民課長","answer":"本人が知らない間にだれかから請求があったということを本人が知る方法ですが、情報公開開示請求があります。その中で、自分の戸籍の戸籍証明がとられたという申請者に個人情報の部分を秘して開示しております。そういう制度をご利用いただいているところです。","voiceIndex":68,"id":"exchange-027"},{"speaker":"阿部委員","kind":"確認","question":"個人情報の開示請求ということでとれるようになったというのは、それはそれで一歩だと思うんですけれども、そういうことが気になる方は、例えば定期的に半年に１回とか１年に１回とか、常に自分から請求をしないと過去に自分の個人情報がだれかによってとられたかどうかが確認しようがないというのは、これはやはりちょっと不合理感が強いと思うんですよね。","respondent":"上川内戸籍住民課長","answer":"その件は、戸籍法の今法改正が国会を通りまして、今後実施されることになっておりますが、審議の中でも入っておりました。ただし、現実の中では、戸籍の証明の部分というのは、かなりの件数がございまして、実務的に無理だろうということに審議の中では話されたと伺っております。","voiceIndex":70,"id":"exchange-028"},{"speaker":"渡辺委員","kind":"質問","question":"私は成果報告書の７４ページからの各項目の最後にあります土地建物使用料、それと８０ページにあります車体利用広告についてお伺いしたいと思います。多岐にわたる場合は、主な用途、数点で構いませんのでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-029"},{"speaker":"渡辺委員","kind":"質問","question":"今主なものの中で、原っぱ公園のことがありました。こういった賃借関係で、今後もそちらの貴重な区有地といいますか、区有財産を今後も継続していくのか、見通しを教えてください。","respondent":"日下部企画財政課長","answer":"そういった意味では、区の財政面でも非常に貴重な収入でありますので、私どもとしましては、今後ともその辺、増収がどれだけ図れるか、なかなか難しい面はありますけれども、最大限継続をして活用してまいりたいと、このように考えております。","voiceIndex":79,"id":"exchange-030"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今項目が多岐にわたって、聞き方も申しわけなかったんですが、特に土木費のところで金額が大きかったものですから、今の原っぱ公園のような形で、特に住宅密集地の中でなかなか転用が難しいけれども、今後考えた場合に、防災利用へ転用できるような、割と狭小な、小さな土地等で応用がきくようなことが可能性としてあるのか、特に土木のところでそのような、今現在区有地というよりは。","respondent":"伊勢住環境整備担当課長","answer":"土木使用料の中で、密集事業をやっておりました戸越一・二丁目地区ですけれども、戸越二丁目のまちづくり用地、これは広場になっていない形なんですけれども、こういうところの使用料を取っております。これが将来的には防災に役立つ広場に変わるということもあります。","voiceIndex":81,"id":"exchange-031"},{"speaker":"渡辺委員","kind":"質問","question":"では次に、８０ページの車体利用広告について伺いたいと思います。車体利用広告といいますと、私ども感覚的には東京都が行っているバスのラッピングなどがまず浮かんだりします。この点で、品川区におけるこの車体利用広告、具体的にはどのようなものなのか、お教えいただければと思います。","respondent":"松代管理工事課長","answer":"それ以外で言いますと、タクシーの横のドアとか、そういったところにラッピング等で広告等をされているというもので占用料等を取っているものです。加えて、先ほど言いましたバスの枠の部分以外にも若干ラッピングを行っているものがあります。","voiceIndex":83,"id":"exchange-032"},{"speaker":"渡辺委員","kind":"質問","question":"今のバスというのは、どのようなバス、どこの所有のバスか伺えればと思いますので、よろしくお願いします。","respondent":"松代管理工事課長","answer":"バスといいますと、都バス、それと京急、そういったバスのところで広告、ラッピング等をやっております。","voiceIndex":85,"id":"exchange-033"},{"speaker":"渡辺委員","kind":"確認","question":"もう一度確認をします。品川区に収入が入るということかと思われますので、品川区の所有のものかなと私想像しておったんですが、どのような仕組みで品川区に広告収入が入るのかをお教えいただければと思います。その対象は、今タクシーというお話がありましたが、どのような車体なのか、もう一度お願いします。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"失礼しました。一応バスのほうがそういったものの広告料として１台当たり６１０円もらっていまして、数量としましては７９件あります。それの前年度、平成１８年度で言いますと、４万８,１９０円の収入です。バスやタクシーのいわゆるラッピングに限定して言えば、ここに計上させていただいていますのは、屋外広告物条例という条例がありまして、一般の宣伝、看板等を設置する場合に。","voiceIndex":87,"id":"exchange-034"},{"speaker":"渡辺委員","kind":"確認","question":"今のご説明でもう一点だけ確認なんですが、品川区にそのような形、収入で入るという仕組みの中で、まず今都バス等でラッピングという点で考えれば、収入が入る。そのうちの品川区の認めた分に、品川区を通行することで収入が得られるのか、ちょっとその辺、もう一度お願いします。","respondent":"岩田まちづくり事業部長","answer":"先ほどちょっと申しましたけども、屋外広告物条例の中で、ラッピングバスについては、全体の面積の何分の１以下でなければいけないとか、色彩等についても一定の基準があるんですね。その基準に適合しているかどうかの審査を書類上うちの区の職員が行います。","voiceIndex":90,"id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"都バスというもので、今限定されているかと思うんですが、まず、こちらの現状の車体広告は、都バスですとかが主な収入なのかどうかと、もう一点伺いたいのが、品川区で所有するそういった車体利用が現在あると思いますが、そこでの今後広告利用等が展開として考えられるのか、そういった増収の可能性を探っていけるのかお教え願えればと思います。","respondent":"松代管理工事課長","answer":"そういったものを今後例えば広げていくということであれば、東京都の知事の許可ということで、東京都広告物審議会というものでそういったものを諮りまして、そこの中で審議されます。そういったものの規制が少しずつ緩和されれば、これが広がっていくものと考えているところです。","voiceIndex":92,"id":"exchange-036"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは、成果報告書９１ページの認証保育所運営費助成費についてと、７７ページの教育使用料についてお伺いします。それと、平成１６年度、平成１７年度それぞれこの補助金を見させていただいたところ、前年に比べて、１.１％ないし１.２％増になっておりました。この現状から見る認証保育所の運営状況というのでしょうか、その辺をお伺いいたします。","respondent":"小林保育課長","answer":"それで、こちらの助成額が基本的に若干増えているという部分は、一つは運営費総体から申しますと、各年度この間新規開設がございました。その分の実績の増、ないしは各保育園で若干年によって実績が異なりますので、それを積み上げた結果が実績の増に結びついているところです。","voiceIndex":96,"id":"exchange-037"},{"speaker":"金野委員","kind":"質問・要望","question":"その状況を見させていただいて、先の第３回の定例会でも公明党より同僚議員から質問をこの件に関してはさせていただきましたが、やむを得ずここにまたあえて認証保育所に通園をされているこのご家庭の経済的負担というんでしょか、その点を見ますと、この保育料の助成制度というのを確立していただきたい、そのように重ねて要望させていただいたところでありまして、そのときに、理事者の方からは。","respondent":"小林保育課長","answer":"今後そういった区の状況も参考にしながら、品川区で認証保育所を利用している実態がどうなのか、また、そうした場合にどういった負担がかかっているのか等を確認した上で助成の進め方等も含めた検討を行ってまいりたいと考えております。","voiceIndex":98,"id":"exchange-038"},{"speaker":"金野委員","kind":"質問・要望","question":"そういうのも考えたときに、今後品川区としてのまちづくりを考えたときに、この若年層のファミリーが越してくる、転入してくる可能性もあるわけですので、ぜひそこも踏まえていただきながら、１日も早い創設を強く要望したいと思います。この件に関しては終わります。それぞれ記載方法が違うのはなぜでしょうか。その点、お伺いしたいと思います。","respondent":"富田生涯学習課長","answer":"これに対比するものといたしまして、荏原文化センターの件数ですが、荏原文化センターにつきましては、平成１８年度は７万８,４１６件となっております。続きまして、品川区民公園のプールですが、こちらは有料で入りました利用人数です。","voiceIndex":100,"id":"exchange-039"},{"speaker":"金野委員","kind":"質問","question":"今の数はわかったんですが、なぜ記載方法が違ったのかという点をいま一度教えてください。","respondent":"富田生涯学習課長","answer":"この点につきましては、深い事情というものはございませんので、今後できる限り整理するように修正してまいりたいと思います。","voiceIndex":102,"id":"exchange-040"},{"speaker":"金野委員","kind":"質問","question":"何が暑かったかというと、外にいるのと同じ状態で、頭から照らされ、そして温水プールの中でやっていたということで暑かったということと同時に、プールサイドに上がったときに日影がなかったということで非常に大変だったというお声を伺いました。ということは、高齢者の方は昼間利用することが多いというお声もありましたので、ぜひその点の工夫をお願いしたいと思いますが、いかがでしょうか。","respondent":"富田生涯学習課長","answer":"屋外でも大変今年の夏は暑かったわけですが、屋内プールであり、ドームをあけている状態の伊藤学園につきまして、安全上の問題もありますが、例えば傘等を設けることができないか検討してまいりたいと考えています。","voiceIndex":104,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"私は成果報告書の９７ページから１００ページ、諸収入、そして、７５ページの使用料で賃貸工場アパートについてお聞きしたいと思います。歳入のほうで一般会計の月別資金のほうをちょっとお聞きしたいと思います。","respondent":"鷹倉区民課長、志村生活福祉課長、金子産業振興課長","answer":"これは前年と比較という意味でちょっと説明しますけれども、前年が６,４６６万１,８００円です。前年よりも伸びているという状況です。私からは生活保護費弁償金についてお答えを申し上げます。生活保護費、皆様方に毎月銀行振込を基本に保護費の支給をしています。それからもう一点の、７５ページの賃貸工場アパート使用料ですけれども、これもご案内のとおり広町にあります従前。","voiceIndex":108,"id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"これはもう返せない、返さなくていいんだ。決算書から除去するというような額なんでしょうか。それとも、このまま不納欠損としてずっと決算書の事項のほうには残っていくものでしょうか、その辺、お聞かせください。","respondent":"鷹倉区民課長、金子産業振興課長、志村生活福祉課長、諸岡児童課長","answer":"奨学金のほうは不納欠損はございませんが、収納率も確かに収入未済はありますが、前年の収入率が６７.６％というところを。私どもは賃貸工場アパートのほうの不納欠損ですけれども、これにつきましては、個別の事情を明らかにするのはちょっとできませんけれども。そのときには、ほとんどの方にノーと言われてありますので、なおかつまたこの債権の回収というのは大変なそういう意味では理解が必要だということで。","voiceIndex":112,"id":"exchange-043"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区は本当に低所得者に今後もできるだけ配慮して、おもいやりのある品川区政を続けていただきたいと思います。ただ、毎月の収入額を月数ごとに見ますと、平成１８年４月は収入の欄で４９億円、約５０億円ですね。これはここだけちょっと突出しているんですが、我々民間企業でも決算月になって急激に金額が増えることがあるんですが、何か理由があるんでしょうか、お聞かせください。","respondent":"日下部企画財政課長","answer":"例えば国庫でありますとか東京都の財源につきましては、年度末に区のほうに収入をされるということがかなり多いということもありますので、その分増えているというものです。","voiceIndex":117,"id":"exchange-044"},{"speaker":"須貝委員","kind":"質問・要望","question":"もちろん向こうから来る額ですから、調整はできないと思いますが、ちょっと不思議だなという感はありますので、その辺、事情等はあると思いますが、いろいろご検討されてはと思います。その月に特段のやはり大きな変動があるというのは、やはり何か一般の人にとったら不思議な気がしますので、その辺、今後もいろいろお考えになって、事業も進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"私からは、先ほど浅野委員から質問ありましたけども、８５ページの国庫支出金、国庫補助金の土木費補助金の中の再開発事業費、都市再生総合整備事業費についてお伺いしたいと思います。改めて整理をする意味で、先ほどの再開発事業費と都市再生総合整備事業費それぞれのお金が、どこからどのような名目で出て、それが開発事業のどこに使われるのか教えてください。","respondent":"青木都市開発課長","answer":"委員ご指摘の８５ページの土木費補助金の中から再開発事業費約３５億円、都市再生総合整備事業費、先ほど午前中ちょっと間違いましたが、７億８,０００万何がし、これは国庫補助金ということで、国から区に収入したものです。","voiceIndex":121,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"国庫補助金ということで、半分が区の施工事業、道路や公園に出ているということなんですが、品川区の一般会計から入ろうが、都に一たん入って投入されるものでありますが、どちらにしても税金であるということには変わりがないということなんですけども、そこでちょっと具体的にお伺いしたいんですが、どれぐらい私たちの税金が投入されているのかということで、北品川五丁目第１地区。","respondent":"青木都市開発課長","answer":"今委員のご指摘で２０年ぐらい前のものも含まれておりますので、すべての細かい数字までは申し上げられませんけれども、大崎駅周辺で現在のところ、大崎駅東口第１地区から第３地区までと、あと東五反田一丁目第１地区という４地区を完了しております。","voiceIndex":123,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"大崎駅地区のほうはわかったんですけども、東五反田のほうと、あと北品川五丁目第１地区、これから見込みで構わないんですが、そちらのほうはどうでしょうか。","respondent":"青木都市開発課長","answer":"ご指摘で、これからのものですので確定ではございませんけれども、東五反田二丁目第２地区、現在施工中のもの、こちらに補助金が約６９億円から７０億円ぐらいを予定しています。総事業費４２０億円ほどを予定している中で補助金が７０億円弱という予定。","voiceIndex":125,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"東五反田二丁目第２地区だけで申しますと、４２０億円の中に６９億円ということで、６分の１ぐらい税金が入っているということなので、やっぱり冒頭に申し上げましたように、改めてまちがきれいになるのはいいことじゃないかと一般的に思っている方々も、これだけの税金が投入されているということは改めてやっぱり驚くと思うんですけれども、そこで改めて。","respondent":"青木都市開発課長","answer":"つまり、民間の事業者みずからが資金を負担して開発を行っているというものですから、そういった民間の開発努力に対して、まちの全体のクオリティーをアップするという意味において補助金を導入することは必要なことであると考えております。","voiceIndex":127,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"もう一つ、こうした先ほど事業費とか補助金の額を聞いた地域の多くが大崎駅周辺の６０ヘクタールの都市再生緊急整備地域に指定されておりますけども、その地域の中における開発というのは、他地域の開発とはまた違った条件的な緩和措置ですとか、あるいはそういった規制を一定緩くするというか、そういう開発をする側にとっては非常にやりやすいというか、そういう措置がなされていると思うんですが。","respondent":"青木都市開発課長","answer":"区といたしましては、市街地整備基本方針に基づきまして、大崎や大井町の都市活性化拠点のほかに、武蔵小山など、地域生活拠点というものもまちづくりの中で位置づけておりまして、そういった拠点での開発については。","voiceIndex":129,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"地域環境の変化という点では、目黒川に大崎第３地区の建物が３棟建ちましたけど、それが壁のようになっておりまして、それが現在の大崎の都営住宅にお住まいの方の上の階の方から、電車の騒音が壁のようなビルにはね返って今までにない騒音が聞こえているという声も伺っております。そのような声をどのように受けとめておりますでしょうか。","respondent":"青木都市開発課長","answer":"風の問題など、かなり難しい問題ではあるんですけれども、事前に予測したものと結果が違うような事態になれば、それはその中での新たな事業者側での対策も要請しているところでございまして、繰り返しになりますけども、おおむね委員からのご指摘の情報は。","voiceIndex":131,"id":"exchange-051"},{"speaker":"大沢委員","kind":"質問","question":"１００ページのリサイクル資源売払収入を質問します。リサイクル資源売払収入ということで１億円入っていますが、この１億円を入れるためにいろいろ経費があると思います。資源にしたり、回収をし、またそれを資源にするというもろもろの１億円を入れるためにどれぐらいの経費がかかっているのか、またごみに直した場合、キログラム当たりどれぐらいの単価がかかっているのか教えてください。","respondent":"秋山資源循環推進課長","answer":"こちらの費用ですけれども、衛生費のほうで、環境費のリサイクル推進費がありますけれども、１億４,６００万円余りというのが資源化センターの管理運営費となっています。","voiceIndex":134,"id":"exchange-052"},{"speaker":"大沢委員","kind":"質問","question":"１億円というのは、先ほど私ども歳出のほうで見させていただきましたので、それはわかっています。これに対して経費が約１億円かかるということですけれども、これに対して資源回収、集団回収のほうの経費はどれぐらいかかっているのかも、歳出のほうには書いてありますが、収入に比べるものなので、集団回収をするに当たってどれぐらいの経費がかかっているのか教えてください。","respondent":"島袋品川区清掃事務所長","answer":"集団回収の費用ですけれども、８,４００万円です。","voiceIndex":136,"id":"exchange-053"},{"speaker":"大沢委員","kind":"質問","question":"これで、東京ルールＩというやつでしょうか、それで、３日のうち１回が資源回収になったということで、資源回収という啓発をする上で非常に区民のごみに対する意識をこれで啓発した結果に集団回収のほう、これがだんだん回収事業によって利益といいますか、ここで言えば報奨金が与えられ、ある程度の区民に還元されるような形になってきたわけですけれども、１億円というリサイクル売払収入。","respondent":"島袋品川区清掃事務所長","answer":"集団回収と週１回やっています東京ルールＩの回収とは別のものでございまして、いわゆるある地区では集団回収で区の資源回収をやらないところがあるんですけど、規模が全然違いますので、うちの区としてはあくまでも集団回収は集団回収。","voiceIndex":138,"id":"exchange-054"},{"speaker":"大沢委員","kind":"質問","question":"集団回収、いわゆる行政回収という部分で、先ほどの１億円、リサイクル売払収入、行政回収ですけれども、行政回収の効率というのはどういうふうに考え、経費、費用対効果といいますか、片や集団回収のほうで地域住民がみずから行って、それに対して報奨金ということで、お金の回り、非常に集団回収のほうは有効に感じ、また行政回収のほうにとっては。","respondent":"島袋品川区清掃事務所長","answer":"ちょっと我々区のほうの資源回収のほうですけれど、その総回収量は１万５,２６３ｔあります。集団回収のほうは、９,７５７ｔということで、ちょっと規模的に半分以下ということなので、ちょっと比較にはならないんじゃないかと考えているところです。","voiceIndex":140,"id":"exchange-055"},{"speaker":"大沢委員","kind":"質問","question":"経費のことで、これは今日決算ということで、経費のことなんですが、私単純に１億円かけて、１億円の収入を得るよりも、区民の方がやっていただいて、８,０００万円ぐらいでしょうか、経費がかかるということですが、それに対して、区民にそれを還元するという、それをより多くするとしたほうがいいと思うんですけども、またさっきと同じような質問になりますが。","respondent":"島袋品川区清掃事務所長","answer":"集団回収が広まるのは当然いいことだと思うんですけど、これはすべての地区でやっているわけじゃなくて、例えば町会で比較しますと、大体半分ぐらいの町会がやっているということなので、すべてがすべて。","voiceIndex":144,"id":"exchange-056"},{"speaker":"大沢委員","kind":"意見","question":"ある程度理解をしなければいけないなと思いますけれども、けれどもということで、集団回収のほう、報奨金がありますね、これも年々増えてきています。今行政回収のほうから、集団回収のほうに話を移しますけれども、古紙の需要と供給のバランス、そういうものを考えながら報奨金について議論する場合、そういうものを考えながら議論されていますか。","respondent":"島袋品川区清掃事務所長","answer":"現在、廃棄物減量等推進審議会というのがございまして、そちらの委員の方にそういう各区の状況とか、市場ルールに合う方法とか、そういうことを検討いただいているところです。","voiceIndex":146,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"国庫支出金、都支出金、それから財調も含めてですが、特定財源のところから、三位一体の関係が始まって、地方分権というのがますますこれから広がっていくだろうという動向の中で、国とか都からの支出金の動向がどういうふうになっているのか、特に気になるのは、特定財源で来ていたものが、一般財源化という形で来て。","respondent":"日下部企画財政課長","answer":"じゃあ一方で、一般財源のほうで、その分が三位一体の趣旨である一般財源のほうにうまく切りかわっていくかというと、実は品川区も含めまして、一部の自治体におきましては、なかなかうまくスムーズに特定財源から一般財源へという形の移行がうまくいっていないと。","voiceIndex":149,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"それを今後品川区としてはどういうふうにとらえていくのか、全く、おそらくは全く違うところにそのお金を使うというわけではないとは思いますが、今までのやっている国とか都とかの財源、ソフト的なところも含めて今後品川区としてはそれも継続という意味で考えていくのか、今後どういうふうな考え方で財源を確保し、やっていくのかなというところではいかがでしょうか。","respondent":"日下部企画財政課長","answer":"例えば、公立保育園につきましても、一番影響が大きくて、年間１０億円ぐらいの国庫のほうがマイナスになるということでありますけれども、これはこの間の平成１８年度の実績を見ていただきましても、基本的には保育の内容そのものにつきましては。","voiceIndex":151,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"今まで品川区においては、さまざまな施策をしているという中では、やはりかなり国であるとか都の補助金、助成金、いろいろなところによって運営しているという部分もありますので、今後かなり削減されてしまうという部分もありながら、なるべく影響がないように進めていただきたいということで要望させていただきたいと思います。","respondent":"小林保育課長","answer":"これは主に制度的な変化というよりは、待機児等にも対応する目的で施設を拡張し、定数を拡大し、また、平成１８年６月には幼保一体施設台場の開設、こういったところで、定員を合わせて１３４名、年間の人月で申しますと、１,４０８人月ほどの収容実績増となっております。","voiceIndex":153,"id":"exchange-060"},{"speaker":"西本委員","kind":"意見","question":"確かに、定員増というところで増えてきているというのはわかりますが、今年にかかってしまうことかもしれませんが、税制度が変わることによって、今後どういうふうな動きを見通しているのかを、ちょっとお聞かせください。","respondent":"小林保育課長","answer":"保育料へ及ぼす影響いたしましては、一つは、平成１１年度分の所得税制の改正の定率減税が、２分の１に縮減されて、平成１９年度の保育料に影響してくるものと考えております。今後は、税源移譲等による影響等も、来年度以降、保育料に影響していくものと予想しております。","voiceIndex":155,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"来年度は大きく変わるわけですね。その中で、定率減税が始まっていくと、所得税で保育料というのは加算してきますので、当然ながら、保育料は高くなってくるわけですよね。しかしながら、来年度になると、今度は下がるわけですね。そういう状況の中で、これは今の時期はまだ早すぎるかもしれませんけれども、どういう方向で考えていくのかというところは、いかがでしょうか。","respondent":"小林保育課長","answer":"そうした状況を注視しながら、保育料の負担のあり方、また運営費総体に対する割合や、各世代の負担等を加味して、求めるべき適正な保育料水準を検討してまいりたいと考えております。","voiceIndex":157,"id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"来年度、大きく変わると思うんです。ですから、もし来年にかけていろいろなことが起きるんであれば、機会を見て、今、保育料というのはどういう流れになっているのか、どういう階層になっているのか、今、国ではこういうことが流れているとかということは、ある一定の利用者には知っていただく機会を設ける必要があるのではないかと考えています。","respondent":"小林保育課長","answer":"求めるべき適正な保育料の水準ということにつきましては、現在、検討しているところであり、各区の状況も加味した上で、品川区の子育て中の世代への負担がどうなのかということを中心に、負担していただく基本原則につきましては、応能負担の原則に立って、その負担階層の設定等。","voiceIndex":159,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、もう少し広い意味で、どういうところにどのぐらいのお金をかけたらいいのか、補助、助成金等々の考え方も含めて、広く考えていただきたいと要望したいと思います。次に健康センターですが、特に品川健康センターの利用料について質問します。数年前に、今のコナミのほうにしていただいて、コース型、フリー利用という枠の変動はどうなっているんでしょうか。動向がわかれば、お願いします。","respondent":"太田健康課長","answer":"平成１３年８月の時点です。１週間のコマ数ですけれども、大体１２３本、１単位１時間、あるいは一部１時間半ですけれども、プログラム実施可能数としては、１２３本が可能となっております。","voiceIndex":161,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"コース型が増えているというところでありますが、なかなか中身まで分析等々は難しいかとは思いますが、利用者から、こちらのほうにいろいろご意見をいただくんです。以前お聞きしたときに、子ども対象のコースというのは非常に利用率が高くて、要望が多いんだ、ですから増やしていくという状況もあるということでしたが、その中で、じゃあ健康センターの事業というのは、どういう考え方でやっていくのか。","respondent":"太田健康課長","answer":"健康センターの考え方ですけれども、品川区民健康づくり品川プランという総合計画の中で、区民一人ひとりがさまざまな場で健康づくりを目指した活動ができるよう支援をする、そのための拠点として、そういう趣旨で設置しています。","voiceIndex":163,"id":"exchange-065"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり区民の人たちが、どうしても子ども向けが多くなってきていると、多くなっているのであれば、それは別に民間を利用してもらえばいいんじゃないか、品川区は、どういう考えで健康センターをやっていくのかと、むしろ、なかなかそういう場がない人たちを対象にしてやるべきではないかという意見もありますので、健康センターの使い方、考え方というものを、今度の第四次長期基本計画もありますので。","respondent":"太田健康課長","answer":"正直、空きが３２本あったのが、現行の事業者のもとで９本、２３コマ増えてきた。そういうことで営業努力の部分もあろうかと思いますが、いずれにしても、全世代が利用できるような健康づくりの場として考えていきたいと考えています。","voiceIndex":165,"id":"exchange-066"},{"speaker":"稲川委員","kind":"質問","question":"私のほうからは、成果報告書の６９ページにあります軽自動車税、そして、特別区たばこ税についてお伺いをいたします。軽自動車税なんですが、現年課税分、そして滞納繰越分、それぞれ決算調定額と決算額があります。そして、何となくはわかっておるんですが、還付未済金の意味と、なぜこれが発生したかをお答えいただければと思います。よろしくお願いします。","respondent":"武内税務課長","answer":"ところが、還付するに当たりまして、連絡しても区外に転出しているとか、今、日本にいないとか、あるいは、ちょっとなかなか連絡がとれないとかいうことで、本来返さなければいけない金額が残ってしまっているのが、平成１８年度で１９万８,５００円の還付未済となります。","voiceIndex":168,"id":"exchange-067"},{"speaker":"稲川委員","kind":"質問","question":"先ほど、６月１日ごろから督促状を出すという話なんですが、さっき、ご説明をいただきまして、納税する側がダブって払ってしまうということがございましたけれども、これは役所の事務的なミスというのは一切ないのですか。お答えください。","respondent":"武内税務課長","answer":"特に区役所のほうで、払っているにもかかわらず、その辺のミスで納付書を送っているということはありません。","voiceIndex":170,"id":"exchange-068"},{"speaker":"稲川委員","kind":"意見","question":"滞納繰越分が減額されているんですが、これは、先ほど言った廃車になったり、そういう部分なのか。それとも、行政側の熱意による督促によって徴収してこの額になったのか、その辺をお答えください。","respondent":"武内税務課長","answer":"あるいは、ご本人がどうしても、金額は少なくても払わない方がいらっしゃいますので、それが何年がしますと、不納欠損というような形になりますので、そういう状況で滞納繰越金額が減っていくという状況です。","voiceIndex":172,"id":"exchange-069"},{"speaker":"稲川委員","kind":"質問","question":"ほんとうに税金というのは払わなければいけないものなので、ぜひ、しっかりミスのないように徴収ができる体制をつくっていただければと思います。次に、特別区たばこ税なんですが、先ほどと同様、現年課税分と、決算調定額と、決算額、ほんとうに数百円なんですか、この差が出ている理由をお聞かせください。","respondent":"武内税務課長","answer":"ただ、その２社だけではなくて、卸売業者というのは、いわゆる登録すればできないことはないんです。","voiceIndex":174,"id":"exchange-070"},{"speaker":"稲川委員","kind":"意見","question":"６９ページの一番下に、前年度との比較があります。平成１７年度に比べて、平成１８年度が増額をしているんですが、さまざまな増税とか、たばこ税の値上がりとかがあった関係で増えているのかもしれないんですが、その辺は、どういう分析をしているのか、お答えください。","respondent":"武内税務課長","answer":"実際、この間、たばこを吸わなくなる方も非常に多くなっている中で、この税額の変更により、かろうじて前年の決算額と同等の金額が入ったということです。たばこの本数でいきますと、１０億６,３００本が、平成１７年度から平成１８年度は、２００万本ほど減になっております。","voiceIndex":176,"id":"exchange-071"},{"speaker":"稲川委員","kind":"質問","question":"この額を見ても、品川区に３１億円という税収というのはすごく大きなものだと思います。ちょっとこの案件からそれてしまうかもしれないんですが、健康増進法が施行されてから、吸わない方の環境というのが非常に守られているんですが、吸う側の環境というのは、どうお考えですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-072"},{"speaker":"武内委員","kind":"質問・要望","question":"一つは、平成１８年度の予算書では、東京都のほうの補助金では、当初、７４９万１,０００円×４０分の５.５、１０３万円という補助金だったんですが、決算書のほうでは、５.５という補助率プラス４分の１というのが２段階で出ているんですけれども、この辺の経緯というか、なぜこうなったのかというのを教えていただきたいと思います。","respondent":"片田建築課長","answer":"私のほうからは、木造耐震関係に係わる補助金についてのご質問にお答えしたいと思います。当初の平成１８年度予算の中では、特に国と都の補助金ということで、国については、耐震診断および耐震改修、都の件については、耐震改修の補助金を指定してきた経過があります。","voiceIndex":180,"id":"exchange-073"},{"speaker":"武内委員","kind":"質問","question":"そうすると、さっき、私がページを示した以外のところで、地域住宅交付金という中でも補助があるということでよろしいんでしょうか。それから、東京都のほうの補助金の４分の１というのと、４０分の５.５というのは、それぞれ、例えば４分の１のほうが診断で、４０分の５.５のほうが改修に当てられるという認識でいいんでしょうか。","respondent":"片田建築課長","answer":"補助率についても、現在、このような動きかたをしておりますが、今後、国のほうの緩和等々の考え方も聞いておりますので、確認をしていきたいと考えています。","voiceIndex":182,"id":"exchange-074"},{"speaker":"武内委員","kind":"質問","question":"そうすると、耐震診断と耐震改修について、それぞれ国の補助率、それから、都の補助率、残りが区になると思うんですけれども、大体で結構なんですけれどもそれを教えていただけますでしょうか。","respondent":"片田建築課長","answer":"ここで記載されている数字については、若干整理した数字ですので、概略の耐震診断および改修の補助額といたしましては、基本的には、事業費ベースで考えた場合に、先ほど申し上げましたような、例えば事業費が１２万円の耐震診断であれば、自己が２分の１ということで。","voiceIndex":184,"id":"exchange-075"},{"speaker":"武内委員","kind":"確認","question":"私のほうで、ちょっとあらかたあれしたのは、診断も改修も、おおよそ国が半分、例えば、区民の方の自己負担分は除いて、例えば診断で言えば、６万円のうちの半分が国、残りの３万円のうちの都が４分の１、区が４分の１かなと思っていたんですけれども、そこだけ、もう１回ちょっと確認させていただけますか。","respondent":"片田建築課長","answer":"今申し上げた数字と別に、一つの考え方として、例えば、国のほうの診断の補助で申し上げれば、一つは区の補助額の２分の１という制約があります。","voiceIndex":186,"id":"exchange-076"},{"speaker":"武内委員","kind":"質問","question":"ちょっとわからないところは、また後で伺いたいと思います。歳出のほうには入りませんけれども、国のほうで、こういう形で、毎年補助率がアップしたりとか、また違う名前でいろいろな形で補助金が出てきていますけれども、今後の国の補助金の流れというか、補助率アップとかというところについては、どのようにお聞きでしょうか。","respondent":"片田建築課長","answer":"その辺、国のほうの支援策の拡充、規制の緩和等々を含めて、私どものほうとしても検討していきたいと考えております。","voiceIndex":188,"id":"exchange-077"},{"speaker":"武内委員","kind":"質問","question":"といいますのは、自転車の駐車場のほうでは、平成１８年度の決算では、バイクのほうは増えておりますが、自転車のほうは、例えば定期で言えば、当初予算で予定していた４万１,７００台に対して３万８,７３８台分しか駐車場料金が入っていないと。それとも、職員が一生懸命頑張っていただいたので、これだけ予算書以上に多く放置自転車が確保できたのか、これはどちらの考え方なんでしょうか。","respondent":"松嶋交通安全担当課長","answer":"これによりまして、撤去、保管、返還台数も減少するということを見込んだ上で計上していますけれども、放置がなかなかなくならない、あるいは、区民要望が多く、このニーズにこたえるために放置禁止区域外での撤去にも力を入れて行っているところでございまして。","voiceIndex":190,"id":"exchange-078"},{"speaker":"武内委員","kind":"質問","question":"１点だけ。そうなると、平成１９年度の予算づけでは、平成１８年度の決算で１万５,８００台近く実績があったのに対して、予算では１万４,０００台と減らしているわけですね。バイクについても、平成１８年度決算で３９４台あったのに、平成１９年度では２００台という予算づけをしているんですが、この辺の考え方を教えていただいて、終わりたいと思います。","respondent":"松嶋交通安全担当課長","answer":"この考え方につきましても、先ほど、ご説明いたしましたとおり、撤去活動等に力を入れてやれば、本来は放置自転車というのはだんだんなくなっていくということを見込んだ上で計上していたわけです。","voiceIndex":192,"id":"exchange-079"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、成果報告書の７４ページ、区民保養所に関連しての質問をします。それで、初めに何点かお伺いいたします。この中で、延べと書かれておりますので、私も区民の方々から、「あの人は何回も行っているよ」とか、そういうようなお話をときどきお聞きするんですけれども、リピーターに関しまして、割合等がわかりましたら、約で結構なんで、その辺をお教えいただきたい。","respondent":"鷹倉区民課長","answer":"品川荘全体の雰囲気がきれだという話ですけれども、あの建物でも既に何年か経ってきておりまして、これから計画的な修繕という形で、今回も外壁等をやっていくということで、今年も９月１日から１０月１２日を予定しております。","voiceIndex":195,"id":"exchange-080"},{"speaker":"原委員","kind":"質問","question":"褒めておいて下げちゃいけないのかもわかりませんけれども、では、質問の順番を変えまして、今、改修でちょっと手直しを入れるというお話なので、そちらのほうから伺いますけれども、私は、視察させていただいたときに、現地の管理者と従事者の職員ですとか、そういう面におきましては、非常に現場の声、または一生懸命頑張っておられるなということを感じたんです。","respondent":"鷹倉区民課長","answer":"そして今回、視察していただいた東京ケータリング、２回目のチャレンジということで継続してやっていただいておりますけれども、現場でかなり頑張っていただいていると思います。","voiceIndex":197,"id":"exchange-081"},{"speaker":"原委員","kind":"意見","question":"ほかに借上げの保養所等を区のほうでやっておられる、この辺のところにつきまして、今後の形ですね、具体的なことを申し上げちゃうと、数を増やしていくのか、このまま横ばいでいくのかという形、その辺等々、あとは極端な場合、品川荘、箱根荘ということではないにしても、不採算関係、先ほど申し上げたように、ある程度長い期間において、損益分岐点を割り込みそうなものであれば。","respondent":"鷹倉区民課長","answer":"箱根荘に関しましては、今回も暖房機の部分で、平成１９年度予算をいただいておりますけれども、必要最小限の修繕をする中で、やはりこれだけ利用率等が落ちている中で、少し見直しをかけていく必要があると考えています。","voiceIndex":199,"id":"exchange-082"},{"speaker":"原委員","kind":"質問","question":"そうしますと、これは質問ではなくてお願い事なんですけれども、広報等を通じて、メディア等いろいろなところの広告物だけではなくて、新しい分野から、もう少し区民の皆さんに広めていく、より多くの方に行っていただいて、効率を上げるということをお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-083"},{"speaker":"井上委員","kind":"提案","question":"例年で言いますと、明日からの歳出決算の中で、支出率をずっと読み上げていただくわけですけれども、これも４年前に見やすい決算書、予算書ということで、そういう見直しができるところから改善していただきたいということを提案していまして、歳出の部分においても、支出率を記入して、なるべく見やすく、早くこのことを分析したいという思いもありますし、区民も、これを見たときに。","respondent":"西島会計管理者","answer":"いずれにいたしましても、限られたスペースですので、そこの中でどれだけわかりやすく表現するかというのはなかなか難しいところはありますけれども、足りない分は、当日の口頭の中で説明をするということで、現段階ではやっているところです。","voiceIndex":203,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問・要望","question":"できるところから、なるべく改善をしていただきたいということを要望します。そこで、今回、増税分の１５億円、結果的には９２億円の増収になっているわけですが、ここの部分で、決算をした段階で、公がする事業ということをきちんと視点に置いた上で、区民の皆さんが幸せを実感できるということで、予算執行をこんなふうにしたという自己評価をしている部分があれば、教えてください。","respondent":"日下部企画財政課長","answer":"例えば区独自で、少子化の面では、すこやか児童手当の支給を開始する、あるいは区独自の不妊治療の相談助成制度を創設する、さらに学校避難所におきましても、自家発電装置の整備でありますとか、そういう形で、個々具体的に各施策の充実を図ってきたです。","voiceIndex":205,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"これからも、ここを見ていかなければいけないなと思っていますけれども、行政としても、ただできるからやるということではなく、区別をしていただきたいと要望します。それから、次は、３４ページの民生費負担金の保育園の保育料についての収入未済額について、どのように分析をされているのか伺います。","respondent":"小林保育課長","answer":"しかしながら、全体として、どうしても納めていただけないようなケースもありますので、引き続き督促、催告等を行って、その滞納額の解消に努めてまいっておるんですけれども、最終的に、不納欠損に至らぬように、今後も督促、催告。","voiceIndex":207,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問","question":"そういった場合に、督促状を出したりだけではなくて、相談がきちんとできているのか、相談される仕組みがあるのかどうかということを、お伺いをいたします。","respondent":"小林保育課長","answer":"そういった状況は、随時相談の窓口のほうでお受けして、ケースによっては、保育料の減免等も含めてご相談をしていますし、また、一部滞っている部分につきましては、少しずつ払っていただくということでお約束をいただくというような形で。","voiceIndex":209,"id":"exchange-087"},{"speaker":"井上委員","kind":"質問","question":"働いている中で、そういう困難事例の方たちというのは、大変時間的にもハードな中で、働きながら子育てをしているかと思うんです。３点目には、保育園の中で、園長だとか、区の関係の職員がいるわけですから、直接、そういう方たちに、保育料の相談まではいかなくても、そこに至るまでの困難な事例みたいなものを相談する場が持てているのか、どうなのか、３点、お伺いいたします。","respondent":"小林保育課長","answer":"それで、コンタクトがとれた部分について、お会いするときには、相手の就労の状況にあわせたお約束等をしておりますので、勤務時間外に来ていただくような例もやはり多うあります。それはそういった状況に応じて対応してまいりたいと思います。","voiceIndex":211,"id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"次に、６２ページの財産運用収入について、お伺いしたいと思います。基金の収入なんですけれども、一応、果実運用型基金ということで、一般財源化されて使われているわけですけれども、この部分で、各基金の一般財源に入った部分というのは、どういうふうに使うという約束事というか、ルールは持ち合わせているんでしょうか。","respondent":"日下部企画財政課長","answer":"果実運用型の基金につきましては、いろいろ種類がありますけれども、それぞれの目的に沿いまして、各事業の中に充当いたしまして、有効に活用しているというものです。","voiceIndex":213,"id":"exchange-089"},{"speaker":"井上委員","kind":"質問","question":"いちいち職員に、みどりの基金で言えば、１００万円はどう使われたんでしょうかと言っても、その１００万円がはっきりと見える部分ではないと思うんです。その辺のことで、改正というのはすごく大変なことでもないように思いますけれども、お考えがあればお聞かせください。","respondent":"日下部企画財政課長","answer":"ただ、品川区としましては、やはり、まとまった金額を長期にわたって有効に活用するという視点から、果実運用型というような形で、ちょっと息長くという視点で有効に活用していますので、ご理解をいただきたいと思います。","voiceIndex":215,"id":"exchange-090"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう部分で、実際にこういう基金が有効に、効果的に使われることというのは、いろいろ五百何億円の基金が、品川区にもあるわけですけれども、やはり有効に使うことも、ひとつこれから検討していかなければならないと思いますので、その辺は研究をしていただきたいと思います。具体的にはこれを例に挙げましたけれども、そういう事例の場合は、どのような考え方を持って進めていかれるとお考えでしょうか。","respondent":"高橋障害者福祉課長","answer":"障害児タイムケア事業ですが、この事業につきましては、歳出のほうで、やんちゃっこクラブ、もしくはにじのひろばというところで事業を運営しています。現在につきましても、にじのひろばにつきましては、事業を運営しているということで、必要ということで運営をしています。","voiceIndex":217,"id":"exchange-091"},{"speaker":"石田（慎）委員","kind":"質問","question":"主要施策の成果報告書の９８ページにあります諸収入の中で、雑入について、２点お伺いします。初めに、雑入のところの一番初めに私用電話料約６８万９,０００円と、私用光熱水費６,８７２万９,０００円、私用コピー料が５６５万円、これは一体、だれが、どこのものを使って支払われたものなのか、お聞かせください。","respondent":"中島経理課長、藤田道路公園課長、日下部企画財政課長","answer":"私用光熱水費ですけれども、６,８００万円のごく一部なんですけれども、約５８万円ですけれども、例えば。公園の中に自動販売機を設置しておりますのは、福祉団体のところが主で、そちらのほうからの歳入という形になっているものです。実は、今のご質問につきましては、各所管別に相当な項目にわたりますので、私のほうから一括してご説明をします。","voiceIndex":222,"id":"exchange-092"},{"speaker":"石田（慎）委員","kind":"質問","question":"それからもう１点、諸収入で幾つか項目がありますが、６番目の雑入で、さらに(5)でまた雑入と書いてあって詳しく内訳が書いてあるんですが、その一番最後にさらにまた雑入というのがあって、全体の歳入が１,３６２億円に対して、これが２億円ですから、そんなに大きくないのかもしれませんが、違う視点から見れば、２億円というのはものすごい額でして、この雑入の内訳というか。","respondent":"日下部企画財政課長","answer":"どうしても、項目として、金額も比較的小さいものを寄せ集めると、ということでありますけれども、例えばまちづくり事業部の関係で申し上げれば、水上バスステーションの利用料でありますとか、あるいは、住宅課のほうでまいりますと。","voiceIndex":226,"id":"exchange-093"},{"speaker":"石田（慎）委員","kind":"意見","question":"そうすると、例えば、金額がものすごく少ないものかもしれませんが、この中にも、２万円代のものだったり、３万円代のものだったりが実際に載っているわけでして、どのような判断で雑入という判断をとっているのか、お教えください。","respondent":"日下部企画財政課長","answer":"これについては、やはり項目としてでき得る限り実際の成果報告の調書の中に記載をして、議会のほうでは、これは決算についてご審議いただくわけですから、やはり項目としてきちんと出してご審議をしていただくと、そういう観点で。","voiceIndex":228,"id":"exchange-094"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、２億円の内訳の中に、一番大きい額のものは一体何なのかということを一つお教えいただければと思います。１件当たりというか、項目の中で一番金額の大きいものを教えてください。","respondent":"日下部企画財政課長","answer":"金額として一番大きいものは、実は、子どもすこやか医療費の高額医療費の返還金、これが金額としましては１,８００万円。これはちょっと金額が大きいんですが、これが最大のものです。","voiceIndex":230,"id":"exchange-095"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"今、政治とお金の問題とかもいろいろと言われている中ですので、もちろん品川区は健全な運営をしていると思いますが、その辺を要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８２ページの生活保護について、お聞きをしたいと思います。それにもかかわらず、今年７月、また５０歳代の男性が「おにぎりを食べたい」というメモを書き残して餓死すると、どうしてこんなことが次々と起こるんだと、ほんとうに異常な事態なんじゃないかと思うんですけれども、全国に衝撃が走っています。今の国の動きと、品川区の生活保護行政に対する姿勢について、まずお聞かせいただきたいと思います。","respondent":"志村生活福祉課長","answer":"ですから、私どもからしますと、そこの就労の支援につきましては、就労の支援員、ハローワークのＯＢではありますけれども、平成１８年度から２名に増やして、この辺のところの取り組みを、今までのケースワーカーだけではなくて。","voiceIndex":235,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、医療でも、介護でも、年金でも、社会保障がどんどん改悪をされて、負担が増やされて、ほんとうに追い詰められるという状況になってきていますので、ぜひ、セーフティネットをしっかりと機能させるというところでやっていただきたいと思いながら、具体的に質問をさせていただきたいと思います。それから、平成１８年度、廃止の世帯数と、人数、また、その理由についても教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"ただし、これは電話等の相談は含まれておりません。いわゆる面接記録としてペーパーに残したものです。それから、平成１８年度、保護を開始した件数は４９６件です。一方、廃止をしたのが５００件ということで、ここ数年来、初めて、廃止の数が開始の数を上回ったです。","voiceIndex":237,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"受理件数は４９６件ということなんですが、申請件数と受理件数というのは同じなんでしょうか。それから、廃止の世帯数は５００件ということですが、辞退届けというのは、品川区ではあるんでしょうか。あったら、何件あるのか。就業指導で仕事につくことで廃止になったという件数も、わかったら教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"申しわけありません、受理と開始したというのは同数です。それから、申請の前段階で何回か相談に来ていただいた、すみません、その数については、ちょっと把握しておりません。","voiceIndex":239,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その辞退届の人数は、わかったら教えていただきたいと思います。北九州市では、相談件数に対する受理件数とか、廃止件数の数値目標を設定して、ノルマのような形でやっているというのが問題だと、マスコミでは書かれておりましたけれども、品川区では、相談件数に対する申請数の申請率の目標数値とか、そういうことを決めてやっているのか、そのことについても、お聞かせいただきたいと思います。","respondent":"志村生活福祉課長","answer":"すみません、辞退件数につきまして、ちょっとお待ちください、今、調べております。それから、今のお尋ねの件につきましては、当然のことながら、そういった設定はございません。","voiceIndex":242,"id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ないということで、ほっとしました。私もいろいろ生活保護の相談を受けて、窓口にも一緒に行かせていただくということもあるんですけれども、申請というのは、どのように申請書を受け付けられるのか、このことをちょっと教えていただきたいんです。","respondent":"志村生活福祉課長","answer":"私どものほうで、先ほどお答えしたとおり、毎年１,５００件程度のいわゆる相談がまいります。その中には、確かに、先ほど申し上げたとおり、記録に残したのは１,５００件です。","voiceIndex":244,"id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、この申請というのは、本人が申請をしたいと意思表示をすれば受け付けなければいけないというのが、生活保護法の規定ではないかと思うんです。そこら辺のところの実態と、あるべき姿、そこら辺のところをお聞かせいただきたいと思います。","respondent":"志村生活福祉課長","answer":"お尋ねにあるとおりでございまして、私ども申請を受け付けてから２週間以内に保護の要否を決定するものです。２週間の間に、いろいろ調査をしなければならないという制約があります。","voiceIndex":246,"id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうしましたら、病気の場合のドクターの診断書ですとか、または通帳のコピーとか、こういうものは申請書を出した後、ということで確認させていただいてよろしいでしょうか。","respondent":"志村生活福祉課長","answer":"ただ、先ほど申し上げたとおり、いろいろな福祉の施策がありますので、その活用に当たっては、細かくお聞きするということになっておりますので、たまたまその経過の中でそういうようなことがあるかもしれませんけれども。","voiceIndex":248,"id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところを申し上げましたので、そこのところを確認を一つお願いしたいと思います。去年の１０月に、豊町での一家４人の心中事件が新聞でも取り上げられましたけれども、ここの中では、母親と長男が亡くなられて、長女が重体という痛ましい事件、その後亡くなったんですか、そういうことで報道されました。","respondent":"志村生活福祉課長","answer":"いわゆる生活保護の運用といいますか、適正な運用はどうしたらいいのかというような視点から、いろいろ細かくお聞きして、これからも適正な対応をとっていきたいと考えています。","voiceIndex":250,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一人ひとりが大変な問題を抱えた方が見えるわけですから、ほんとうにすごく苦労も多いお仕事だと思いますけれども、でも、その生活保護の申請に来られる方が、やっぱり一大決心をして来るという、そこら辺のところをしっかりと見ていただいて、一人ひとりの命がかかった、人生がかかっているというところでの対応を、ぜひお願いしたいと思います。辞退届については、まだわからないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-105"},{"speaker":"山内委員","kind":"質問・要望","question":"報告書の８６ページの教育費補助金、教具費について、ちょっとお尋ねをさせていただきたいと思います。国庫補助基本額が、小・中学校合わせて約３００万円と、ここで計上されていますが、この内訳というか、何を、どのような目的があって購入したのかという、内容的なものを教えていただきたいと思います。","respondent":"古里学務課長","answer":"内容的には、理科設備としては、振り子の実験機ですとか、高感度上皿天秤、そのほか流水の動き実験機ですとか、百葉箱、天体投影機、デジタル双眼実体顕微鏡等々が購入されておりますので、その合計額が３１４万２,４００円。このうちの３分の１が補助になったという内容です。","voiceIndex":254,"id":"exchange-106"},{"speaker":"山内委員","kind":"質問・要望","question":"今、考えたんですけれども、例えば実習を多くやるとか、履修の内容とか、そういうものを大事にしていただきたいなと思っているんですけれども、先生の気持ちの問題とか、そういうものに対して、何か教育委員会のほうからはお話とかしているんでしょうか。","respondent":"古里学務課長","answer":"この補助申請につきましては、それぞれ学校側に問い合わせをいたしまして、学校側が、その学校における教育課程の中で、このような道具があれば、ということで申請をしてきているものですので、学校側の意識によって申請がされているです。","voiceIndex":258,"id":"exchange-107"},{"speaker":"山内委員","kind":"質問","question":"今の説明で何となくわかるんですが、申込みをした際に、こういう授業をしたい、こういう特色のある授業をしていきたいというような、例えば書類での報告書とか、ＰＲとか、そういうものはあえて教育委員会のほうでは要求はしないのでしょうか。","respondent":"古里学務課長","answer":"理科教育振興法そのものが、委員おっしゃったような、さまざまな理科教育振興ということでされておりますので、その制度の趣旨自体は、学校側はよく理解をしていますので、その理解の中で、それぞれの学校で理科授業、あるいは、算数。","voiceIndex":260,"id":"exchange-108"},{"speaker":"山内委員","kind":"質問","question":"たまたまなんですけれども、きのうの広報「しながわ」に、１８歳以上の方で、理科に興味のある方に募集をかけますというような記事が出ていたんですけれども、今、理科に限定して話をしていますけれども、理科の教材等を、そういうような形でいろいろな学校に普及をし、そして、教員というか、指導者というか、そういうものもこれから増やしていくというか、そういう考えがあるのか、その辺については。","respondent":"河野指導課長","answer":"教員の資質向上に関しては、夏休みに、教育会のほうに委託をいたしまして、理科の実技研修会というような形で、さまざまな実験、観察等の研修を行って、資質の向上を図っているところです。理科の教員の増員については、検討課題とさせていただきたいと思います。","voiceIndex":262,"id":"exchange-109"},{"speaker":"山内委員","kind":"質問・要望","question":"理科関係はわかりましたのであれなんですけれども、先ほど、いろいろな教具の説明がございました。いろいろな教材を各学校で購入をし、そしてそれを活用するという中で、私、考えるに、いわゆる学校指導の教材等は非常にお金のかかるものではないかと考えるんです。この件につきまして、ちょっとお答えをいただきたいと思うんです。","respondent":"古里学務課長","answer":"それぞれの学校、近隣の学校においてですけれども、教材教具につきましては共有化を図っております。学務課でも、それの運搬に必要な経費は予算計上して運用しています。","voiceIndex":264,"id":"exchange-110"},{"speaker":"若林委員","kind":"質問","question":"私は、成果報告書６９ページの特別区民税、それから、８３ページの保健事業費につきまして、質問します。投資的経費、それから、消費的経費、これの別になっている一覧といいますか、そういうものが存在するのか、この決算書の中でどれがどうというのは無理ですので、そういうものが存在するのかどうか、１回、ちょっとお聞きしたいと思いますので、それだけ。","respondent":"日下部企画財政課長","answer":"これは、その性質別で大括りをしているものでございまして、これを具体的に項目として細目がわかるようなものは、特段、今回も出しておりません。ですから、その辺については、どういう出しかたができるかも含めまして、受けとめさせていただきたいと思います。","voiceIndex":269,"id":"exchange-111"},{"speaker":"若林委員","kind":"質問・要望","question":"６９ページの特別区民税。ここから、特に区民の負担等から見える今後の品川区という観点で、ご質問をさせていただきたいんです。その前段といたしまして、平成１６年度から平成１８年度にかけまして、いわゆる三位一体改革が進められました。来年度以降の税収の影響についても、三位一体改革の影響ということも含めて、総括といいますか、まとまったお話を伺いたいと思います。","respondent":"日下部企画財政課長","answer":"本格的な税源移譲ということで、住民税のフラット化によりまして、所得税が移転をするということになります。ただ、これは先ほどのご質問でもご説明させていただきましたが、区の側にとりましては、トータルで大体１億６,０００万円ぐらいのマイナスになるです。","voiceIndex":271,"id":"exchange-112"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、先ほど、マイナス２０億円というご答弁が、他の委員の質問の中でありましたけれども、平成１９年度以降、恒常的にマイナス２０億円というのが区のほうに残ってしまうという言い方で正しいんでしょうか。","respondent":"日下部企画財政課長","answer":"基本的には、そのようなことで受けとめていただきたいと思います。","voiceIndex":273,"id":"exchange-113"},{"speaker":"若林委員","kind":"質問","question":"毎年２０億円、恒常的に収入がなくなるです。その中で、税制改革によりましてというんでしょうか、いわゆる地方特例交付金もなくなって、今の２０億円の中にもう既にセットになっておりますので、細かい内容はあれなんですが、一つ疑問点といたしまして、成果報告書の７２ページに地方特例交付金が載っております。減税補てん特例交付金２２億円、それから児童手当の特例交付金というのも入っております。","respondent":"日下部企画財政課長","answer":"平成１９年度には定率減税が全廃されますので、本来であれば、地方特例交付金は全廃されるということで、私どもも考えておりましたら、国のほうで、一定の経過措置といいますか、激変緩和といいますか、それで、３年間、平成２１年度までは地方特例交付金が残るです。","voiceIndex":275,"id":"exchange-114"},{"speaker":"若林委員","kind":"質問","question":"参考までに、ちょっと横にそれちゃうかもしれませんけれども、児童手当については、国、都のほうからも、補助という形なんでしょうか、ほかのページで出てきておりますけれども、今後、ここに組み込まれるという性質のものではないんですね。","respondent":"日下部企画財政課長","answer":"そのようなことにはなってございません。","voiceIndex":277,"id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"児童手当のことは終わります。先ほどの話の続きですけれども、区民への影響というところで、もう１点、これは単純にお聞かせいただきたいんですが、いわゆる今回の住民税のフラット化によりまして、１０％になったと。実際は、ほんとうにそうなのかと。","respondent":"日下部企画財政課長","answer":"ですから、例えば、品川区がマイナス１億６,０００万円になるというのも、実は、単純な税源移譲だけであれば、区のほうが若干増える予定だったんですが、調整控除、つまり所得税のほうが調整措置の額が大きい、住民税のほうが小さい。","voiceIndex":279,"id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"次がありますので、そういう形で、極力変わらないようにフラット化を図ったということで理解をいたします。やはりまち中でそういうお声を多く聞き、国の税の体系の変化によって、区民の一定の方々、また多くの方々に負担が増えたんだという実態を目の当たりにいたしまして、あえて私どもで区の対応について要望をさせていただいた経緯があります。","respondent":"日下部企画財政課長","answer":"住民税への移行というような形にはなっているわけですけれども、区長も施政方針の中で表明をしておりましたけれども、実際には増税にはなっていないはずなんですが、実は、定率減税の関係もありまして、やはり実額が増えるような形になっている。","voiceIndex":281,"id":"exchange-117"},{"speaker":"若林委員","kind":"意見","question":"そのご努力、さらには平成１９年度、平成２０年度に向かっての方策になると思いますけれども、午前中の質疑の中でも、特別区税のうち区民税に関しては、１５億円ほどの増収があったというお話がございました。","respondent":"日下部企画財政課長","answer":"区のほうといたしましては、今の社会、経済の動き、全体をとらえながら、福祉の増進を図っていくという基本的な考え方に変わりはございませんけれども、具体的にまた、来年度以降、何をどうしていくかということにつきましては、今後、予算編成等も含めまして。","voiceIndex":283,"id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"これは、都知事のお話によると、決して福祉施策が後退をしたのではなくて、それは、例えば軽減額が７００円程度にとどまるということで大変に効果が薄いんだと、逆によりよい施策、サービスを、今後、そういう社会的な弱い立場の方々に施していくと、こういう考え方を表明されたと伺っております。８３ページの保健事業費につきましては、これは端的に、保健事業費は各ページにたくさん出てきております。","respondent":"太田健康課長","answer":"８９ページについては、東京都の民生費の負担金ということでございまして、衛生費負担金についても、区民健診の部分のものです。それから、がん健診については、平成１０年に一般財源化されておりますので、ここには振り分けはされてございません。","voiceIndex":285,"id":"exchange-119"},{"speaker":"本間委員","kind":"質問","question":"成果報告書の７４ページ、歳入の総務使用料、区民斎場使用料について、７６ページ、土木使用料、自転車駐車場使用料とあわせて放置自転車等保管料です。それから、１００ページ、水族館運営費収入、時間があれば、８５ページからの都市計画道路整備費、補助１６３号線の件について、お願いします。都市計画道路の関係なんですけれども、平成２０年度を目標に着々と整備が進められてきております。","respondent":"浜脇街路事業担当課長","answer":"今の状況ですけれども、進捗状況といいますか、用地の取得状況におきましては、都市整備公社等も活用しておりますので、今、９２％の用地を取得しているふうになっております。残りは８％ということで、平成２０年度の完成に向けて、鋭意努力しています。","voiceIndex":288,"id":"exchange-120"},{"speaker":"本間委員","kind":"質問・要望","question":"８％ということではありますけれども、目に見える部分と、目に見えない部分とがありまして、むしろ目に見えない部分の細かいところの、土地が中途半端にまたがっているというようなところもあろうかと思いますが、十分な話し合いを進めながら、平成２０年度を目標にお願いしたいと思います。そのような中で、どのようなご苦労といいますか、努力の経過があったのでしょうか。簡単に説明していただきたい。","respondent":"藤田道路公園課長","answer":"その効果もございまして、平成１８年度、私どももその後、アザラシ館をオープンいたしました。アラザシ館のオープンの後につきましては、対前年をおおむね１０５％というような形で推移をいたしまして、大変多くのお客様にきていただいたところです。","voiceIndex":290,"id":"exchange-121"},{"speaker":"本間委員","kind":"質問・要望","question":"返還数が１万６,５６５台とのことですが、いわゆる自転車の再生利用数が９６９台とありますが、この自転車の行き先はどうなっているのか。そして、処分数が１万１,６３０台になっていますが、これはどのような形で処分されるのかということを教えていただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"続きまして、処分品です、１万１,６００台程度あるんですけれども、これにつきましては、自転車につきまして、すべて売却になっているところです。バイクにつきましては、平成１８年度は、すべて、こちらで処分費を払って処分ということでやっております。","voiceIndex":292,"id":"exchange-122"},{"speaker":"本間委員","kind":"質問・要望","question":"地域の住民の皆さんとのトラブルの中で、公共の土地を使って何だとかという部分も聞いておりますので、その辺、今後のありようとして、研究、検討していただきたいと思います。それから、総務使用料の区民斎場の件です。この利用状況につきましては、２３７件、利用率６０.９％ということになっておりますけれども、この中身について、一度、評価といいますか、ご見解をいただきたいと思います。","respondent":"鷹倉区民課長","answer":"臨海斎場との絡みで、というご質問かと思います。確かに、臨海斎場が平成１６年にできております。いろいろ利用されているわけですけれども、その意味からいきまして、なぎさ会館の利用が、平成１５年度から平成１６年度にかけて、ここで落ち込んでおります。","voiceIndex":294,"id":"exchange-123"},{"speaker":"本間委員","kind":"質問","question":"３階の和室、お清めのところになりますけれども、どうも周りの状況を見てみますと、高齢者の皆さんが入口で立ち止まったり、あるいは手前の柔らかいソファーのところで腰掛けたまま動かない状況が続いていました。これは、なぎさ会館の件だけなくて、ほかのところでもそういうようなご意見をいただいておりますが、今、幾つか言いました件につきましてのご見解がありましたら、お願いします。","respondent":"鷹倉区民課長","answer":"施設的なものにつきましては、計画的にやっている部分があります。トイレも、今、確かに腰かけ的なものが主流になりつつあるのかなと思われる部分もありますので、もう少しいろいろ、今のご見解も含めて調査を進めていきたいなと考えております。","voiceIndex":296,"id":"exchange-124"},{"speaker":"松澤委員","kind":"確認","question":"成果報告書の７３ページ、分担金及び負担金、庁舎管理費負担金と、７５ページ、使用料及び手数料、中小企業センターの行政財産使用料、それから、８０ページの土木手数料、建築確認手数料についてお伺いをしたいと思います。","respondent":"中島経理課長、金子産業振興課長","answer":"総務費負担金の庁舎管理費負担金につきまして、ご説明を申し上げます。中小企業センターの行政財産使用料の内容ですけれども、こちらは、商店街連合会以下五つの団体につきまして、私どもで使用許可をしまして、それぞれ使用料をいただいているという内容のものです。","voiceIndex":300,"id":"exchange-125"},{"speaker":"松澤委員","kind":"確認","question":"庁舎のほうですけれども、負担金ということですので、これから庁舎の耐震工事が始まりますけれども、当然、これについては負担が当然あるんでしょうね。その辺のことを伺いたいと思います。当然ながら、中小企業センターのほうは使用料ですから、今、耐震工事をして休んでいますけれども、これについては、この部分についての負担はないんでしょうね、その辺ことを、まず確認をしたいと思います。","respondent":"中島経理課長、金子産業振興課長","answer":"総合庁舎につきましては、来年、平成２０年度から工事着手の計画ですけれども、こちらの工事費につきましては、区分所有者であります法務局の出張所、それから東京都につきましては、当然、負担をしていただくです。私どもにいわばテナントとして入っていただいているこの団体については、工事費の負担はしていただいておりません。","voiceIndex":303,"id":"exchange-126"},{"speaker":"松澤委員","kind":"質問・要望","question":"中小企業センターのほうですけれども、テナントとして入って、使用料をいただいているということなんですけれども、平成１７年度に比べると大幅に下がっていますよね。何でこんなに下がっているのかということと、当然、電気とか、ガスとか、水道とか、みんな入るんでしょうけれども、その内容についてお知らせをいただきたいと思います。","respondent":"金子産業振興課長","answer":"行政財産の使用料に関しましては、３年に一度の見直しをしておりまして、ちょうどその節目が平成１８年度でございました。ご案内のとおり、土地の評価額等々、下落の状況にありましたので、この行政財産の使用料についても下がったです。","voiceIndex":306,"id":"exchange-127"},{"speaker":"松澤委員","kind":"質問・要望","question":"観光協会は最近入りましたけれども、いろいろな団体が、こういうのがあるんなら、私たちも入りたいと言ったときに入れるのかどうか。これの入居基準というんでしょうか、入居条件というんですか、当然、新しく入ったりしているわけですから、出入りについても、どこかで基準があって考えるときがあるかと思うんですが、その辺のお考え方をお聞かせいただきたいと思います。","respondent":"金子産業振興課長","answer":"現在、私どものセンターに新しく入りたいというお申し出をいただいている団体はありませんので、今後、そういうような団体がございましたら、検討していくようになると考えております。","voiceIndex":308,"id":"exchange-128"},{"speaker":"松澤委員","kind":"確認","question":"建築確認手数料、これも昨年に比べて大幅に増えていますよね。原因は幾つか考えられると思うんです。一つは、手数料を上げたんじゃないかとか、あるいは、民間に比べて信用が増して、品川区の建築確認をとる人が増えたんじゃないか、あるいは、景気がよくなって全体のパイが広がって、建築確認の件数が増えたんじゃないかとか、いろいろありますけれども、この増えたことについての分析を、お願いいたします。","respondent":"片田建築課長","answer":"ただ、今年６月に法改正が改めて施行された中で、平成１８年度はこういう状況ですけれども、平成１９年度の状況で、現時点で、ちょっとかなり厳しい状況があります。","voiceIndex":310,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問・要望","question":"建築確認について、やっぱり信頼性が高まっているということで、頑張っていただきたいと思います。これは、確認申請もとらずに建てて、私も呼ばれて行ったんですけれども、赤紙を張られて標識をかけられているのにどんどん建てて、３階まで建っちゃっているよと、私たちもいろいろびっくりしたんです。相当苦労されたと思うんですが、これの対応経過について、お伺いしたいと思います。","respondent":"片田建築課長","answer":"私どものほうも適正な行政指導をしたいということで、６月初旬から工事の停止命令をかける、あわせて、７月の初旬には現場のほうに標識を設置するということで指導してきた経過があります。","voiceIndex":312,"id":"exchange-130"},{"speaker":"松澤委員","kind":"確認","question":"大変な努力をされたと思いますけれども、最後のまた適正な許可の条件で建築確認をということですが、今、また建てますということで周りに回っているんですよね。あれだけのことをして、建築違反して赤紙を張られて、立て札まで立てられて、どんどん無視して３階まで建ち上げてきて、それが指導によってやっと取り壊した、でもまた改めて確認を出せば、それが通るんだというのは、どうもわからない。","respondent":"片田建築課長","answer":"ただ、現実的に、なかなか立証が、現時点で難しいところも一つはありますけれども、ただ、建主に対してはかなり厳しい指導をした中で、解体を行っていただいた。ただ、区のほうとしては、適正に法を守った中で進めていただきたいと。","voiceIndex":314,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問・要望","question":"実際に３階まで建ち上がりつつあったのを取り壊させたというのは、これは大変な努力であり、成果だと思いますけれども、二葉三丁目はやはり危険地域ということで、いろいろな行政の網をかけて、道路を広げようとか、いろいろやっているところですから、ここについての建物については、新しく許可を与えても、しっかりと見ていただいて、近所の方が納得するような形で建てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":316,"id":"exchange-132"},{"speaker":"南委員","kind":"質問・要望","question":"教育費の補助金のほうは、国庫補助金として７０万３,０００円計上されておりますけれども、国がこういう補助金という形でつけている意味、そしてちょっと構造的によくわからないので、改めて伺いたいんですが、国庫補助金がついているものは、東京都の補助金もついていいのかと思っているんですけれども、そこが見当たらなかったので、その辺もあわせて教えていただきたいと思います。","respondent":"富田生涯学習課長、古里学務課長","answer":"伊藤学園について、特に今年の夏の状況ですので、日野学園とあわせて、今年度の７、８月の利用状況ということについて、お話をします。７月につきましては、学校枠というものがいずれもあります。それからもう一つは、特殊教育就学奨励費補助金ということでございまして、こちらは、品川区内にお住まいの養護学校に通っている子どもたちに対する就学奨励費ということで、４９万３,０００円の補助金対象になっておりまして。","voiceIndex":318,"id":"exchange-133"},{"speaker":"南委員","kind":"質問","question":"プールのほうなんですけれども、かなり利用実態がありますけれども、７月については、学校枠が２１％、２３％ということです。先ほどのご説明でも、学校枠が７月だけで二十数％ということなので、夏休み期間も、その学校に通学している子どもたちを対象にして、普通の一貫校以外の学校が行っているようなプール教室をやっているのかどうかを、端的に伺いたいと思います。","respondent":"古里学務課長、藤森小中一貫教育担当課長","answer":"都の補助金が、ですが、これは、法律に基づく補助金ですが、東京都のほうは一般財源化されておりまして、財調制度の中で措置されているために、この中に入っておりません。一貫校におきます夏休みのプール指導ですけれども、伊藤学園、日野学園ともに、夏季休業中のいわゆる、どこの学校でもやっている夏休みのプール指導というものは行っておりません。","voiceIndex":321,"id":"exchange-134"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろと調べてみると、生活保護費の保護費のところで、そういう標準服を購入できるような配慮、対応がされていると聞いておりますけれども、そうなれば、生活保護を受けておられる方たちはまあいいんですが、生活保護まで至らない、しかし、所得が低くて教育費がなかなか厳しいというご家庭には、就学援助をやっぱり出していくべきだと思うので、その辺の見解もあわせて伺いたいと思います。","respondent":"藤森小中一貫教育担当課長、古里学務課長","answer":"１点目の、日野学園、伊藤学園の夏のプールの件ですけれども、そもそも、委員のほうからは、規則的な生活をするためにプール指導があるというようなご案内ですけれども、まずは、夏休みのプールというのは。生活保護費の中で措置されているです。私どもも、この情報を受けております。ただ、就学援助は法律に基づいて措置されている内容があります。そうしたことも研究をしながら検討してまいりたいと、現在、考えているところです。","voiceIndex":324,"id":"exchange-135"},{"speaker":"南委員","kind":"質問・要望","question":"プールのほうなんですけれども、私は、夏休みのところで必要じゃないかという認識を持ち、その点について伺ったんです。通年でやることは全然否定しないし、むしろ、いいんじゃないかなと思います。一般開放しているところだって、一部のコースを割り当ててやればいい話ですから、そういうことをぜひ検討していただきたいと考えていますけれども、見解を伺います。","respondent":"藤森小中一貫教育担当課長","answer":"そういった意味で、夏はそのサマースクールに重点的に取り組めるということで、保護者や教員からも評価をいただいているところです。","voiceIndex":327,"id":"exchange-136"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうからは、成果報告書の７５ページ、４項の産業経済使用料について、お伺いをいたします。したがって、使用料等も含めまして、この件の現況についてお知らせいただきたいと思います。平成１７年４月に開設をされました天王洲の創業支援センターも、約１４２万円ほど減少となっておりますけれども、これも使用料等を含めまして、現況についてお知らせいただければと思います。","respondent":"金子産業振興課長","answer":"その関係で、当初予定した予算よりも若干減少してしまうということが、その原因です。","voiceIndex":331,"id":"exchange-137"},{"speaker":"堺委員","kind":"質問","question":"ですから、単純に計算しちゃいますと、平成１７年度の残金が、もう１回、収入未済で２７０万円で、不納決損が５００万円、合わせると、ほんのわずかな差しかないんですが、その辺の入りくりというんでしょうか、平成１７年度末はこういう現状だったけれども、平成１８年度は新たにこの収入未済額が出てきて、不納欠損が５００万円と、こういうふうになっていったのか。","respondent":"金子産業振興課長","answer":"これは、先ほど、別の議員からも質問がありましたとおり、もはや確実に入る見込みはない、それから、時効が成立したということで、平成１８年度、不納欠損で落とさせていただいたものですので、そういう意味では。","voiceIndex":333,"id":"exchange-138"},{"speaker":"堺委員","kind":"質問","question":"おそらく、１９カ月分ということになるのか、いわゆるここで１９件というのは、我々がどう理解をすればいいのか、ちょっとそれも教えていただけますか。","respondent":"金子産業振興課長","answer":"これは、ご指摘のとおり、２社で計１９カ月分です。","voiceIndex":335,"id":"exchange-139"},{"speaker":"堺委員","kind":"質問","question":"ですから、こういう不納欠損という形で計上しないように、いわゆる徴収努力というのは、当然されてきたんだろうとは思いますが、残念ながら、結果としてこうなってしまったと思うんですが、やっぱり、品川区の財源確保といいましょうか、そういう面で、どのようなご努力をされてきたのか、大変酷な話かもしれませんが、多分、課長のことですから、一生懸命徴収努力をなされてきたんだろうなとは思いますが。","respondent":"金子産業振興課長","answer":"２件でそれぞれ事情は違うんですけれども、一人の方につきましては、当初、滞納しがちであったところ、分割納付によって何とか追いかけていただいていたんですけれども、それもままならなくなりまして、最終的には退去をお願いして、その後。","voiceIndex":337,"id":"exchange-140"},{"speaker":"堺委員","kind":"確認","question":"要するに、使用料そのものに対する考え方につきまして、ちょっと確認をしておきたいんですが、現況のままで特に問題はないというのか、どうか、その辺含めて、お考えをお聞かせいただけますか。","respondent":"金子産業振興課長","answer":"この産業振興関係の施設につきましては、大きな目的として、品川区内の産業の振興ということがありますので、もちろん周囲の同等の物件の家賃等を調査し、また、通常は、３年に１回程度の見直しをかけて、適切かどうかといったものを勘案しながら、先ほど申し上げたとおり。","voiceIndex":339,"id":"exchange-141"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは前からちょっと、なぜだろうかと思っていたんですが、改めて、さっき、別の面で、決算書については書式が決まっているという部分もありましたけれども、私なんか、今年度が平成１８年度なんだから、監査報告書の平成１８、平成１７、平成１６年度というほうが見やすいなと思っていたんですけれども、その辺、何か特別な理由があるのか、どうか、簡単なことから、ちょっと教えてください。","respondent":"日下部企画財政課長","answer":"ただ一方で、５７ページでありますけれども、過去の経緯を追っていくということになりますと、左から右のほうへというのも一つの選択肢かなと。どちらが適正かということはございません。その辺はまた、今後、いろいろご指摘を受けとめていきたいと思います。","voiceIndex":342,"id":"exchange-142"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どっちかというと、私も、決算の見方のほうが楽かなと思うんです。ただ、やっぱり見ていて統一性がないというのは非常に疑問だと思っていたので、これを１点、指摘というと変ですけれども、質問をさせていただきました。歳入、歳出、数字を並べるとあれですけど、かなり違いが出ているんですけれども、一番大きな理由というのはどこら辺に出ているのか、その理由を、まず教えてください。","respondent":"日下部企画財政課長","answer":"２０４ページの決算統計、普通会計決算ベースでの数値につきまして、冒頭も説明をさせていただきましたけれども、あくまでも各自治体間で比較できるように、総務省が一つの基準を設けまして、それに従いまして取りまとめた中身です。","voiceIndex":344,"id":"exchange-143"},{"speaker":"鈴木（真）委員","kind":"意見","question":"翌年度に繰り越すべき財源が５,６５１万円というのが、決算の中に出てくるんですけれども、これが、４,５４７万２,０００円との決算概況、ここの数字というのは、何が違いが出てくるのか。","respondent":"日下部企画財政課長","answer":"こういうものについても、決算統計上はつけ加えるというルールになっておりますので、平成１８年度につきましては、それが１,１０３万８,０００円ありますので、その違いです。","voiceIndex":346,"id":"exchange-144"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もうちょっと数字だけ確認します。例えば基金だと、決算状況だと５２９億円、それが決算書だと５５０億円ぐらいに変わっている。それから、地方債として出されているものが決算状況は３８０億円、きょう出ている委員会の資料の残高でいうと４１０億円になっている。この辺も、統計上の流れなのか。区として考えていくのは、決算の数字で考えていっていいんでしょうね、そこら辺も教えてください。","respondent":"日下部企画財政課長","answer":"起債の関係なんですけれども、起債に関しましても、現在高は違っておりまして、これの一番大きな違いというのは、決算統計上は約３８０億円、実は、企画部のほうの委員会資料で出しておりますのは４１０億円ということなんですが、この３０億円というのは何かというと。","voiceIndex":348,"id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう一つ、二つだけ、財政力指数０.５２という、この数字をどう評価するか。先ほどの説明の中で、品川区全体的にいい決算を出しているという中での考え方と、それから、公債費比率が４.８％になっているのが、先日の新聞ですと、実質公債比率ということで数字が変わっていた。品川区はたしか４番目ぐらいに都市部で出ていたと思うんですが、その辺の判断、どういうふうにしていったらいいのか。","respondent":"日下部企画財政課長","answer":"ただ、今、委員からご指摘にありましたように、せっかくいい結果が出ているわけですから、できるだけ早い段階で、議会はもとより、区民の皆様方にもお知らせするような形で検討してまいりたいと考えております。","voiceIndex":350,"id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ほんとうは、事業部制について、ちょっとまたお聞きしたかったんですが、私の聞き方も悪かったんで、時間がもう間もなくになってしまったんですが、今朝ほど、区長のあいさつの中で、ちょっとそのときに控えたんですが、高橋区長が編成した予算に対する最後の決算というお言葉があったと思います。それから、平成２０年度に向けて、どのような考え方を持っていらっしゃるか、一言お願いしたいと思います。","respondent":"濱野区長","answer":"したがって、その健全な財政をしっかりと維持しながら、どうやってこれからの社会の変化に対応した政策を打って出るかということに尽きるのではないかと考えています。いずれにしましても、品川区の財政力を維持することは、私の大きな務めの一つだと考えています。","voiceIndex":352,"id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":108285,"voices":354}}]);
